// Inline SVG initials avatar (data URI) — zero network requests. The old placehold.co URLs fired an
// external image fetch per line item per order on every render, a big source of dashboard jank.
function createFallbackImage(itemName) {
    const initials = (itemName || 'N/A').split(' ').map(word => word[0]).join('').substring(0, 2).toUpperCase().replace(/[^A-Z0-9]/g, '') || 'NA';
    return 'data:image/svg+xml,' + encodeURIComponent(
        `<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100"><rect width="100" height="100" fill="#f1f5f9"/><text x="50" y="50" font-family="Arial,sans-serif" font-size="34" fill="#94a3b8" text-anchor="middle" dominant-baseline="central">${initials}</text></svg>`);
}

// Branded loaders — EVERY loading state shows the Pravidhi logo (spinning ring + logo).
// brandLoader = large centered (tables, KPI strips, modals) · brandLoaderSm = compact inline (small panels).
// ⚠️ brandLoader IS the app-wide loading popup now (user, 2026-08-27: "apply this same for entire
// software … loader design should same"). Every dashboard already calls it with its own label, so
// hooking it here gives all ~35 call sites the centred dark-premium card with zero per-page edits.
// It returns a MARKER shim for the container (keeps layout height, carries no visuals); a watcher
// polls for visible markers and hides the overlay the moment the last one is replaced by real
// content — which is exactly when the old inline loader used to disappear. A marker inside a
// hidden view (navigated away, closed modal) has no offsetParent and does not hold the overlay open.
let _eclWatch = null;
function _eclWatchStart() {
    if (_eclWatch) return;
    _eclWatch = setInterval(() => {
        let live = false;
        document.querySelectorAll('[data-ec-loading]').forEach(m => { if (m.offsetParent !== null) live = true; });
        if (!live) { clearInterval(_eclWatch); _eclWatch = null; ecLoadingHide(); }
    }, 300);
}
function brandLoader(label = 'Loading…') {
    try { ecLoadingShow(label); _eclWatchStart(); } catch (_) {}
    return `<div data-ec-loading class="py-10"></div>`;
}
// Centred loading POPUP in the app's dark-premium identity — the SAME card language as the welcome
// splash and the signout page (first cut was a bare white box; user: "this is not our standard").
// The page's previous content stays dimly visible behind the blur, so a refresh reads as updating.
function ecLoadingShow(label = 'Loading…') {
    if (!document.getElementById('ec-loading-style')) {
        const st = document.createElement('style');
        st.id = 'ec-loading-style';
        st.textContent = `
          @keyframes eclBackIn { from { opacity:0 } to { opacity:1 } }
          @keyframes eclCardIn { 0% { opacity:0; transform:translateY(16px) scale(.95) } 100% { opacity:1; transform:translateY(0) scale(1) } }
          @keyframes eclSpin { to { transform:rotate(360deg) } }
          @keyframes eclSheen { from { background-position:-200% center } to { background-position:200% center } }
          @keyframes eclDots { 0%,20% { content:'' } 40% { content:'.' } 60% { content:'..' } 80%,100% { content:'...' } }
          #ec-loading-overlay .ecl-label::after { content:''; animation:eclDots 1.6s steps(1) infinite; }
          @media (prefers-reduced-motion: reduce) { #ec-loading-overlay * { animation-duration:.01ms !important; animation-iteration-count:1 !important } }`;
        document.head.appendChild(st);
    }
    let el = document.getElementById('ec-loading-overlay');
    if (!el) {
        el = document.createElement('div');
        el.id = 'ec-loading-overlay';
        el.style.cssText = 'position:fixed;inset:0;z-index:120;display:flex;align-items:center;justify-content:center;padding:1.25rem;background:rgba(8,11,26,.45);-webkit-backdrop-filter:blur(7px);backdrop-filter:blur(7px);animation:eclBackIn .35s ease both;';
        document.body.appendChild(el);
    }
    el.innerHTML = `
      <div style="position:relative;display:flex;align-items:center;gap:22px;max-width:calc(100vw - 32px);padding:26px 38px 26px 28px;border-radius:22px;color:#fff;background:linear-gradient(165deg,#211d54,#111536 60%,#0b0f26);border:1px solid rgba(129,140,248,.28);box-shadow:0 40px 90px rgba(49,46,129,.55),inset 0 1px 0 rgba(255,255,255,.06);animation:eclCardIn .45s cubic-bezier(.2,.9,.25,1.1) both;">
        <div style="position:relative;width:64px;height:64px;flex:none;">
          <span style="position:absolute;inset:-7px;border-radius:24px;border:3px solid rgba(129,140,248,.18);border-top-color:#818cf8;border-right-color:rgba(129,140,248,.45);animation:eclSpin 1s linear infinite;"></span>
          <img src="/static/assets/pravidhi-icon.png" alt="" style="position:relative;width:64px;height:64px;border-radius:18px;box-shadow:0 18px 45px rgba(99,102,241,.5);">
        </div>
        <div style="display:flex;flex-direction:column;min-width:0;">
          <p style="margin:0;font-size:.66rem;letter-spacing:.3em;text-transform:uppercase;font-weight:700;color:#a5b4fc;">Please wait</p>
          <div class="ecl-label" style="margin:.3rem 0 0;font-size:1.15rem;font-weight:800;letter-spacing:-.01em;background:linear-gradient(90deg,#e0e7ff,#a78bfa 40%,#818cf8 68%,#e0e7ff);background-size:220% auto;-webkit-background-clip:text;background-clip:text;color:transparent;animation:eclSheen 3s linear infinite;">${escapeHtml(String(label).replace(/…$/, ''))}</div>
          <p style="margin:.35rem 0 0;font-size:.72rem;color:#8b93b8;">Pulling the latest data — this only takes a moment</p>
        </div>
      </div>`;
    el.style.display = 'flex';
}
function ecLoadingHide() { const el = document.getElementById('ec-loading-overlay'); if (el) el.style.display = 'none'; }
function brandLoaderSm(label = 'Loading…') {
    return `<div class="flex items-center gap-2 py-3"><span class="relative inline-flex items-center justify-center w-6 h-6 shrink-0"><span class="absolute w-6 h-6 rounded-full border-2 border-indigo-100 border-t-indigo-600 animate-spin"></span><img src="/static/assets/pravidhi-icon.png" class="w-4 h-4 rounded"></span><span class="text-slate-400 text-xs">${escapeHtml(label)}</span></div>`;
}

// Debounce: run fn only after `ms` of quiet — keeps typing smooth on heavy table re-renders.
function debounce(fn, ms) {
    let t;
    return function (...args) { clearTimeout(t); t = setTimeout(() => fn.apply(this, args), ms); };
}

// Escape HTML — prevents stored XSS when injecting server/customer data into innerHTML.
function escapeHtml(s) {
    if (s === null || s === undefined) return '';
    return String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

// --- NEW HELPER: CUSTOMER BADGE ---
function getCustomerBadge(email, phone, currentOrderId, precount) {
    if (!email && !phone) return '';
    // precount (prebuilt once in renderOrders) avoids an O(n) scan per row; falls back to a live scan.
    const count = (precount !== undefined) ? precount : allOrders.filter(o => {
        const matchEmail = email && o.email && o.email.toLowerCase() === email.toLowerCase();
        const matchPhone = phone && (o.phone || '').includes(phone);
        return matchEmail || matchPhone;
    }).length;
    if (count === 1) {
        return `<span class="ml-2 px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide text-emerald-600 bg-emerald-100 rounded border border-emerald-200">New</span>`;
    } else if (count > 5) {
        return `<span class="ml-2 px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide text-amber-600 bg-amber-100 rounded border border-amber-200">VIP (${count})</span>`;
    } else {
        return `<span class="ml-2 px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide text-indigo-600 bg-indigo-100 rounded border border-indigo-200">Repeat (${count})</span>`;
    }
}

// --- AUTHENTICATION ---

let _loginBusy = false;   // Enter fires BOTH the form submit and the keypress handler — post once
async function handleLogin() {
    if (_loginBusy) return;
    _loginBusy = true;
    _authMsg();                    // clear any previous error/notice
    showLoader();
    try {
        const response = await fetch('/api/login', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ email: loginEmailEl.value, password: loginPasswordEl.value })
        });
        const data = await response.json();
        if (!response.ok) throw new Error(data.message || 'Login failed');
        if (data.otp_required) { _otpShow(data); return; }   // 2FA: password OK → OTP step
        authToken = data.token;
        localStorage.setItem('authToken', authToken);
        afterLogin(true);
    } catch (error) {
        showNotification(error.message, true);
        _authMsg(error.message, false);   // persistent red alert on the login card
    } finally {
        _loginBusy = false;
        hideLoader();
    }
}
// Show / clear the shared inline message on the auth card. ok=true → green, false → red, no text → hide.
function _authMsg(text, ok) {
    const m = document.getElementById('auth-msg'); if (!m) return;
    if (!text) { m.classList.add('hidden'); m.textContent = ''; m.style.color = ''; return; }
    m.textContent = text; m.className = 'lv-msg'; m.style.color = ok ? '#86efac' : '';
}
// --- Password strength (shared by signup / forgot-reset / admin reset). Minimum is 8 chars;
//     anything shorter is "Too short" (score 0, blocked). 8+ is Fair, better = Good/Strong. ---
const PW_MIN = 8;
function pwStrength(pw) {
    pw = String(pw || '');
    if (pw.length === 0)   return { score: -1, label: '',          color: '',        pct: 0 };
    if (pw.length < PW_MIN) return { score: 0,  label: 'Too short', color: '#f43f5e', pct: 18 };
    const classes = [/[a-z]/, /[A-Z]/, /\d/, /[^A-Za-z0-9]/].filter(re => re.test(pw)).length;
    let pts = 0;
    if (pw.length >= 12) pts++;
    if (pw.length >= 16) pts++;
    if (classes >= 2) pts++;
    if (classes >= 3) pts++;
    const score = pts >= 3 ? 4 : pts >= 1 ? 3 : 2;   // 8+ = Fair, quality → Good, strong → Strong
    const meta = { 2: { l: 'Fair', c: '#f59e0b', p: 58 }, 3: { l: 'Good', c: '#3b82f6', p: 80 }, 4: { l: 'Strong', c: '#10b981', p: 100 } }[score];
    return { score, label: meta.l, color: meta.c, pct: meta.p };
}
function _bindPwMeter(input, meter) {
    if (!input || !meter) return;
    const bar = meter.querySelector('.pw-bar > span'), lab = meter.querySelector('.pw-label');
    const upd = () => {
        const s = pwStrength(input.value);
        if (s.score < 0) { meter.classList.add('hidden'); return; }
        meter.classList.remove('hidden');
        if (bar) { bar.style.width = s.pct + '%'; bar.style.backgroundColor = s.color; }
        if (lab) { lab.textContent = s.label; lab.style.color = s.color; }
    };
    input.addEventListener('input', upd); upd();
}

// --- 2FA OTP step (admin logins — OTP emailed, verified server-side) ---
let _otpToken = null, _otpTimer = null;
function _otpShow(data) {
    _otpToken = data.otp_token;
    document.getElementById('login-form')?.classList.add('hidden');
    document.getElementById('auth-toggle')?.classList.add('hidden');
    document.getElementById('otp-form')?.classList.remove('hidden');
    const h = document.querySelector('#login-view h1'); if (h) h.textContent = 'Verify it’s you';
    const hint = document.getElementById('otp-hint'); if (hint) hint.textContent = data.channel === 'whatsapp' ? ('WhatsApp ' + (data.wa_hint || '')) : (data.email_hint || 'your email');
    const inp = document.getElementById('otp-input'); if (inp) { inp.value = ''; inp.focus(); }
    _otpCountdown(30);
}
function _otpCountdown(secs) {
    const btn = document.getElementById('otp-resend'); if (!btn) return;
    clearInterval(_otpTimer);
    let left = secs;
    btn.disabled = true; btn.textContent = `Resend OTP (${left}s)`;
    _otpTimer = setInterval(() => {
        left--;
        if (left <= 0) { clearInterval(_otpTimer); btn.disabled = false; btn.textContent = 'Resend OTP'; }
        else btn.textContent = `Resend OTP (${left}s)`;
    }, 1000);
}
function _otpBack() {
    clearInterval(_otpTimer); _otpToken = null;
    document.getElementById('otp-form')?.classList.add('hidden');
    document.getElementById('login-form')?.classList.remove('hidden');
    document.getElementById('auth-toggle')?.classList.remove('hidden');
    const h = document.querySelector('#login-view h1'); if (h) h.textContent = 'Sign in to Pravidhi';
}
let _otpBusy = false;
async function _otpVerify() {
    if (_otpBusy) return;
    const otp = String((document.getElementById('otp-input') || {}).value || '').trim();
    if (!/^\d{6}$/.test(otp)) return showNotification('Enter the 6-digit OTP.', true);
    _otpBusy = true;
    showLoader();
    try {
        const r = await fetch('/api/login/verify-otp', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ otp_token: _otpToken, otp }) });
        const d = await r.json();
        if (!r.ok) throw new Error(d.message || 'OTP verification failed');
        authToken = d.token; localStorage.setItem('authToken', authToken);
        _otpBack();   // reset the login card for the next sign-in
        afterLogin(true);
    } catch (e) { showNotification(e.message, true); }
    finally { _otpBusy = false; hideLoader(); }
}
async function _otpResend() {
    if (!_otpToken) return;
    try {
        const r = await fetch('/api/login/resend-otp', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ otp_token: _otpToken }) });
        const d = await r.json();
        if (!r.ok) throw new Error(d.message || 'Could not resend the OTP');
        showNotification('OTP re-sent.');
        _otpCountdown(30);
    } catch (e) { showNotification(e.message, true); }
}

