// --- DASHBOARD FILTERS RENDERING — clean toolbar; containers live in index.html, JS just populates ---
function renderDashboardFilters() {
    // Shared pill-toggle style (platform + source), so both segmented controls look identical.
    const pill = (attr, val, active, label) =>
        `<button ${attr}="${val}" class="px-3 py-1.5 text-xs font-semibold rounded-md transition-all ${active ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}">${label}</button>`;

    // 1. Platform segmented control (All / Shopify)
    platformFiltersEl.innerHTML = ['All', 'Shopify'].map(p => pill('data-filter', p, activePlatformFilter === p, p)).join('');

    // 2. Source segmented control (All / RapidShyp / DocPharma) — container is in the HTML toolbar.
    const sourceContainer = document.getElementById('source-filters');
    if (sourceContainer) sourceContainer.innerHTML = ['All', 'RapidShyp', 'DocPharma'].map(s => pill('data-source', s, activeSourceFilter === s, s)).join('');

    // 3. COD-status dropdown
    const codFilterContainer = document.getElementById('cod-filter-container');
    if (codFilterContainer) codFilterContainer.innerHTML = `
        <select id="cod-filter-select" class="filter-select">
            <option value="All">All COD Status</option>
            <option value="Confirmed">✓ Confirmed</option>
            <option value="Waiting">Waiting…</option>
            <option value="Cancelled">Cancelled</option>
            <option value="No Data">No Data</option>
        </select>`;

    // 3b. Hold-status dropdown
    const holdFilterContainer = document.getElementById('hold-filter-container');
    if (holdFilterContainer) holdFilterContainer.innerHTML = `
        <select id="hold-filter-select" class="filter-select">
            <option value="All">All Hold Status</option>
            <option value="OnHold">⏸ On Hold</option>
            <option value="NotHeld">Not Held</option>
        </select>`;

    // 3c. Payment-method dropdown (COD vs Prepaid)
    const paymentFilterContainer = document.getElementById('payment-filter-container');
    if (paymentFilterContainer) paymentFilterContainer.innerHTML = `
        <select id="payment-filter-select" class="filter-select">
            <option value="All">All Payments</option>
            <option value="COD">COD</option>
            <option value="Prepaid">Prepaid</option>
        </select>`;

    // 3d. Customer-type dropdown (New vs Repeat)
    const typeFilterContainer = document.getElementById('type-filter-container');
    if (typeFilterContainer) typeFilterContainer.innerHTML = `
        <select id="type-filter-select" class="filter-select">
            <option value="All">All Customers</option>
            <option value="New">New</option>
            <option value="Repeat">Repeat</option>
        </select>`;

    // 4. Attach Listeners
    platformFiltersEl.querySelectorAll('button[data-filter]').forEach(b => {
        b.addEventListener('click', () => { activePlatformFilter = b.dataset.filter; renderAllDashboard(); });
    });
    
    sourceContainer?.querySelectorAll('button[data-source]').forEach(b => {
        b.addEventListener('click', () => { activeSourceFilter = b.dataset.source; renderAllDashboard(); });
    });

    const codSelect = document.getElementById('cod-filter-select');
    if(codSelect) {
        codSelect.value = activeCodFilter;
        codSelect.addEventListener('change', (e) => {
            activeCodFilter = e.target.value;
            renderAllDashboard();
        });
    }

    const holdSelect = document.getElementById('hold-filter-select');
    if(holdSelect) {
        holdSelect.value = activeHoldFilter;
        holdSelect.addEventListener('change', (e) => {
            activeHoldFilter = e.target.value;
            renderAllDashboard();
        });
    }

    const paymentSelect = document.getElementById('payment-filter-select');
    if(paymentSelect) {
        paymentSelect.value = activePaymentFilter;
        paymentSelect.addEventListener('change', (e) => {
            activePaymentFilter = e.target.value;
            renderAllDashboard();
        });
    }

    const typeSelect = document.getElementById('type-filter-select');
    if(typeSelect) {
        typeSelect.value = activeTypeFilter;
        typeSelect.addEventListener('change', (e) => {
            activeTypeFilter = e.target.value;
            renderAllDashboard();
        });
    }

}

// Repeat = Shopify 'repeat' tag OR the same phone/email appears on more than one order (the exact signal
// the row's New/Repeat badge shows). Sets `_isRepeat` on each order so the badge and the Type filter agree.
function computeRepeatFlags(orders) {
    if (!Array.isArray(orders)) return;
    const ph = o => { const p = o.phone || (o.shipping_address && o.shipping_address.phone) || ''; return String(p).replace(/\D/g, '').slice(-10); };
    const em = o => (o.email ? o.email.toLowerCase().trim() : '');
    const pc = new Map(), ec = new Map();
    for (const o of orders) {
        const p = ph(o); if (p) pc.set(p, (pc.get(p) || 0) + 1);
        const eaddr = em(o); if (eaddr) ec.set(eaddr, (ec.get(eaddr) || 0) + 1);
    }
    for (const o of orders) {
        const tags = (o.tags || '').toLowerCase();
        const p = ph(o), eaddr = em(o);
        o._isRepeat = tags.includes('repeat') || (!!p && pc.get(p) > 1) || (!!eaddr && ec.get(eaddr) > 1);
    }
}

// --- UPDATED RENDER DASHBOARD (With COD Filter Logic) ---
function renderAllDashboard() {
    const [s, e] = calculateDateRange(activeDatePreset, startDateFilterEl.value, endDateFilterEl.value);
    let o = [...allOrders];

    // Tag every order New/Repeat once (same signal the row badge shows) so the Type filter and the
    // badge always agree. Runs on the FULL set (not the filtered view) so repeat detection is stable.
    computeRepeatFlags(allOrders);

    // Helper to extract numeric ID for matching
    const extractNum = (str) => {
        if (!str) return '';
        const s = String(str);
        const match = s.match(/(\d+)$/); 
        return match ? match[0] : s.replace(/\D/g, ''); 
    };

    // 1. Date Filter
    if (s && e) {
        o = o.filter(t => { 
            const parts = t.date.split('-'); 
            const d = new Date(parts[2], parts[1] - 1, parts[0]); 
            return d >= s && d <= e; 
        });
    }

    // 2. Platform Filter
    if (activePlatformFilter !== 'All') {
        o = o.filter(t => t.platform === activePlatformFilter);
    }

    // 3. Status Filter — the 6 KPI buckets are filtered SERVER-SIDE (fetched by tracking_status), so skip
    //    them here; only the granular dropdown statuses (Shipped, Pickup Scheduled, …) filter client-side.
    if (activeStatusFilter !== 'All' && !STATUS_BUCKET[activeStatusFilter]) {
        if (activeStatusFilter === 'In Transit') {
            o = o.filter(t => {
                // Must be one of the moving statuses
                const isForwardMoving = ['Pickup Scheduled', 'Shipped', 'In Transit', 'Out For Delivery'].includes(t.status);

                // Check if it is actually RTO (by Tag or Status Text)
                const isRto = t.status.toUpperCase().includes('RTO') ||
                              (t.tags && t.tags.toLowerCase().includes('rto'));

                // Show only if moving forward AND NOT RTO
                return isForwardMoving && !isRto;
            });
        } else if (activeStatusFilter === 'New / Processing') {
            o = o.filter(t => t.status === 'New' || t.status === 'Processing');   // New/Processing KPI card
        } else if (activeStatusFilter === 'RTO') {
            o = o.filter(t => (t.status || '').toUpperCase().includes('RTO'));     // RTO card (incl. 'RTO Delivered')
        } else if (activeStatusFilter === 'Cancelled') {
            o = o.filter(t => t.status === 'Cancelled' || t.status === 'Lost');    // Cancelled card (excludes RTO)
        } else {
            o = o.filter(t => t.status === activeStatusFilter);
        }
    }

    // 4. Source / Shipping-Platform Filter (RapidShyp vs DocPharma).
    // Primary signal = EasyEcom `shipPlatform` (the synced `location`: 'docpharma' / 'rapidshyp');
    // falls back to the Shopify "docpharma: in-progress" tag for orders not yet in EasyEcom.
    if (activeSourceFilter !== 'All') {
        o = o.filter(order => isOrderDocPharma(order) === (activeSourceFilter === 'DocPharma'));
    }

    // 4b. Hold-status filter (EasyEcom On Hold)
    if (activeHoldFilter !== 'All') {
        o = o.filter(order => { const held = !!(order.eeHold || order.shopifyHold); return activeHoldFilter === 'OnHold' ? held : !held; });
    }

    // 4c. Payment-method filter (COD vs Prepaid)
    if (activePaymentFilter !== 'All') {
        o = o.filter(order => String(order.paymentMethod || '').toLowerCase() === activePaymentFilter.toLowerCase());
    }

    // 4d. Customer-type filter (New vs Repeat)
    if (activeTypeFilter !== 'All') {
        o = o.filter(order => activeTypeFilter === 'Repeat' ? !!order._isRepeat : !order._isRepeat);
    }

    // 5. [NEW] COD Status Filter
    if (activeCodFilter !== 'All') {
        o = o.filter(order => {
            const dashNum = extractNum(order.id);
            const codData = codConfirmations?.find(c => {
                const sheetNum1 = extractNum(c['Order Number']);
                const sheetNum2 = extractNum(c['Order Name']);
                return (sheetNum1 === dashNum) || (sheetNum2 === dashNum);
            });

            if (!codData) return activeCodFilter === 'No Data';

            const rawResponse = String(codData['Confirmation received'] || '').toUpperCase().trim();
            const status = String(codData['status'] || '').toLowerCase().trim();

            if (activeCodFilter === 'Confirmed') {
                return ['CONFIRM', 'YES', 'CONFIRMED', 'OK'].includes(rawResponse);
            }
            if (activeCodFilter === 'Cancelled') {
                return ['CANCEL', 'NO', 'REJECT'].includes(rawResponse);
            }
            if (activeCodFilter === 'Waiting') {
                // It is waiting if it's NOT confirmed AND NOT cancelled, but exists
                const isConfirmed = ['CONFIRM', 'YES', 'CONFIRMED', 'OK'].includes(rawResponse);
                const isCancelled = ['CANCEL', 'NO', 'REJECT'].includes(rawResponse);
                return !isConfirmed && !isCancelled;
            }
            return false;
        });
    }

    // 6. Search Filter
    if (currentSearchTerm) {
        o = o.filter(item => 
            (item.id && item.id.toLowerCase().includes(currentSearchTerm)) ||
            (item.name && item.name.toLowerCase().includes(currentSearchTerm)) ||
            (item.email && item.email.toLowerCase().includes(currentSearchTerm)) ||
            (item.phone && String(item.phone).includes(currentSearchTerm)) ||
            (item.shipping_address && item.shipping_address.phone && String(item.shipping_address.phone).includes(currentSearchTerm)) ||
            (item.awb && String(item.awb).toLowerCase().includes(currentSearchTerm)) ||
            (item.total && String(item.total).includes(currentSearchTerm))
        );
    }

    // Sort by the numeric `timestamp` the server provides — `date` is DD-MM-YYYY, which new Date()
    // can't parse (Invalid Date → NaN comparator → arbitrary order). Fallback parses DD-MM-YYYY.
    const _ordTs = x => (typeof x.timestamp === 'number' && x.timestamp) ? x.timestamp
        : (() => { const p = String(x.date || '').split('-'); return p.length === 3 ? new Date(+p[2], +p[1] - 1, +p[0]).getTime() : 0; })();
    const t = [...o].sort((a, b) => _ordTs(b) - _ordTs(a));
    
    renderDashboardFilters(); 
    renderSearchInput(); 
    
    renderOrders(t);
    updateDashboardKpis(o);
}

// --- FIXED SEARCH INPUT (Responsive Width) ---
function renderSearchInput() {
    // Prevent duplicate creation
    if (document.getElementById('search-container-custom')) return;

    const searchContainer = document.createElement('div');
    searchContainer.id = 'search-container-custom';
    searchContainer.className = 'relative group';

    // Search Icon & Input HTML — matches the 38px filter-control height for a clean toolbar row.
    searchContainer.innerHTML = `
        <span class="absolute inset-y-0 left-0 flex items-center pl-3 text-slate-400 group-focus-within:text-indigo-500 transition-colors pointer-events-none">
            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
        </span>
        <input type="text" id="global-order-search"
            placeholder="Search orders…"
            class="filter-input w-44 md:w-56 focus:w-64 transition-all duration-300"
            style="padding-left:2.25rem; padding-right:0.8rem;"
            autocomplete="off">
    `;

    // Drop it into the dedicated toolbar slot (falls back to the old parent if the slot's absent).
    const slot = document.getElementById('orders-search-slot');
    if (slot) { slot.innerHTML = ''; slot.appendChild(searchContainer); }
    else if (platformFiltersEl && platformFiltersEl.parentNode) { platformFiltersEl.parentNode.appendChild(searchContainer); }

    // Add Event Listener
    const inputEl = document.getElementById('global-order-search');
    if (inputEl) {
        // Restore focus/value if re-rendering
        if (typeof currentSearchTerm !== 'undefined') inputEl.value = currentSearchTerm;
        
        let _searchDebounce;
        inputEl.addEventListener('input', (e) => {
            currentSearchTerm = e.target.value.toLowerCase().trim();
            clearTimeout(_searchDebounce);
            _searchDebounce = setTimeout(() => {
                renderAllDashboard(); // Re-render table (debounced ~250ms so typing stays smooth)
                // Keep focus/caret after re-render (trick)
                const newInput = document.getElementById('global-order-search');
                if (newInput) {
                    newInput.focus();
                    newInput.setSelectionRange(newInput.value.length, newInput.value.length);
                }
            }, 250);
        });
    }
}

// --- ORDER LIST RENDERING (Trusts Shopify Tags + Local History) ---
let _ordersRenderToken = 0; // cancels an in-flight progressive render when a newer one starts
function renderOrders(o) {
    ordersListEl.innerHTML = '';
    _ordersById.clear();   // fresh map for the lazy detail-row builder
    updateBulkActionBar();

    if (o.length === 0) {
        const activeBits = [];
        if (activeHoldFilter === 'OnHold') activeBits.push('on-hold');
        if (activeSourceFilter !== 'All') activeBits.push(activeSourceFilter);
        if (activeStatusFilter !== 'All') activeBits.push(activeStatusFilter.toLowerCase());
        if (activeCodFilter !== 'All') activeBits.push('COD ' + activeCodFilter.toLowerCase());
        const hint = activeBits.length ? `No <b>${activeBits.join(' · ')}</b> orders in this date range.` : 'No orders match your filters.';
        ordersListEl.innerHTML = `<tr><td colspan="10" class="py-16 text-center">
            <div class="inline-flex flex-col items-center gap-2 text-slate-400">
                <svg class="w-10 h-10 text-slate-300" fill="none" stroke="currentColor" stroke-width="1.5" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"/></svg>
                <p class="text-sm">${hint}</p>
                ${activeBits.length ? '<p class="text-xs text-slate-300">Try widening the date range or clearing a filter.</p>' : ''}
            </div></td></tr>`;
        return;
    }

    // Helper: Extract Number from ID
    const extractNum = (str) => {
        if (!str) return '';
        const s = String(str);
        const match = s.match(/(\d+)$/); 
        return match ? match[0] : s.replace(/\D/g, ''); 
    };

    // Helper: Normalize Phone (Last 10 digits only)
    const cleanPhone = (p) => {
        if (!p) return '';
        return String(p).replace(/\D/g, '').slice(-10);
    };

    // --- Prebuild lookup maps ONCE (was O(n) scan per row → O(n²) total; now O(1) per row) ---
    const emailCountNoTrim = new Map(); // email.toLowerCase() -> count (matches getCustomerBadge)
    const phoneToOrders = new Map();    // last-10-digit phone -> [orders]
    const emailToOrders = new Map();    // email.toLowerCase().trim() -> [orders]
    for (const x of allOrders) {
        const xeb = x.email ? x.email.toLowerCase() : '';
        if (xeb) emailCountNoTrim.set(xeb, (emailCountNoTrim.get(xeb) || 0) + 1);
        const xp = cleanPhone(x.phone);
        if (xp) { let a = phoneToOrders.get(xp); if (!a) phoneToOrders.set(xp, a = []); a.push(x); }
        const xe = x.email ? x.email.toLowerCase().trim() : '';
        if (xe) { let a = emailToOrders.get(xe); if (!a) emailToOrders.set(xe, a = []); a.push(x); }
    }
    const codByNum = new Map();         // extractNum(order number/name) -> first matching COD row
    if (Array.isArray(codConfirmations)) {
        for (const c of codConfirmations) {
            const n1 = extractNum(c['Order Number']);
            const n2 = extractNum(c['Order Name']);
            if (n1 && !codByNum.has(n1)) codByNum.set(n1, c);
            if (n2 && !codByNum.has(n2)) codByNum.set(n2, c);
        }
    }

    const buildRow = (order) => {
        const displayName = (order.name === 'N/A' && order.buyerName) ? order.buyerName : order.name;
        const uniqueId = order.id.replace(/\W/g, ''); 
        const isSelected = selectedOrders.has(order.originalId);
        
        const custBadge = getCustomerBadge(order.email, null, order.id, emailCountNoTrim.get((order.email || '').toLowerCase()) || 0);

        const mainRow = document.createElement('tr');
        // DocPharma-rejected & not yet moved to our warehouse → red tint (needs action). Once handled
        // (auto-routed / logged move / already on Shifupro) → soft green.
        const _whMoved = order.warehouseChange || order.dpRejectHandled;
        const dpNeedsAction = order.docpharmaRejected && !_whMoved;
        const dpRouted = order.docpharmaRejected && _whMoved;
        const rowTint = dpNeedsAction ? 'bg-rose-50/70 hover:bg-rose-50' : dpRouted ? 'bg-emerald-50/40 hover:bg-emerald-50' : 'hover:bg-slate-50';
        mainRow.className = `order-row border-b border-slate-100 transition-colors ${rowTint} ${isSelected ? 'bg-indigo-50/50' : ''}`;
        if (dpNeedsAction) mainRow.classList.add('border-l-2', 'border-l-rose-400');
        mainRow.dataset.orderId = order.id;

        // =========================================================================
        // 1. GATHER DATA (Shopify Tags & Local History)
        // =========================================================================
        
        // A. Get Shopify Tags (Lowercase for easy checking)
        const shopifyTags = (order.tags || '').toLowerCase();
        
        // B. Calculate History (Strict Phone/Email Match)
        const currentPhone = cleanPhone(order.phone);
        const currentEmail = order.email ? order.email.toLowerCase().trim() : '';

        // Union of phone-matched and email-matched orders (deduped) — from prebuilt maps, O(1) per row.
        const _phMatch = currentPhone ? phoneToOrders.get(currentPhone) : null;
        const _emMatch = currentEmail ? emailToOrders.get(currentEmail) : null;
        let history;
        if (_phMatch && _emMatch) { const seen = new Set(_phMatch); history = _phMatch.concat(_emMatch.filter(x => !seen.has(x))); }
        else { history = _phMatch || _emMatch || []; }

        // =========================================================================
        // 2. DETERMINE STATUS FLAGS
        // =========================================================================
        
        // IS REPEAT? -> precomputed flag (Shopify 'repeat' tag OR same phone/email on > 1 order), so the
        // badge here and the New/Repeat filter always agree. Falls back to the local check if not yet set.
        const isRepeat = (order._isRepeat != null) ? order._isRepeat : (shopifyTags.includes('repeat') || history.length > 1);

        // IS DELIVERED CUSTOMER? -> (Shopify says 'delivered') OR (History has 'Delivered' status)
        const isDeliveredCustomer = shopifyTags.includes('delivered') || history.some(h => {
             const s = String(h.status).toLowerCase();
             // Check if any PAST order was delivered
             return (s === 'delivered' || s === 'completed') && String(h.id) !== String(order.id);
        });

        // =========================================================================
        // 3. GENERATE BADGE HTML
        // =========================================================================
        let tagsHtml = '';

        if (isRepeat) {
            tagsHtml += `<span class="inline-block px-1.5 py-0.5 text-[10px] font-bold text-indigo-600 bg-indigo-50 rounded border border-indigo-100 uppercase tracking-wide mr-1 mb-1">Repeat</span>`;
        } else {
            tagsHtml += `<span class="inline-block px-1.5 py-0.5 text-[10px] font-bold text-slate-500 bg-slate-100 rounded border border-slate-200 uppercase tracking-wide mr-1 mb-1">New</span>`;
        }

        // Show Delivered Badge (Independent check - fixes the missing badge issue)
        if (isDeliveredCustomer) {
            tagsHtml += `<span class="inline-block px-1.5 py-0.5 text-[10px] font-bold text-emerald-600 bg-emerald-50 rounded border border-emerald-100 uppercase tracking-wide mr-1 mb-1">Delivered</span>`;
        }

        // Influencer order — flagged from the "Influencer" tag / INFLUENCER company line (set by the Influencer CRM).
        if (order.isInfluencer || order.customerType === 'Influencer' || shopifyTags.includes('influencer')) {
            tagsHtml += `<span class="inline-block px-1.5 py-0.5 text-[10px] font-bold text-fuchsia-700 bg-fuchsia-50 rounded border border-fuchsia-200 uppercase tracking-wide mr-1 mb-1" title="Influencer shipment">Influencer</span>`;
        }

        // VIP Check
        if (history.length > 5 || parseFloat(order.total) > 5000 || shopifyTags.includes('vip')) {
             tagsHtml += `<span class="inline-block px-1.5 py-0.5 text-[10px] font-bold text-amber-600 bg-amber-50 rounded border border-amber-100 uppercase tracking-wide mr-1 mb-1">VIP</span>`;
        }

        // DocPharma rejected/cancelled — needs to be re-fulfilled from our warehouse.
        if (order.docpharmaRejected) {
            const moved = order.warehouseChange || order.dpRejectHandled;
            tagsHtml += moved
                ? `<span class="inline-block px-1.5 py-0.5 text-[10px] font-bold text-emerald-700 bg-emerald-50 rounded border border-emerald-200 uppercase tracking-wide mr-1 mb-1" title="DocPharma rejected · moved${order.warehouseChange ? ' ' + escapeHtml(order.warehouseChange.change||'') : ' to Shifupro'}">DP Rejected → MWH</span>`
                : `<span class="inline-block px-1.5 py-0.5 text-[10px] font-bold text-rose-700 bg-rose-100 rounded border border-rose-200 uppercase tracking-wide mr-1 mb-1" title="Rejected / Cancelled by DocPharma — needs warehouse action">DP Rejected</span>`;
        }

        // --- PREPARE DISPLAY DATA ---
        const tagsDisplay = (order.tags || 'None');
        const hoverText = tagsDisplay !== 'None' ? `Tags: ${tagsDisplay}` : '';

        // --- COD LOGIC ---
        let codBadge = '<span class="text-[10px] text-slate-300">-</span>'; 
        const dashNum = extractNum(order.id);
        let rawPhone = order.phone || (order.shipping_address ? order.shipping_address.phone : '') || '';
        let displayPhone = String(rawPhone).replace(/^(\+91|91)/, ''); 

        const codData = codByNum.get(dashNum);

        if (codData) {
            // Try multiple possible column names for confirmation field (match sheet header exactly)
            const confirmVal = codData['Confirmation received'] || codData['Confirmation Received']
                || codData['COD Confirmation'] || codData['Confirmation'] || codData['Response']
                || codData['COD Status'] || codData['Status'] || '';
            const rawResponse = String(confirmVal).toUpperCase().trim();

            if (['CONFIRM', 'YES', 'CONFIRMED', 'OK', 'Y'].includes(rawResponse)) {
                codBadge = `<span class="inline-flex items-center gap-1 px-2 py-1 text-[10px] font-bold text-emerald-700 bg-emerald-100 rounded border border-emerald-200 uppercase tracking-wide">✓ Confirmed</span>`;
            } else if (['CANCEL', 'NO', 'REJECT', 'REJECTED', 'N'].includes(rawResponse)) {
                codBadge = `<span class="inline-flex items-center gap-1 px-2 py-1 text-[10px] font-bold text-rose-700 bg-rose-100 rounded border border-rose-200 uppercase tracking-wide">Cancelled</span>`;
            } else {
                // Order found in sheet but confirmation pending / unknown value
                codBadge = `<span class="inline-flex items-center gap-1 px-2 py-0.5 text-[10px] font-medium text-amber-600 bg-amber-50 rounded border border-amber-200">Waiting...</span>`;
            }
        }

        mainRow.innerHTML = `
            <td class="p-4 w-10">
                <input type="checkbox" class="order-checkbox w-4 h-4 text-indigo-600 rounded border-slate-300 focus:ring-indigo-500 cursor-pointer" 
                    value="${order.originalId}" ${isSelected ? 'checked' : ''}
                    onclick="toggleOrderSelection('${order.originalId}', this)">
            </td>
            <td class="p-4"><img src="${platformLogos[order.platform]||''}" loading="lazy" decoding="async" class="w-6 h-6 opacity-70" alt="${escapeHtml(order.platform)}"></td>
            <td class="p-4 text-slate-500 text-sm font-medium">${order.date}</td>
            <td class="p-4 font-semibold text-slate-900 group relative">
                <span title="${escapeHtml(hoverText)}" class="cursor-help border-b border-dotted border-slate-400">${escapeHtml(order.id)}</span>
                <div class="text-[10px] text-slate-400 font-normal mt-0.5">${order.awb ? 'AWB: ' + escapeHtml(order.awb) + (order.courier ? ' · <span class="text-slate-500 font-medium">' + escapeHtml(order.courier) + '</span>' : '') : 'Unfulfilled'}</div>
            </td>
            <td class="p-4 font-medium text-slate-800">
                <div class="flex flex-col">
                    <div class="flex items-center">
                        ${escapeHtml(displayName)}
                        ${custBadge}
                    </div>
                    <div class="text-[11px] text-slate-500 mt-1 flex items-center gap-2">
                        <span class="font-semibold text-slate-600 uppercase text-[10px] tracking-wide">${escapeHtml(order.paymentMethod || 'Unknown')}</span>
                        <span class="text-slate-300">|</span>
                        <span class="font-mono text-slate-600 flex items-center gap-1">
                            <svg class="w-3 h-3 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z"></path></svg>
                            ${escapeHtml(displayPhone)}
                        </span>
                    </div>
                </div>
            </td>
            <td class="p-4">
                <div class="flex flex-wrap w-24">
                    ${tagsHtml}
                </div>
            </td>
            <td class="p-4">
                ${codBadge}
            </td>
            <td class="p-4 font-medium text-slate-900">${formatCurrency(order.total)}</td>
            <td class="p-4 ord-status-cell"><span class="px-3 py-1 text-xs font-semibold rounded-full whitespace-nowrap ${getStatusBadge(order.status)}">${order.status}</span>${ordHoldChipHtml(order)}</td>
            <td class="p-4 text-right">
                 <button class="text-slate-400 hover:text-indigo-600 focus:outline-none" onclick="openOrderModal('${order.id}')" title="View order details">
                    <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"></path></svg>
                 </button>
            </td>
        `;

        // Detail opens in a POPUP now (openOrderModal) instead of an inline expand row. This keeps the
        // table at ~503 rows instead of ~1000, and the heavy detail lives in a single modal — so scrolling
        // and viewing an order never janks, and a background re-render can't disturb the open detail.
        _ordersById.set(String(order.id), order);
        mainRow.classList.add('cursor-pointer');
        mainRow.addEventListener('click', (e) => {
            if (e.target.closest('input,button,a,label,select,.no-modal')) return;   // let controls work
            openOrderModal(String(order.id));
        });
        return mainRow;
    };

    // Progressive render: the first chunk paints now (so the click returns instantly), the rest fill in
    // across animation frames so the main thread never blocks. All rows still render; a newer render cancels this.
    const token = ++_ordersRenderToken;
    let _ri = 0;
    const step = (chunkSize) => {
        if (token !== _ordersRenderToken) return; // superseded by a newer render (filter/nav/refresh)
        const frag = document.createDocumentFragment();
        const end = Math.min(_ri + chunkSize, o.length);
        for (; _ri < end; _ri++) { frag.appendChild(buildRow(o[_ri])); }
        ordersListEl.appendChild(frag);
        if (_ri < o.length) requestAnimationFrame(() => step(150));
    };
    step(40); // tiny first chunk fills the viewport instantly; the rest stream in at 150/frame
}

// (Live-EDD column removed 2026-07 — it fired a serviceability batch call on every render and slowed
//  the Orders dashboard. Full EDD lookup still lives on the Serviceability page.)

// Build one order's expanded detail content — called on FIRST expand only (lazy).
function buildOrderDetailHtml(order) {
    const displayName = (order.name === 'N/A' && order.buyerName) ? order.buyerName : order.name;
    const uniqueId = String(order.id).replace(/\W/g, '');
    let detailedAddress = order.address || 'No address provided';
    if (order.shipping_address && typeof order.shipping_address === 'object') {
        const { address1, address2, city, province, zip } = order.shipping_address;
        detailedAddress = [address1, address2, city, province, zip ? `(${zip})` : ''].filter(Boolean).join(', ');
    }
    const orderItems = order.line_items || order.items || [];
    const itemsHtml = orderItems.map(item => {
        const itemName = item.title || item.name || 'Unknown Item';
        const itemQty = item.quantity || item.qty || 1;
        const itemSku = item.sku || '';
        return `
            <div class="flex items-center gap-3 p-2 bg-white rounded border border-slate-100 mb-1">
                <img src="${createFallbackImage(itemName)}" loading="lazy" decoding="async" class="w-8 h-8 rounded object-cover">
                <div class="flex-1 min-w-0">
                    <div class="text-sm text-slate-700 truncate">${escapeHtml(itemName)}</div>
                    ${itemSku ? `<div class="text-[10px] text-slate-400 font-mono mt-0.5">SKU: <span class="text-slate-600 font-semibold">${escapeHtml(itemSku)}</span></div>` : ''}
                </div>
                <div class="text-xs font-bold text-slate-500 shrink-0">x${itemQty}</div>
            </div>`;
    }).join('');

    let workflowHtml = '';
    const tags = (order.tags || '').toLowerCase();
    const shouldShow = (order.platform === 'Shopify') && !tags.includes('docpharma: in-progress');
    if (shouldShow && order.status !== 'Cancelled') {
        const isConfirmed = order.easyecomStatus && !['new', 'unconfirmed', 'open', ''].includes((order.easyecomStatus || '').toLowerCase());
        const hasEasyecomId = !!order.easyecomOrderId;
        workflowHtml = `
            <div class="bg-white p-4 rounded-xl border border-slate-200 shadow-sm mt-2">
                <div class="flex justify-between items-center mb-4">
                    <h4 class="text-xs font-bold text-slate-500 uppercase tracking-wide">EasyEcom Order Processing</h4>
                    <span class="px-2 py-1 rounded text-[10px] font-bold uppercase ${getStatusBadge(order.status)}">${order.status}</span>
                </div>
                <div class="space-y-3">
                    <div class="flex justify-between items-center">
                        <div>
                            <p class="text-sm font-semibold text-slate-800">Confirm Order</p>
                            <p class="text-[10px] text-slate-400 mt-0.5">${hasEasyecomId ? 'EasyEcom ID: ' + escapeHtml(order.easyecomOrderId) : 'EasyEcom ID not mapped yet'}</p>
                            ${order.easyecomStatus ? `<p class="text-[10px] text-slate-500 mt-0.5">EasyEcom Status: <span class="font-semibold">${escapeHtml(order.easyecomStatus)}</span></p>` : ''}
                        </div>
                        ${ isConfirmed ?
                            `<span class="px-3 py-1 bg-emerald-100 text-emerald-700 text-xs font-bold rounded border border-emerald-200">Confirmed</span>` :
                            hasEasyecomId ?
                                `<button onclick="handleManualStep1('${order.originalId}', '${uniqueId}')" id="btn-step1-${uniqueId}" class="px-3 py-1 bg-indigo-600 text-white text-xs font-medium rounded hover:bg-indigo-700 shadow-sm">Approve</button>` :
                                `<span class="px-3 py-1 bg-amber-50 text-amber-600 text-xs font-medium rounded border border-amber-200">Syncing...</span>`
                        }
                    </div>
                    ${order.awb ? `
                    <div class="flex justify-between items-center pt-2 border-t border-slate-100">
                        <div>
                            <p class="text-sm font-semibold text-slate-800">Shipping</p>
                            <p class="text-[10px] text-slate-400 font-mono">${escapeHtml(order.courier || '')} ${escapeHtml(order.awb)}</p>
                        </div>
                        <span class="text-xs font-bold text-emerald-600">Assigned</span>
                    </div>` : ''}
                    ${hasEasyecomId ? (() => {
                        if (order.status === 'Cancelled' || order.cancelled_at) return '';   // cancelled → no hold/unhold, the hold is moot
                        const held = order.eeHold || (/hold/i.test(order.easyecomStatus || '') ? {} : null);
                        if (held) {
                            const meta = [held.reason ? `“${escapeHtml(held.reason)}”` : '', held.by ? 'by ' + escapeHtml(held.by) : '', held.at ? new Date(held.at).toLocaleString('en-IN', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }) : ''].filter(Boolean).join(' · ');
                            return `
                    <div class="pt-2 border-t border-slate-100">
                        <div class="flex justify-between items-center p-2.5 rounded-lg bg-amber-50 border border-amber-200">
                            <div>
                                <p class="text-sm font-bold text-amber-700">⏸ On hold in EasyEcom${order.shopifyHold ? ' + Shopify' : ''}</p>
                                <p class="text-[10px] text-amber-600 mt-0.5">${meta || 'Held in EasyEcom'}${order.shopifyHold ? ' · one Unhold releases both' : ''}</p>
                            </div>
                            <button onclick="holdOrderModal('${escapeHtml(String(order.id))}', 'unhold')" class="px-3 py-1.5 bg-emerald-600 text-white text-xs font-semibold rounded-lg hover:bg-emerald-700 shadow-sm whitespace-nowrap">▶ Unhold EasyEcom</button>
                        </div>
                    </div>`;
                        }
                        // Hold works any time BEFORE the courier PICKS UP the order — including Ready-To-Ship
                        // (AWB assigned but not yet picked). order.holdable is computed server-side from the
                        // real tracking signal (not the ambiguous 'Shipped' status), so it's true until pickup.
                        if (order.holdable === false) return '';
                        if (order.shopifyHold) return '';   // already held on Shopify → don't also offer an EasyEcom hold
                        return `
                    <div class="flex justify-between items-center pt-2 border-t border-slate-100">
                        <div>
                            <p class="text-sm font-semibold text-slate-800">Hold on EasyEcom</p>
                            <p class="text-[10px] text-slate-400 mt-0.5">Pause processing in EasyEcom (before manifest only)</p>
                        </div>
                        <button onclick="holdOrderModal('${escapeHtml(String(order.id))}', 'hold')" class="px-3 py-1.5 bg-amber-500 text-white text-xs font-semibold rounded-lg hover:bg-amber-600 shadow-sm whitespace-nowrap">⏸ Hold EasyEcom</button>
                    </div>`;
                    })() : ''}
                </div>
            </div>
        `;
    }

    // Warehouse change is ONLY relevant for DocPharma orders (they may need to be re-fulfilled from
    // Shifupro). Orders already on Shifupro / RapidShyp never show the Move button.
    const _sp = String(order.shipPlatform || '').toLowerCase();
    const isDpOrder = _sp.includes('docpharma') || _sp.includes('dp bangalore') || order.docpharmaRejected || (order.tags || '').toLowerCase().includes('docpharma');
    const _whMovedD = order.warehouseChange || order.dpRejectHandled;   // already routed to Shifupro
    let standaloneWhHtml = '';
    if (order.easyecomOrderId && isDpOrder) {
        standaloneWhHtml = _whMovedD
            ? `<div class="bg-white p-4 rounded-xl border border-emerald-200 shadow-sm mt-2"><div class="flex justify-between items-center">
                 <div><p class="text-sm font-semibold text-slate-800">Warehouse ✓ Assigned</p><p class="text-[10px] text-emerald-600 mt-0.5 font-semibold">Moved: ${escapeHtml(order.warehouseChange ? order.warehouseChange.change : 'DocPharma → Shifupro')}</p></div>
                 <button disabled class="px-3 py-1.5 bg-emerald-50 text-emerald-600 text-xs font-semibold rounded-lg border border-emerald-200 cursor-default whitespace-nowrap">✓ Moved</button></div></div>`
            : `<div class="bg-white p-4 rounded-xl border ${order.docpharmaRejected ? 'border-rose-200' : 'border-slate-200'} shadow-sm mt-2"><div class="flex justify-between items-center">
                 <div><p class="text-sm font-semibold text-slate-800">Change warehouse</p><p class="text-[10px] ${order.docpharmaRejected ? 'text-rose-500 font-semibold' : 'text-slate-400'} mt-0.5">${order.docpharmaRejected ? 'DocPharma rejected — re-route to Shifupro (MWH)' : 'Re-route this DocPharma order to Shifupro'}</p></div>
                 <button onclick="changeWarehouseModal('${escapeHtml(String(order.id))}')" class="px-3 py-1.5 bg-indigo-600 text-white text-xs font-semibold rounded-lg hover:bg-indigo-700 shadow-sm whitespace-nowrap">🏬 Move</button></div></div>`;
    }

    // Shopify fulfillment hold — SEPARATE control from the EasyEcom hold, shown for every order (works
    // upstream of EasyEcom). Held → Unhold Shopify; not held + still pre-pickup → Hold on Shopify.
    let shopifyHoldHtml = '';
    if (order.status !== 'Cancelled' && !order.cancelled_at) { const sh = order.shopifyHold;   // cancelled → no Shopify hold/unhold either
      if (sh && !order.eeHold) {   // held in BOTH → the EasyEcom panel owns the single Unhold (it releases both)
        const sm = [sh.reason ? `“${escapeHtml(sh.reason)}”` : '', sh.by ? 'by ' + escapeHtml(sh.by) : ''].filter(Boolean).join(' · ');
        shopifyHoldHtml = `<div class="bg-white p-4 rounded-xl border border-rose-200 shadow-sm mt-2"><div class="flex justify-between items-center">
             <div><p class="text-sm font-bold text-rose-700">🔒 On hold in Shopify</p><p class="text-[10px] text-rose-500 mt-0.5">${sm || "Won't ship / import to EasyEcom"}</p></div>
             <button onclick="shopifyHoldAction('${escapeHtml(String(order.id))}','unhold')" class="px-3 py-1.5 bg-emerald-600 text-white text-xs font-semibold rounded-lg hover:bg-emerald-700 shadow-sm whitespace-nowrap">▶ Unhold Shopify</button></div></div>`;
      } else if (order.holdable !== false && !order.eeHold) {   // hide if already held on EasyEcom
        shopifyHoldHtml = `<div class="bg-white p-4 rounded-xl border border-slate-200 shadow-sm mt-2"><div class="flex justify-between items-center">
             <div><p class="text-sm font-semibold text-slate-800">Hold on Shopify</p><p class="text-[10px] text-slate-400 mt-0.5">Stops it shipping / importing to EasyEcom</p></div>
             <button onclick="shopifyHoldAction('${escapeHtml(String(order.id))}','hold')" class="px-3 py-1.5 bg-slate-800 text-white text-xs font-semibold rounded-lg hover:bg-slate-700 shadow-sm whitespace-nowrap">🔒 Hold Shopify</button></div></div>`;
      } }

    return `
        <div class="ord-detail-fade p-6 grid grid-cols-1 md:grid-cols-2 gap-8 border-t border-slate-100">
            <div class="space-y-4">
                <div>
                    <h4 class="text-xs font-bold text-slate-400 uppercase tracking-wide mb-2">Customer Details</h4>
                    <div class="bg-white p-3 rounded border border-slate-200 text-sm">
                        <p class="font-bold text-slate-800">${escapeHtml(displayName)}</p>
                        <p class="text-slate-500 mt-1 leading-relaxed">${escapeHtml(detailedAddress)}</p>
                        <p class="text-slate-400 text-xs mt-1 border-t border-slate-100 pt-1">${escapeHtml(order.email || '')}</p>
                    </div>
                </div>
                <div>
                    <h4 class="text-xs font-bold text-slate-400 uppercase tracking-wide mb-2">Order Items</h4>
                    <div class="max-h-40 overflow-y-auto pr-2 custom-scrollbar">${itemsHtml}</div>
                </div>
            </div>
            <div>${workflowHtml}${standaloneWhHtml}${shopifyHoldHtml}</div>
        </div>`;
}

// ── Hold / Release an order on SHOPIFY — separate control from the EasyEcom hold. Confirm + shared endpoint.
async function shopifyHoldAction(orderName, mode) {
    const isHold = mode === 'hold';
    const ok = await supConfirm({
        title: isHold ? 'Hold on Shopify?' : 'Release Shopify hold?',
        message: isHold ? `${orderName} will be held on Shopify — it won't ship or import to EasyEcom until released.`
                        : `${orderName} will be released and can ship / import to EasyEcom. Do this only after confirming with the customer.`,
        confirmLabel: isHold ? 'Hold' : 'Release' });
    if (!ok) return;
    try {
        const r = await fetch(isHold ? '/api/shopify-hold' : '/api/shopify-unhold', { method: 'POST', headers: { 'Content-Type': 'application/json', ...getAuthHeaders() }, body: JSON.stringify({ orderName }) });
        const d = await r.json(); if (!r.ok || !d.success) throw new Error(d.message || 'Failed');
        showNotification(isHold ? `${orderName} held on Shopify` : `${orderName} released from Shopify hold`);
        const order = _ordersById.get(String(orderName));
        if (order) order.shopifyHold = isHold ? { reason: 'Repeat COD — awaiting customer confirmation', by: (currentUser && currentUser.email) || null } : null;
        _eeHoldAt = 0;   // bust the hold-chip cache so chips refresh everywhere
        if (typeof silentRefreshOrders === 'function') silentRefreshOrders();
    } catch (e) { showNotification(e.message, true); }
}

// ── Hold / Unhold an order in EasyEcom — custom in-app modal (no browser prompt) ──
function holdOrderModal(orderName, mode) {
    document.getElementById('ee-hold-modal')?.remove();
    const order = _ordersById.get(String(orderName));
    const isHold = mode === 'hold';
    const heldMeta = order && order.eeHold ? [order.eeHold.reason ? `“${escapeHtml(order.eeHold.reason)}”` : '', order.eeHold.by ? 'held by ' + escapeHtml(order.eeHold.by) : ''].filter(Boolean).join(' · ') : '';
    const wrap = document.createElement('div');
    wrap.id = 'ee-hold-modal';
    wrap.className = 'dp-sheet-overlay fixed inset-0 flex items-center justify-center bg-slate-900/50 p-4';
    wrap.innerHTML = `<div class="bg-white rounded-2xl shadow-xl w-full max-w-md flex flex-col">
      <div class="flex items-center justify-between px-6 py-4 border-b border-slate-200">
        <div><h3 class="text-lg font-bold text-slate-800">${isHold ? '⏸ Hold order' : '▶ Release hold'}</h3>
          <p class="text-xs text-slate-400 mt-0.5">${escapeHtml(orderName)} · EasyEcom</p></div>
        <button id="eeh-close" class="text-slate-400 hover:text-slate-700 w-8 h-8 rounded-lg hover:bg-slate-100">✕</button>
      </div>
      <div class="p-6 space-y-3">
        ${isHold ? `
        <div><label class="block text-xs font-semibold text-slate-500 mb-1.5">Hold reason <span class="text-rose-500">*</span></label>
          <textarea id="eeh-reason" rows="3" maxlength="200" class="filter-input w-full !h-auto py-2 resize-none" placeholder="e.g. Customer asked to change address / payment check / stock issue"></textarea>
          <p class="text-[11px] text-slate-400 mt-1.5">Processing pauses in EasyEcom until released. Works only before the manifest is generated.</p></div>`
        : `
        <div class="p-3 rounded-lg bg-amber-50 border border-amber-200 text-xs text-amber-700">
          <b>Currently on hold</b>${heldMeta ? ' — ' + heldMeta : ''}.<br>Releasing returns the order to its previous status and processing resumes.</div>`}
      </div>
      <div class="flex items-center justify-end gap-3 px-6 py-4 border-t border-slate-200">
        <span id="eeh-status" class="text-sm mr-auto"></span>
        <button id="eeh-cancel" class="px-4 py-2 rounded-lg text-sm font-semibold text-slate-600 hover:bg-slate-100">Cancel</button>
        <button id="eeh-submit" class="px-4 py-2 rounded-lg text-sm font-semibold text-white ${isHold ? 'bg-amber-500 hover:bg-amber-600' : 'bg-emerald-600 hover:bg-emerald-700'}">${isHold ? '⏸ Hold order' : '▶ Unhold order'}</button>
      </div></div>`;
    document.body.appendChild(wrap);
    const close = () => wrap.remove();
    document.getElementById('eeh-close').addEventListener('click', close);
    document.getElementById('eeh-cancel').addEventListener('click', close);
    wrap.addEventListener('click', e => { if (e.target === wrap) close(); });
    if (isHold) setTimeout(() => document.getElementById('eeh-reason')?.focus(), 50);
    document.getElementById('eeh-submit').addEventListener('click', () => eeHoldSubmit(orderName, isHold));
}
async function eeHoldSubmit(orderName, isHold) {
    const st = document.getElementById('eeh-status'), btn = document.getElementById('eeh-submit');
    const reason = (document.getElementById('eeh-reason')?.value || '').trim();
    if (isHold && !reason) { st.textContent = 'Hold reason is required'; st.className = 'text-sm text-rose-600 mr-auto'; return; }
    btn.disabled = true; st.textContent = isHold ? 'Holding…' : 'Releasing…'; st.className = 'text-sm text-slate-500 mr-auto';
    try {
        const r = await fetch('/api/easyecom/' + (isHold ? 'hold-order' : 'unhold-order'), {
            method: 'POST', headers: { 'Content-Type': 'application/json', ...getAuthHeaders() },
            body: JSON.stringify(isHold ? { orderName, reason } : { orderName })
        });
        const d = await r.json();
        if (!r.ok || !d.success) throw new Error(d.message || 'Failed');
        // Update local state so the UI flips to held/unheld INSTANTLY (no wait for the next sync).
        const order = _ordersById.get(String(orderName));
        if (order) order.eeHold = isHold ? (d.hold || { reason, at: new Date().toISOString() }) : null;
        refreshOrderDetailRow(orderName);
        // Bust the shared ⏸-HOLD map so every other dashboard (Ops/DP/Claims/Support) reflects it on next load.
        const _hk = String(orderName || '').replace('#', '').trim();
        if (isHold) _eeHold[_hk] = { order_name: _hk, note: reason, created_by: currentUser && currentUser.email, created_at: new Date().toISOString() };
        else delete _eeHold[_hk];
        _eeHoldAt = 0;
        st.textContent = 'Done ✓'; st.className = 'text-sm text-emerald-600 mr-auto';
        showNotification(d.message || 'Done.');
        setTimeout(() => document.getElementById('ee-hold-modal')?.remove(), 700);
    } catch (e) { st.textContent = e.message; st.className = 'text-sm text-rose-600 mr-auto'; btn.disabled = false; }
}
// Rebuild an order's detail content in place (after hold/unhold etc.).
function refreshOrderDetailRow(orderId) {
    const order = _ordersById.get(String(orderId));
    // Detail now lives in a popup — rebuild it there if it's the open order.
    const modal = document.getElementById('order-detail-modal');
    if (modal && order && modal.dataset.orderId === String(orderId)) {
        const body = modal.querySelector('.overflow-y-auto');
        if (body) body.innerHTML = buildOrderDetailHtml(order);
    }
    const details = document.getElementById(`details-${orderId}`);   // legacy inline (none now)
    if (details && order && !details.dataset.lazy) details.firstElementChild.innerHTML = buildOrderDetailHtml(order);
    // Patch the main row's status cell chip too.
    const row = document.querySelector(`tr[data-order-id="${(window.CSS && CSS.escape) ? CSS.escape(String(orderId)) : String(orderId)}"]`);
    const cell = row && row.querySelector('.ord-status-cell');
    if (cell) { const chip = cell.querySelector('.ord-hold-chip'); if (chip) chip.remove(); const html = ordHoldChipHtml(order); if (html) cell.insertAdjacentHTML('beforeend', html); }
}

// ── Change an order's fulfilment warehouse in EasyEcom — own modal (routes a rejected order out) ──
// Uses the stored EasyEcom panel session cookie server-side (the only thing UpdateVendor accepts).
async function changeWarehouseModal(orderName) {
    document.getElementById('ee-wh-modal')?.remove();
    const _o = (typeof _ordersById !== 'undefined') ? _ordersById.get(String(orderName)) : null;
    const _panelUrl = _o && _o.easyecomOrderId ? `https://app.easyecom.io/V2/Orders/Details/${_o.easyecomOrderId}` : 'https://app.easyecom.io/';
    const wrap = document.createElement('div'); wrap.id = 'ee-wh-modal';
    wrap.className = 'dp-sheet-overlay fixed inset-0 flex items-center justify-center bg-slate-900/50 p-4';
    wrap.innerHTML = `<div class="sup-pop bg-white rounded-2xl shadow-xl w-full max-w-md p-6">
        <div class="flex items-center justify-between mb-1"><h3 class="text-lg font-bold text-slate-800">🏬 Change warehouse</h3>
          <button data-x class="text-slate-400 hover:text-slate-700 w-8 h-8 rounded-lg hover:bg-slate-100">✕</button></div>
        <p class="text-xs text-slate-400 mb-4">Re-route <b>${escapeHtml(String(orderName))}</b> to another fulfilment warehouse in EasyEcom. Works only before a shipment/AWB is assigned.</p>
        <label class="block text-xs font-semibold text-slate-500 uppercase tracking-wide mb-1.5">Move to warehouse</label>
        <select id="eewh-target" class="filter-select w-full"><option>Loading…</option></select>
        <p id="eewh-status" class="text-sm text-slate-500 min-h-[20px] mt-3"></p>
        <div class="mt-3 pt-3 border-t border-slate-100">
          <div class="flex items-center justify-between">
            <span class="text-xs text-slate-500">EasyEcom session: <b id="eewh-sess" class="text-slate-700">checking…</b></span>
            <button id="eewh-sess-toggle" class="text-xs text-indigo-600 font-semibold hover:underline">Update session</button>
          </div>
          <div id="eewh-sess-box" class="hidden mt-2">
            <p class="text-[11px] text-slate-400 mb-1.5">In the EasyEcom panel: open DevTools (F12) → Network → click any request → copy the whole <b>Cookie</b> value (must include <code>laravel_session</code>) → paste below.</p>
            <textarea id="eewh-cookie" class="filter-input w-full text-xs" style="height:64px" placeholder="PHPSESSID=…; laravel_session=…"></textarea>
            <button id="eewh-sess-save" class="mt-1.5 px-3 py-1.5 text-xs rounded-lg bg-slate-800 text-white font-semibold hover:bg-slate-700">Save session</button>
          </div>
          <p class="text-[11px] text-slate-400 mt-2">Can't route (shipment assigned, or session issue)? <a href="${_panelUrl}" target="_blank" class="text-indigo-600 hover:underline">Open order in EasyEcom ↗</a></p>
        </div>
        <div class="flex justify-end gap-2 mt-3">
          <button data-x class="px-4 py-2 rounded-lg border border-slate-200 text-slate-600 text-sm hover:bg-slate-100">Cancel</button>
          <button id="eewh-submit" class="px-4 py-2 rounded-lg text-sm font-semibold text-white bg-indigo-600 hover:bg-indigo-700">Move order</button></div></div>`;
    document.body.appendChild(wrap);
    wrap.addEventListener('click', e => { if (e.target === wrap || e.target.closest('[data-x]')) wrap.remove(); });
    const st = document.getElementById('eewh-status');
    // warehouses
    try {
        const d = await (await fetch('/api/easyecom/warehouses', { headers: getAuthHeaders() })).json();
        document.getElementById('eewh-target').innerHTML = (d.warehouses || []).map(w => `<option value="${w.cId}">${escapeHtml(w.name)}</option>`).join('');
    } catch (e) { st.textContent = 'Could not load warehouses: ' + e.message; }
    // live session health (pings EasyEcom with the stored cookie)
    const sessEl = document.getElementById('eewh-sess');
    (async () => {
        try {
            const s = await (await fetch('/api/easyecom/session/check', { headers: getAuthHeaders() })).json();
            if (!s || !s.success) { sessEl.textContent = '—'; return; }
            // Health = freshness of the cookie the browser sync extension pushes (~every 20 min). The
            // server can't ping EasyEcom (WAF blocks its IP), so a fresh sync IS a live session.
            if (!s.hasSession) { sessEl.innerHTML = '<span class="text-amber-600 font-semibold">● not set — paste a cookie</span>'; document.getElementById('eewh-sess-box').classList.remove('hidden'); }
            else if (s.valid) { sessEl.innerHTML = `<span class="text-emerald-600">● healthy</span>${s.updatedAt ? ' · synced ' + supRelTime(s.updatedAt) : ''}`; }
            else { sessEl.innerHTML = `<span class="text-amber-600 font-semibold">● stale — auto-sync may be offline${s.updatedAt ? ' · last synced ' + supRelTime(s.updatedAt) : ''}</span>`; document.getElementById('eewh-sess-box').classList.remove('hidden'); }
        } catch (_) { sessEl.textContent = '—'; }
    })();
    document.getElementById('eewh-sess-toggle').addEventListener('click', () => document.getElementById('eewh-sess-box').classList.toggle('hidden'));
    document.getElementById('eewh-sess-save').addEventListener('click', async () => {
        const cookie = document.getElementById('eewh-cookie').value.trim();
        if (!cookie) return;
        try {
            const r = await fetch('/api/easyecom/session', { method: 'POST', headers: { 'Content-Type': 'application/json', ...getAuthHeaders() }, body: JSON.stringify({ cookie }) });
            const d = await r.json(); if (!r.ok || !d.success) throw new Error(d.message || 'Failed');
            showNotification('EasyEcom session saved'); document.getElementById('eewh-sess-box').classList.add('hidden');
            document.getElementById('eewh-cookie').value = ''; sessEl.innerHTML = '<span class="text-emerald-600">saved</span> · just now';
        } catch (e) { showNotification(e.message, true); }
    });
    document.getElementById('eewh-submit').addEventListener('click', async () => {
        const target = document.getElementById('eewh-target').value;
        const btn = document.getElementById('eewh-submit');
        btn.disabled = true; st.textContent = 'Routing in EasyEcom…'; st.className = 'text-sm text-slate-500 min-h-[20px] mt-3';
        try {
            const r = await fetch('/api/easyecom/change-warehouse', { method: 'POST', headers: { 'Content-Type': 'application/json', ...getAuthHeaders() }, body: JSON.stringify({ orderName, targetCid: target }) });
            const d = await r.json();
            if (!r.ok || !d.success) {
                if (d.needSession) { document.getElementById('eewh-sess-box').classList.remove('hidden'); document.getElementById('eewh-cookie').focus(); }
                throw new Error(d.message || 'Failed');
            }
            st.textContent = d.message || 'Done ✓'; st.className = 'text-sm text-emerald-600 min-h-[20px] mt-3';
            showNotification(d.message || 'Warehouse changed');
            setTimeout(() => { wrap.remove(); if (currentView === 'orders-dashboard' && typeof silentRefreshOrders === 'function') silentRefreshOrders(); }, 1400);
        } catch (e) { st.textContent = e.message; st.className = 'text-sm text-rose-600 min-h-[20px] mt-3'; btn.disabled = false; }
    });
}

// Order detail now opens in a popup (kept the old name as an alias so any caller still works).
