async function claimsSend(which){
  const from = document.getElementById('claims-from')?.value, to = document.getElementById('claims-to')?.value;
  const cfg = {
    srto: { url: '/api/silent-rto-claims/send', status: 'srto-status', msg: 'Email the silent-RTO claim list to RapidShyp for this date range?' },
    late: { url: '/api/late-deliveries/send', status: 'late-status', msg: 'Email the late-delivery report? A separate email goes to each platform\'s recipients (RapidShyp / DocPharma).' },
    intransit: { url: '/api/intransit-late/send', status: 'itl-status', msg: 'Email the overdue in-transit chase list? A separate email goes to each platform\'s recipients (RapidShyp / DocPharma).' },
    ofd: { url: '/api/first-ofd-late/send', status: 'ofd-status', msg: 'Email the First-OFD-late RTO report (first attempt after the promised EDD) to RapidShyp?' },
  }[which];
  const st = document.getElementById(cfg.status);
  if(!confirm(cfg.msg)) return;
  if(st){ st.textContent = 'Sending…'; st.className = 'text-sm text-slate-500'; }
  try{
    const body = { from, to, source: _claimsFilter.platform || undefined };
    const r = await fetch(cfg.url, { method: 'POST', headers: { 'Content-Type': 'application/json', ...getAuthHeaders() }, body: JSON.stringify(body) });
    const d = await r.json();
    if(!r.ok || !d.success) throw new Error(d.message || 'Send failed');
    if(st){ st.textContent = d.message || 'Sent ✓'; st.className = 'text-sm text-emerald-600'; }
  }catch(e){ if(st){ st.textContent = e.message; st.className = 'text-sm text-rose-600'; } }
}

// ═════════════════ CUSTOMER SUPPORT CONSOLE (port of the standalone Support Console) ═════════════════
// Buckets — every order sits in exactly one (computed upstream in the order_buckets view).
const SUP_BUCKETS = [
  ['order_to_dispatch','Order → Dispatch','info'], ['dispatch_plus_2','Dispatch + 2 days','info'],
  ['two_to_five_days','2–5 days','warning'], ['five_days_plus','5 days +','destructive'],
  ['undelivered','Undelivered','destructive'], ['delivered','Delivered','success'],
  ['rto','RTO','destructive'], ['cancelled','Cancelled','muted'],
];
const SUP_TONE = {
  info:        ['bg-sky-100 text-sky-700 border-sky-200', 'ring-sky-300'],
  warning:     ['bg-amber-100 text-amber-700 border-amber-200', 'ring-amber-300'],
  destructive: ['bg-rose-100 text-rose-700 border-rose-200', 'ring-rose-300'],
  success:     ['bg-emerald-100 text-emerald-700 border-emerald-200', 'ring-emerald-300'],
  muted:       ['bg-slate-100 text-slate-600 border-slate-200', 'ring-slate-300'],
};
const supBucketOf = id => SUP_BUCKETS.find(b => b[0] === id) || [id, id || '—', 'muted'];
function supBadge(id){ const [,label,tone]=supBucketOf(id); return `<span class="inline-flex px-2 py-0.5 rounded-full text-[11px] font-semibold border ${SUP_TONE[tone][0]} whitespace-nowrap">${escapeHtml(label)}</span>`; }
// COD / Prepaid chip (server sets r.payment from orders.financial_status). Amber = money still to collect
// on delivery (COD — the costly ones to lose), emerald = already paid. Tooltip shows the raw Shopify status.
function supPayChip(r){
  if(!r||!r.payment) return '<span class="text-slate-300">—</span>';
  const cod=r.payment==='COD';
  const partial=String(r.financial_status||'')==='partially_paid';
  const cls=cod?'bg-amber-50 text-amber-800 border-amber-200':'bg-emerald-50 text-emerald-700 border-emerald-200';
  const tip=`Shopify payment status: ${r.financial_status||'unknown'}`+(partial?' — part-paid online, balance due on delivery':'');
  return `<span class="inline-flex px-2 py-0.5 rounded-full text-[11px] font-semibold border ${cls} whitespace-nowrap" title="${escapeHtml(tip)}">${r.payment}${partial?' •':''}</span>`;
}
// ── Customer Support live-tracking modal — click an AWB → courier scan log (like Fulfillment Ops). ────
// Reuses the read-only, cached /api/delivery-performance/shipment/:awb (RapidShyp scans + DocPharma milestones).
let _supTrackKey=null;
function supTrackClose(){ const m=document.getElementById('sup-track-modal'); if(m) m.remove(); _supTrackKey=null; }
// Builds its own modal DOM (no dependency on a static element in index.html — works even if the HTML wasn't
// reloaded), appended to <body>. z-index is set via INLINE STYLE (95) — a Tailwind `z-[90]` class wouldn't be
// in the compiled CSS, so it silently did nothing and the popup fell BEHIND the z-[80] order-detail modal.
async function supTrackOpen(awb, orderName, courier){
  awb=String(awb||'').trim();
  supTrackClose();
  _supTrackKey=awb||('#'+(orderName||'')); const cur=_supTrackKey;
  const wrap=document.createElement('div');
  wrap.id='sup-track-modal';
  wrap.className='fixed inset-0 flex items-end sm:items-center justify-center bg-slate-900/50 backdrop-blur-sm p-0 sm:p-4';
  wrap.style.zIndex='95';
  wrap.innerHTML=`<div class="bg-white w-full sm:max-w-lg rounded-t-3xl sm:rounded-2xl shadow-2xl flex flex-col animate-slide-up" style="max-height:88vh">
    <div class="px-5 pt-4 pb-4 border-b border-slate-100"><div class="flex items-start justify-between gap-3">
      <div class="flex-1 min-w-0"><span class="text-[10px] font-bold uppercase tracking-widest text-slate-400">Live Tracking</span>
        <div class="font-mono text-base font-bold text-slate-800 tracking-wider truncate">${escapeHtml(awb||orderName||'—')}</div>
        <div class="text-xs text-slate-400 mt-0.5">${escapeHtml([orderName,courier].filter(Boolean).join(' · '))}</div></div>
      <button class="sup-track-x w-8 h-8 flex items-center justify-center rounded-full bg-slate-100 hover:bg-slate-200 text-slate-500 text-lg flex-shrink-0">×</button>
    </div></div>
    <div class="sup-track-body overflow-y-auto flex-1 px-5 py-4">${brandLoaderSm('Loading live tracking…')}</div>
  </div>`;
  document.body.appendChild(wrap);
  wrap.addEventListener('click',e=>{ if(e.target===wrap) supTrackClose(); });
  wrap.querySelector('.sup-track-x').addEventListener('click',supTrackClose);
  const body=wrap.querySelector('.sup-track-body');
  if(!awb){ body.innerHTML='<div class="text-slate-400 text-sm py-8 text-center">No AWB assigned yet — live tracking appears once the courier generates one.</div>'; return; }
  try{
    const r=await fetch(`/api/delivery-performance/shipment/${encodeURIComponent(awb)}`,{headers:getAuthHeaders()});
    const d=await r.json(); if(!d.success) throw new Error(d.error||'failed');
    if(_supTrackKey===cur) body.innerHTML=supTrackRender(d);
  }catch(e){ if(_supTrackKey===cur) body.innerHTML=`<div class="text-rose-400 text-sm py-8 text-center">${ecEsc(e.message)}</div>`; }
}
function supTrackRender(d){
  const j=d.journey, ts=(j&&j.ts)||{};
  const step=(label,iso,color)=>`<div class="flex items-center gap-2 py-0.5 text-xs"><span class="w-2 h-2 rounded-full shrink-0" style="background:${iso?color:'#cbd5e1'}"></span><span class="w-28 text-slate-500">${label}</span><span class="tabular-nums ${iso?'text-slate-700 font-medium':'text-slate-300'}">${dpFmtTs(iso)}</span></div>`;
  const isRto=j&&/rto/i.test(j.outcome||'');
  const timeline=step('Order placed',ts.order,'#6366f1')+step('Dispatched',ts.dispatched,'#0ea5e9')+step('Out for delivery',ts.ofd,'#f59e0b')+(isRto?step('RTO',ts.rto,'#ef4444'):step('Delivered',ts.delivered,'#16a34a'))+step('Promised EDD',ts.edd,'#8b5cf6');
  const scanRows=arr=>`<div class="space-y-1 max-h-72 overflow-auto pr-1">${arr.map(s=>`<div class="flex gap-2 text-xs"><span class="w-24 shrink-0 text-slate-400 tabular-nums">${dpFmtTs(s.at)}</span><span class="text-slate-700">${ecEsc(s.desc)}${s.code?` <span class="text-slate-400">(${ecEsc(s.code)})</span>`:''}${s.location?` <span class="text-slate-400">· ${ecEsc(s.location)}</span>`:''}</span></div>`).join('')}</div>`;
  let scanHtml;
  if(d.dp){ const dp=d.dp;
    const badge=dp.current_status?`<span class="px-2 py-0.5 rounded-full bg-indigo-50 text-indigo-700 ring-1 ring-indigo-200 text-[11px] font-semibold">${ecEsc(dp.current_status)}</span>`:'';
    const link=dp.tracking_url?`<a href="${ecEsc(dp.tracking_url)}" target="_blank" rel="noopener" class="text-indigo-600 hover:underline text-xs font-medium">Track on DocPharma ↗</a>`:'';
    scanHtml=`<div class="flex items-center gap-3 mb-2">${badge}${link}</div>${(d.scans&&d.scans.length)?scanRows(d.scans):''}<div class="text-[11px] text-slate-400 mt-2">${ecEsc(dp.note||'')}</div>`;
  } else if(!d.scans||!d.scans.length) scanHtml='<div class="text-slate-400 text-xs py-3">No scan log available yet for this shipment.</div>';
  else scanHtml=`${scanRows(d.scans)}${d.live?'<div class="text-[10px] text-emerald-500 mt-1">● fetched live from courier</div>':''}`;
  const hasJourney=j&&(ts.order||ts.dispatched||ts.ofd||ts.delivered||ts.rto||ts.edd);
  const courierLine=(j&&j.courier)?`<div class="text-xs text-slate-400 mb-3">${ecEsc(j.courier)}${j.order_name?' · '+ecEsc(j.order_name):''}</div>`:'';
  return `<div class="space-y-4">${courierLine}${hasJourney?`<div><div class="text-xs font-bold text-slate-600 uppercase tracking-wide mb-2">Journey</div>${timeline}</div>`:''}<div><div class="text-xs font-bold text-slate-600 uppercase tracking-wide mb-2">Scan log</div>${scanHtml}</div></div>`;
}
// Clickable AWB (or any label) → support tracking modal. Renders plain text when no AWB.
function supAwbLink(awb, orderName, courier, label){
  const a=String(awb||'').trim();
  if(!a) return escapeHtml(label!=null?String(label):'—');
  const hasLabel=(label!=null&&String(label).trim()!=='');   // AWB shown in mono; an explicit label (courier) stays normal
  const txt=hasLabel?String(label):a;
  // Reads as clean dark data (no blue-hyperlink underline). On hover a subtle grey pill appears + a
  // "Click to track live" tooltip to signal it's clickable. inline-block + px/-mx keep it aligned with text.
  return `<a href="#" class="sup-awb-track ${hasLabel?'':'font-mono'} no-underline cursor-pointer inline-block rounded px-1.5 -mx-1.5 py-0.5 text-slate-700 hover:bg-slate-100 transition-colors whitespace-nowrap" data-awb="${escapeHtml(a)}" data-oname="${escapeHtml(orderName||'')}" data-courier="${escapeHtml(courier||'')}" title="Click to track live">${escapeHtml(txt)}</a>`;
}
// Capturing listener (fires before a parent row's click) — scoped to Customer Support's .sup-awb-track links.
document.addEventListener('click', e => { const el = e.target.closest && e.target.closest('.sup-awb-track'); if(el){ e.preventDefault(); e.stopPropagation(); supTrackOpen(el.dataset.awb, el.dataset.oname, el.dataset.courier); } }, true);
const SUP_OUTCOMES = [['no_answer','No answer'],['customer_will_accept','Customer will accept'],['refused','Refused'],['reschedule','Reschedule'],['wrong_number','Wrong number'],['delivered_confirmed','Delivered confirmed'],['other','Other']];
const supOutcomeLbl = o => (SUP_OUTCOMES.find(x=>x[0]===o)||[o,String(o||'').replace(/_/g,' ')])[1];
function supAge(iso){ if(!iso) return '—'; const h=(Date.now()-new Date(iso).getTime())/3600000; if(h<24) return Math.max(1,Math.round(h))+'h'; return Math.round(h/24)+'d'; }
async function supFetch(url, opts){ const r=await fetch(url,{...(opts||{}),headers:{'Content-Type':'application/json',...getAuthHeaders(),...((opts||{}).headers||{})}}); const d=await r.json().catch(()=>({})); if(!r.ok||d.success===false) throw new Error(d.error||d.message||('HTTP '+r.status)); return d; }

// Shared date range (persisted) + a tiny picker rendered into each page header.
// ── Support date ranges — ONE PER PANEL (user, 2026-09-05: "for Hold Order, Undelivered, and Status
// Changes date filter should work separtly"). There used to be a single `_supRange` and a single
// localStorage key behind every panel, so narrowing Undelivered to today silently narrowed Hold
// Orders too, and going back re-ran a query nobody had asked to change. Each panel now keeps its own
// range under its own key, and the queue's three tabs count as three panels because that is how they
// are used — the same order sits in each for different reasons.
const SUP_RANGE_DEFAULT_DAYS = 14;
const _supRanges = {};
function _supRangeKey(scope){ return 'support.dateRange.' + (scope || 'default'); }
function supRangeFor(scope){
  if (_supRanges[scope]) return _supRanges[scope];
  try { const s = JSON.parse(localStorage.getItem(_supRangeKey(scope)) || 'null');
        if (s && s.from && s.to) return (_supRanges[scope] = s); } catch (_) {}
  // Falls back to the OLD shared key once, so nobody's saved range is lost on the day this ships.
  try { const s = JSON.parse(localStorage.getItem('support.dateRange') || 'null');
        if (s && s.from && s.to) return (_supRanges[scope] = s); } catch (_) {}
  const d = new Date(), f = new Date(d.getFullYear(), d.getMonth(), d.getDate() - SUP_RANGE_DEFAULT_DAYS);
  return (_supRanges[scope] = { from: _ymd(f), to: _ymd(d) });
}
// Kept for the panels that read the range without owning a picker; `_supRange` stays a live alias of
// whichever panel rendered last so no existing caller had to change.
let _supRange = supRangeFor('default');
function supRangeQS(scope){ const r = scope ? supRangeFor(scope) : _supRange; return `from=${r.from}&to=${r.to}`; }
// Presets are OFFSETS in days from today, except the two that name a single day or a short window.
// "Yesterday" is a one-day window, not "since yesterday" — that distinction is the whole point of it.
const SUP_PRESETS = [
  ['0', 'Today', 0, 0], ['y', 'Yesterday', 1, 1], ['3', 'Last 3 days', 2, 0],
  ['7', 'Last 7 days', 6, 0], ['14', 'Last 14 days', 13, 0], ['30', 'Last 30 days', 29, 0],
];
function supRenderRange(containerId, onChange, scope){
  const el=document.getElementById(containerId); if(!el) return;
  scope = scope || 'default';
  const r = supRangeFor(scope);
  const save=()=>{ _supRanges[scope]=r; _supRange=r; localStorage.setItem(_supRangeKey(scope), JSON.stringify(r)); };
  _supRange = r;
  el.innerHTML=`<div class="flex items-center gap-2 flex-wrap">
    <select class="filter-select sup-preset"><option value="">Presets</option>${
      SUP_PRESETS.map(([v,label])=>`<option value="${v}">${label}</option>`).join('')}</select>
    <input type="date" class="filter-input sup-from" value="${r.from}"><span class="text-slate-400">→</span>
    <input type="date" class="filter-input sup-to" value="${r.to}">
    <button class="filter-btn sup-apply">Apply</button></div>`;
  el.querySelector('.sup-preset').addEventListener('change',e=>{ const v=e.target.value; if(v==='') return;
    const p=SUP_PRESETS.find(x=>x[0]===v); if(!p) return;
    const d=new Date();
    const from=new Date(d.getFullYear(),d.getMonth(),d.getDate()-p[2]);
    const to=new Date(d.getFullYear(),d.getMonth(),d.getDate()-p[3]);
    r.from=_ymd(from); r.to=_ymd(to);
    el.querySelector('.sup-from').value=r.from; el.querySelector('.sup-to').value=r.to;
    save(); onChange(); });
  el.querySelector('.sup-apply').addEventListener('click',()=>{
    const f=el.querySelector('.sup-from').value, t=el.querySelector('.sup-to').value;
    if(!f||!t) return showNotification('Pick both dates',true);
    if(f>t) return showNotification('The From date is after the To date',true);
    r.from=f; r.to=t; save(); onChange(); });
}

// ── Support Dashboard ──────────────────────────────────────────────────────
async function supDashInit(){
  supRenderRange('sup-range-dash', supDashInit, 'dash');
  const k=document.getElementById('sup-kpis'); if(k) k.innerHTML='<div class="col-span-full">'+brandLoader()+'</div>';
  try{
    const d=await supFetch('/api/support/summary?'+supRangeQS('dash'));
    const tile=(label,val,sub)=>`<div class="card p-5"><p class="text-xs font-semibold text-slate-400 uppercase tracking-wide">${label}</p><p class="text-2xl font-bold text-slate-800 mt-1">${val}</p>${sub?`<p class="text-[11px] text-slate-400 mt-0.5">${sub}</p>`:''}</div>`;
    k.innerHTML = tile('Total orders', d.kpis.totalOrders,'selected range')+tile('Calls today', d.kpis.callsToday,'today')+
      tile('Delivered today', d.kpis.deliveredToday,'today')+tile('Pending (undelivered)', d.kpis.pendingUndelivered,'selected range')+
      tile('MSG91 confirmed', d.kpis.msg91Confirmed,'undelivered + confirmed');
    document.getElementById('sup-buckets').innerHTML = SUP_BUCKETS.map(([id,label,tone])=>
      `<button class="sup-bucket-tile card p-4 text-left hover:ring-2 ${SUP_TONE[tone][1]} transition-all" data-bucket="${id}">
        <p class="text-[11px] font-semibold text-slate-400 uppercase tracking-wide truncate">${label}</p>
        <p class="text-xl font-bold mt-1 ${SUP_TONE[tone][0].split(' ')[1]}">${d.buckets[id]||0}</p></button>`).join('');
    document.querySelectorAll('.sup-bucket-tile').forEach(b=>b.addEventListener('click',()=>{ _supoFilters={bucket:b.dataset.bucket,page:1}; navigate('support-orders'); }));
    document.getElementById('sup-calls-range').innerHTML =
      `<div class="flex items-center justify-between"><div><p class="text-sm font-semibold text-slate-700">${d.kpis.callsInRange} calls logged in the selected window</p>
       <p class="text-xs text-slate-400 mt-0.5">Every outcome is in the call log</p></div>
       <button class="filter-btn" onclick="navigate('support-calls')">View call log →</button></div>`;
  }catch(e){ if(k) k.innerHTML=`<div class="col-span-full text-rose-500 text-sm">${escapeHtml(e.message)}</div>`; }
}

// ── Call Queue ─────────────────────────────────────────────────────────────
let _supTab='und', _supQueueRows=[], _supCapped=false, _supTotal=0, _supQueueWired=false, _supSort=null;   // _supSort={k,d} set by clicking a column header
function supQueueInit(){
  supRenderRange('sup-range-queue', supLoadQueue, 'queue.'+_supTab);
  if(!_supQueueWired){ _supQueueWired=true;
    // Each tab carries its own range, so the picker is re-rendered on every switch — Undelivered
    // narrowed to today must not silently narrow Hold Orders.
    document.querySelectorAll('.sup-tab').forEach(b=>b.addEventListener('click',()=>{ _supTab=b.dataset.tab; supTabPaint();
      supRenderRange('sup-range-queue', supLoadQueue, 'queue.'+_supTab); supLoadQueue(); }));
    ['sup-f-notes','sup-f-age','sup-f-hold','sup-f-pay','sup-f-platform','sup-f-raised','sup-f-status','sup-f-calltype','sup-f-calldate','sup-f-callfrom','sup-f-callto'].forEach(id=>document.getElementById(id)?.addEventListener('change',supQueueTable));
    document.getElementById('sup-f-notesearch')?.addEventListener('input', debounce(supQueueTable,250));
    // Defaults live WITH their control, not in a parallel array — the array had seven entries for
    // eleven inputs, so every filter added since silently reset to undefined and only behaved by
    // luck (an empty string happening to read as 'all' downstream).
    const SUP_FILTER_DEFAULTS={'sup-f-notes':'all','sup-f-age':'any','sup-f-hold':'all','sup-f-pay':'all','sup-f-platform':'all','sup-f-raised':'all','sup-f-status':'all','sup-f-calltype':'all','sup-f-calldate':'all','sup-f-callfrom':'','sup-f-callto':''};
    document.getElementById('sup-f-clear')?.addEventListener('click',()=>{ Object.entries(SUP_FILTER_DEFAULTS).forEach(([id,v])=>{ const el=document.getElementById(id); if(el) el.value=v; }); document.getElementById('sup-f-notesearch').value=''; _supSort=null; supQueueTable(); });
    document.getElementById('sup-refresh')?.addEventListener('click', supRefreshTracking);
  }
  supTabPaint(); supLoadQueue();
}
function supTabPaint(){ document.querySelectorAll('.sup-tab').forEach(b=>{ const on=b.dataset.tab===_supTab;
  b.classList.toggle('border-indigo-600',on); b.classList.toggle('text-indigo-700',on);
  b.classList.toggle('border-transparent',!on); b.classList.toggle('text-slate-500',!on); }); }
function supSyncInfo(lock){ const el=document.getElementById('sup-sync-info'); if(!el||!lock) return;
  const res=lock.last_result||{}; el.textContent = lock.is_running?'Sync running…':(lock.last_finished_at?`Last sync ${new Date(lock.last_finished_at).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}${res.updated!=null?` · ${res.updated} updated`:''}`:''); }
async function supLoadQueue(quiet){
  const c=document.getElementById('sup-queue-table'); if(c && !quiet) c.innerHTML=brandLoader('Loading queue…');
  try{ _eeHoldAt=0; const d=await supFetch(`/api/support/queue?tab=${_supTab}&`+supRangeQS('queue.'+_supTab)); await eeHoldRefresh(); _supQueueRows=d.rows||[]; _supCapped=!!d.capped; _supTotal=d.total||0; supSyncInfo(d.lock); supQueueTable(); }
  catch(e){ if(c && !quiet) c.innerHTML=`<div class="text-rose-500 text-sm p-8">${escapeHtml(e.message)}</div>`; }   // quiet poll error → keep showing current data
}
// Real-time-ish: quietly re-fetch the queue every 30s WHILE the support view is visible, so agents see
// current holds without a manual refresh. Skipped when hidden or a hold/cancel dialog is open (don't disrupt).
setInterval(()=>{
  const c=document.getElementById('sup-queue-table');
  if(!c || c.offsetParent===null || document.hidden) return;
  if(document.getElementById('sup-confirm-modal')||document.getElementById('sup-cancel-modal')) return;
  supLoadQueue(true);
}, 30000);
// Repeat-tab call-reason tags — shows which of the 3 reasons put this order on the call list.
const SUP_REASON_META={
  in_flight:['🚚','In-flight','bg-sky-100 text-sky-700','Customer has another order still in transit / not yet delivered','bg-sky-50 text-sky-700'],
  recent_undelivered:['⚠️','Recent non-delivery','bg-rose-100 text-rose-700','≥1 of the last 3 orders was not delivered (RTO / undelivered)','bg-rose-50 text-rose-700'],
  high_value:['💰','Above ₹1500','bg-emerald-100 text-emerald-700','Order value is above ₹1500','bg-emerald-50 text-emerald-700'],
  short_address:['📍','Short address','bg-amber-100 text-amber-700','Address is under 60 characters (often incomplete → RTO-prone); skipped if a past order was delivered to the same address','bg-amber-50 text-amber-700'],
};
// Per-ATTEMPT history of the AI auto-caller for the order modal — every dial shows, answered or not
// (an unanswered dial has no transcript row, so the transcript cards alone under-count attempts).
function supAiAttemptsCard(a, title, maxA){
  if(!a||!(a.attempts>0)) return '';
  const mx=maxA||3;
  const RES={no_answer:['no answer','text-violet-700'],confirmed:['confirmed','text-emerald-700'],denied:['denied','text-rose-700'],unclear:['not confirmed','text-amber-700'],failed:['failed','text-rose-700'],gated:['gated (test)','text-slate-400'],reattempt:['reattempt agreed','text-emerald-700'],cancelled:['wants cancel','text-rose-700']};
  const fmt=t=>new Date(t).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
  const raw=Array.isArray(a.attempt_log)?a.attempt_log:[];
  const byN=new Map(); raw.forEach(e=>byN.set(e.n,e));               // one line per attempt — latest state wins
  const log=[...byN.values()];
  const lines=log.map(e=>{const r=RES[e.result]||(e.result?[e.result,'text-slate-500']:['ringing / awaiting result','text-slate-400']);
    const cdr=e.cause?`<span class="text-slate-400">— ${escapeHtml(e.cause)}${e.ring_s!=null?`, ${e.ring_s}s`:''}${e.hangup_by?` · by ${escapeHtml(String(e.hangup_by).toLowerCase())}`:''}</span>`:'';
    return `<div class="flex items-center gap-2 flex-wrap"><span class="font-semibold tabular-nums">#${e.n}</span><span class="text-slate-500 tabular-nums">${fmt(e.at)}</span><span class="${r[1]} font-semibold">${escapeHtml(r[0])}</span>${cdr}</div>`;}).join('');
  const older=a.attempts-log.length;
  const nxt=a.status==='retry'&&a.next_attempt_at?`<div class="text-slate-500 mt-0.5">next attempt ~${fmt(a.next_attempt_at)}</div>`:'';
  const done=a.status==='exhausted'?`<div class="text-violet-700 font-semibold mt-0.5">${mx} calls unanswered — no more auto calls</div>`:'';
  return `<div class="rounded-lg border border-indigo-100 bg-indigo-50/40 p-2.5 text-xs">
    <div class="font-semibold text-indigo-700 mb-1">📞 ${title||'AI dial attempts'} — ${a.attempts} of ${mx}</div>
    ${older>0?`<div class="text-slate-400">${older} earlier attempt${older===1?'':'s'} (before per-attempt logging)</div>`:''}
    ${lines}${nxt}${done}</div>`;
}
// AI COD-confirmation call state (repeat tab) — the chip says what the CALL concluded; only a
// confirmed call ever acts (auto-unhold, server-side). Denied / not-confirmed rows are highlighted
// by conditional row color below and left for a person, by explicit instruction (2026-08-31).
function supAiCallChip(r){ const a=r.ai_call; if(!a) return '';
  const o=a.outcome;
  if(o==='confirmed') return `<span class="px-1.5 py-0.5 rounded text-[10px] font-semibold bg-emerald-50 text-emerald-700" title="AI confirmation call: customer CONFIRMED the order — hold released automatically, release recorded as ai-call (customer confirmed)">📞✅ Confirmed on call</span>`;
  if(o==='denied') return `<span class="px-1.5 py-0.5 rounded text-[10px] font-semibold bg-rose-100 text-rose-700" title="AI confirmation call: ${escapeHtml(a.note||'customer denied on call')} — no automatic action taken, decide manually">📞❌ Denied on call</span>`;
  if(o==='unclear') return `<span class="px-1.5 py-0.5 rounded text-[10px] font-semibold bg-amber-100 text-amber-700" title="AI confirmation call: ${escapeHtml(a.note||'customer did not clearly confirm')} — no automatic action taken, decide manually">📞😕 Not confirmed on call</span>`;
  if(o==='no_answer'||a.status==='exhausted') return `<span class="px-1.5 py-0.5 rounded text-[10px] font-semibold bg-violet-100 text-violet-700" title="AI confirmation call: no answer on 3 attempts (instant, +10 min, +20 min) — no more auto calls, decide manually">📞🔇 No answer (3 calls)</span>`;
  if(a.status==='retry') return `<span class="px-1.5 py-0.5 rounded text-[10px] font-medium bg-slate-100 text-slate-500" title="AI call not answered — will retry automatically (attempt ${(a.attempts||1)+1} of 3)">📞 Retrying ${a.attempts||1}/3</span>`;
  if(a.status==='placed'||a.status==='calling') return `<span class="px-1.5 py-0.5 rounded text-[10px] font-medium bg-slate-100 text-slate-500" title="AI confirmation call placed — outcome pending">📞 AI called</span>`;
  return ''; }
// RTO recovery call chip for the Undelivered tab (user, 2026-09-02: "give called kind of thing —
// not need to open order"): the ladder's state readable straight off the row.
function supRtoCallChip(r){ const a=r.rto_call; if(!a) return '';
  const t=x=>x?new Date(x).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}):'';
  if(a.outcome==='reattempt') return `<span class="px-1.5 py-0.5 rounded text-[10px] font-semibold bg-emerald-50 text-emerald-700" title="AI RTO call: customer agreed to the reattempt">📞✅ Reattempt agreed</span>`;
  if(a.outcome==='cancelled') return `<span class="px-1.5 py-0.5 rounded text-[10px] font-semibold bg-rose-100 text-rose-700" title="AI RTO call: ${escapeHtml(a.note||'customer wants to cancel')}">📞❌ Wants cancel</span>`;
  if(a.outcome==='unclear') return `<span class="px-1.5 py-0.5 rounded text-[10px] font-semibold bg-amber-100 text-amber-700" title="AI RTO call: ${escapeHtml(a.note||'talked, outcome unclear')} — decide manually">📞😕 Unclear on call</span>`;
  if(a.status==='exhausted'||a.outcome==='no_answer') return `<span class="px-1.5 py-0.5 rounded text-[10px] font-semibold bg-violet-100 text-violet-700" title="AI RTO call: no answer — ladder done, no more auto calls">📞🔇 No answer</span>`;
  if(a.status==='retry') return `<span class="px-1.5 py-0.5 rounded text-[10px] font-medium bg-slate-100 text-slate-500" title="AI RTO call not answered — 2nd call ~${t(a.next_at)}">📞 Retry ${t(a.next_at)}</span>`;
  if(a.status==='placed'||a.status==='calling') return `<span class="px-1.5 py-0.5 rounded text-[10px] font-medium bg-slate-100 text-slate-500" title="AI RTO call placed — outcome pending">📞 AI called</span>`;
  if(a.status==='gated') return `<span class="px-1.5 py-0.5 rounded text-[10px] font-medium bg-slate-100 text-slate-400" title="Queued — the engine will dial on its next tick">📞 Queued</span>`;
  return ''; }
// Row tint for the same signal: denied = red wash, not-confirmed = amber wash (repeat tab only).
function supAiRowTint(r){ const a=r.ai_call||{}; const o=a.outcome;
  return o==='denied'?'bg-rose-50':o==='unclear'?'bg-amber-50':(o==='no_answer'||a.status==='exhausted')?'bg-violet-50':''; }
// Courier PLATFORM tag (the aggregator, not the courier) — RapidShyp / DocPharma / KwikShip. Sits next to
// the courier name on the shipped panels so an agent knows which partner portal / escalation route owns the
// parcel before opening it. Server-resolved from shipment_journey_ecom.source (see platformByOrder).
const SUP_PLATFORM_META={
  rapidshyp:['RapidShyp','bg-indigo-50 text-indigo-700 border-indigo-200'],
  docpharma:['DocPharma','bg-teal-50 text-teal-700 border-teal-200'],
  kwikship:['KwikShip','bg-amber-50 text-amber-700 border-amber-200'],
};
function supPlatformTag(p){
  const m=SUP_PLATFORM_META[String(p||'').toLowerCase()]; if(!m) return '';
  return `<span class="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold border ${m[1]} whitespace-nowrap" title="Shipped through ${m[0]} — use this partner for tracking / escalation">${m[0]}</span>`;
}
// Latest courier status, humanised. The feed mixes casings and separators for the same state —
// "Undelivered" / "undelivered", "OUT_FOR_DELIVERY" / "Out for Delivery" — so normalise before showing,
// or the column reads like three different statuses. Colour marks what needs action.
// The label the chip shows AND the value the filter matches — one function, so a status can never be
// offered in the dropdown under a name the column doesn't use.
function supStatusText(r){
  const raw=String(r.tracking_status||'').trim();
  return raw ? raw.replace(/[_-]+/g,' ').toLowerCase().replace(/\b\w/g,c=>c.toUpperCase()) : '';
}
// Options come from the statuses PRESENT in the current tab, with counts. A hardcoded list would go
// stale the moment a courier introduces a status, and would offer choices that match nothing.
// Rebuilt only when the option set actually changes, so it never clobbers a selection mid-use.
function supSyncStatusOptions(rows){
  const sel=document.getElementById('sup-f-status'); if(!sel) return;
  const tally={}; rows.forEach(r=>{ const t=supStatusText(r); if(t) tally[t]=(tally[t]||0)+1; });
  const opts=Object.keys(tally).sort((a,b)=>tally[b]-tally[a]||a.localeCompare(b));
  const sig=opts.map(o=>o+':'+tally[o]).join('|');
  if(sel.dataset.sig===sig) return;
  const keep=sel.value;
  sel.dataset.sig=sig;
  sel.innerHTML='<option value="all">All statuses</option>'+opts.map(o=>`<option value="${escapeHtml(o)}">${escapeHtml(o)} (${tally[o]})</option>`).join('');
  sel.value=opts.includes(keep)?keep:'all';
}
function supStatusChip(r){
  const t=supStatusText(r);
  if(!t) return '<span class="text-slate-300">—</span>';
  const raw=String(r.tracking_status||'');
  const l=t.toLowerCase();
  const cls = /undeliver|exception|lost|damag|misrout/.test(l) ? 'bg-rose-100 text-rose-700'
            : /out for delivery/.test(l)                        ? 'bg-emerald-100 text-emerald-700'
            : /delay/.test(l)                                   ? 'bg-amber-100 text-amber-700'
            :                                                     'bg-slate-100 text-slate-600';
  // HOW MANY TIMES THE COURIER HAS TRIED (user, 2026-09-05: "show attempt count in status along with
  // delivery status. Like OFD Completed 1, OFD Completed 2 … it should show on any status").
  // `attempts` is the courier's own delivery-attempt count from the journey, so the number rides the
  // status whatever that status happens to be — a second attempt is worth seeing on an Out-for-delivery
  // row just as much as on an Undelivered one. Hidden at 0 and 1: "attempt 1" is simply the norm and
  // a badge on every row would carry no information.
  const n = Number(r.delivery_attempts || 0);
  const att = n > 1
    ? `<span class="ml-1 inline-flex items-center justify-center min-w-[1.1rem] h-[1.1rem] px-1 rounded-full bg-white/70 text-[10px] font-bold tabular-nums" title="Courier delivery attempt ${n}">${n}</span>`
    : '';
  return `<span class="inline-flex items-center px-2 py-0.5 rounded-full text-[11px] font-semibold ${cls} whitespace-nowrap" title="${escapeHtml(raw)}${n>1?` · attempt ${n}`:''}">${escapeHtml(t)}${att}</span>`;
}
// ── Call attempts on the row (user, 2026-09-05) ──────────────────────────────────────────────
// The date/time of the LAST attempt, with an ℹ️ that opens every call this order ever received —
// the AI ones from the call log, and the carrier's own per-dial record (ring seconds, hangup cause)
// from the turnstile, which exists for dials that never produced a transcript at all.
const SUP_CALL_KIND={ auto_ai:'Auto AI', manual_ai:'Manual AI', manual:'Manual' };
// ── Manual call — a human agent, bridged through Vobiz (user, 2026-09-05) ────────────────────
// Click-to-call, not a softphone: Vobiz rings the AGENT's own handset and only bridges the customer
// once the agent answers. That ordering is the safety property — if nobody picks up here, the
// customer's phone never rings at all.
// The number is remembered per browser because an agent's handset does not change between calls, and
// re-typing it on every dial is exactly the friction that makes people avoid the button.
function supManualCallDialer(orderName){
  document.getElementById('sup-dialer')?.remove();
  const wrap=document.createElement('div'); wrap.id='sup-dialer';
  // INLINE z-index, not a Tailwind class: z-[86] was never emitted into the compiled CSS, so it
  // resolved to no z-index at all and this dialog opened UNDERNEATH the order-detail modal. The same
  // trap is documented on supTrackOpen above — arbitrary z-[..] values only work if they were built.
  wrap.className='fixed inset-0 flex items-center justify-center bg-slate-900/50 backdrop-blur-[2px] p-4';
  wrap.style.zIndex='96';
  // IT DOES NOT ASK FOR YOUR NUMBER (user, 2026-09-05: "why he asking for number enter manually").
  // Every dashboard user already has a mobile on their profile and the server falls back to it, so
  // the normal path is one click. The field only appears when the server says it has no number for
  // you, or when you deliberately choose a different phone — being asked to retype your own mobile
  // before every call is exactly the friction that stops people using the button.
  wrap.innerHTML=`<div class="bg-white rounded-2xl shadow-2xl w-full max-w-sm">
    <div class="px-6 py-4 border-b border-slate-100 flex items-center justify-between">
      <h3 class="font-semibold text-slate-800">📞 Manual call</h3>
      <button class="text-slate-400 hover:text-slate-600 text-xl leading-none sup-d-x">&times;</button></div>
    <div class="px-6 py-5 space-y-3">
      <p class="text-sm text-slate-600">Calling about <span class="font-semibold">${escapeHtml(orderName)}</span>.</p>
      <p class="text-[13px] text-slate-500">Your phone rings first. Answer it and you will be connected to the customer.</p>
      <div class="sup-d-phonewrap hidden">
        <label class="block text-xs font-semibold text-slate-500">Ring this number instead
          <input class="filter-input w-full mt-1 sup-d-phone" type="tel" inputmode="numeric" placeholder="10-digit mobile"></label>
      </div>
      <div class="sup-d-state text-sm"></div>
      <button class="filter-btn-primary w-full sup-d-go">Call now</button>
      <button class="sup-d-other w-full text-[12px] text-slate-400 hover:text-slate-600">Use a different phone</button>
    </div></div>`;
  document.body.appendChild(wrap);
  const close=()=>wrap.remove();
  wrap.querySelector('.sup-d-x').addEventListener('click',close);
  wrap.addEventListener('click',e=>{ if(e.target===wrap) close(); });
  const go=wrap.querySelector('.sup-d-go'), st=wrap.querySelector('.sup-d-state');
  const pwrap=wrap.querySelector('.sup-d-phonewrap'), pin=wrap.querySelector('.sup-d-phone');
  const other=wrap.querySelector('.sup-d-other');
  const showField=(msg)=>{ pwrap.classList.remove('hidden'); other.classList.add('hidden');
    pin.value=localStorage.getItem('support.agentPhone')||''; pin.focus();
    if(msg) st.innerHTML=`<div class="rounded-lg bg-amber-50 border border-amber-100 p-2.5 text-amber-800 text-[13px]">${escapeHtml(msg)}</div>`; };
  other.addEventListener('click',()=>showField(''));
  go.addEventListener('click', async ()=>{
    const typed=(pin.value||'').replace(/\D/g,'').slice(-10);
    if(typed) localStorage.setItem('support.agentPhone', typed);
    go.disabled=true; go.textContent='⏳ Ringing your phone…';
    st.innerHTML='<span class="text-slate-500">Placing the call…</span>';
    try{
      const d=await supFetch('/api/vobiz/manual-call',{method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({order_name:orderName, agent_phone:typed||undefined})});
      if(!d.success) throw new Error(d.error||'call failed');
      go.textContent='Calling…'; other.classList.add('hidden');
      showNotification('Ringing your phone — answer to connect');
      // LIVE STATE, not a frozen "Calling…" (user, 2026-09-05: "call cut but showing calling").
      // The server knows when the agent picked up and when either side hung up; without polling it
      // the dialog claimed a call was still running long after it ended.
      const paint=(state,secs)=>{
        const mmss=`${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;
        if(state==='ringing') st.innerHTML=`<div class="rounded-lg bg-amber-50 border border-amber-100 p-2.5 text-amber-800 text-[13px]">
          📲 Your phone (${escapeHtml(d.agent)}) is ringing.<br>Answer it to be connected to ${escapeHtml(d.customer)}.</div>`;
        else if(state==='talking') st.innerHTML=`<div class="rounded-lg bg-emerald-50 border border-emerald-100 p-2.5 text-emerald-800 text-[13px]">
          🟢 Connected to ${escapeHtml(d.customer)} · <span class="tabular-nums font-semibold">${mmss}</span></div>`;
        else st.innerHTML=`<div class="rounded-lg bg-slate-100 border border-slate-200 p-2.5 text-slate-700 text-[13px]">
          Call ended${secs?` · lasted <span class="tabular-nums font-semibold">${mmss}</span>`:' — not connected'}.</div>`;
      };
      paint('ringing',0);
      let ticks=0;
      const poll=setInterval(async ()=>{
        ticks++;
        try{
          const st2=await supFetch('/api/vobiz/manual-call/'+encodeURIComponent(d.id));
          paint(st2.state==='unknown'?'ended':st2.state, st2.seconds||0);
          if(st2.state==='ended'||st2.state==='unknown'){
            clearInterval(poll); go.textContent='Call again'; go.disabled=false; other.classList.remove('hidden');
            // the row's Called column and ℹ️ history are now a call behind
            if(typeof supLoadQueue==='function' && currentView==='support-queue') supLoadQueue(true);
          }
        }catch(_){ /* a blip must not freeze the dialog on a stale state */ }
        if(ticks>150){ clearInterval(poll); }        // 5 minutes is longer than any of these calls
      },2000);
    }catch(e){
      go.disabled=false; go.textContent='Call now';
      // The one error worth handling specially: no number on file. Reveal the field rather than
      // leaving the user to guess what to do about it.
      if(/phone number is needed|own phone/i.test(e.message)) showField('No mobile saved on your profile — enter the phone to ring.');
      else st.innerHTML=`<div class="rounded-lg bg-rose-50 border border-rose-100 p-2.5 text-rose-700 text-[13px]">${escapeHtml(e.message)}</div>`;
    }
  });
}

// The call-date filter — a SECOND range, on when we rang, applied on top of the header range rather
// than instead of it (user, 2026-09-05: "add call log date filter along with current date filter and
// it should work simultaneously"). The header range decides which parcels are in the queue at all;
// this one narrows those to the ones called in a given window. A row with no call in the window drops
// out, including one never called — "called yesterday" cannot honestly include a row we never rang.
function supCallDateWindow(){
  const sel=document.getElementById('sup-f-calldate')?.value||'all';
  const custom=document.getElementById('sup-f-calldate-custom');
  if(custom) custom.className = sel==='custom' ? 'flex items-center gap-1' : 'hidden items-center gap-1';
  if(sel==='all') return null;
  if(sel==='custom'){
    const f=document.getElementById('sup-f-callfrom')?.value, t=document.getElementById('sup-f-callto')?.value;
    return (f&&t)?{from:f,to:t}:null;          // an incomplete custom range filters nothing, never everything
  }
  const d=new Date();
  if(sel==='y'){ const y=new Date(d.getFullYear(),d.getMonth(),d.getDate()-1); return {from:_ymd(y),to:_ymd(y)}; }
  const back=Math.max(0,(+sel)-1);
  return { from:_ymd(new Date(d.getFullYear(),d.getMonth(),d.getDate()-back)), to:_ymd(d) };
}
// Compared as LOCAL calendar days, the same way the dates in the picker are read — an ISO timestamp
// sliced to 10 chars would be UTC and would put an evening IST call on the previous day.
function supCalledInWindow(r, w){
  const a=r.call_attempts; if(!a) return false;
  const days=[...(a.log||[]).map(c=>c.at), a.last_at].filter(Boolean).map(t=>_ymd(new Date(t)));
  return days.some(d=>d>=w.from && d<=w.to);
}
function supCallCell(r){
  const a=r.call_attempts;
  if(!a||!a.last_at) return '<span class="text-slate-300">—</span>';
  const kinds=(a.kinds||[]).map(k=>SUP_CALL_KIND[k]||k).join(' · ');
  return `<div class="whitespace-nowrap"><span class="tabular-nums text-slate-600">${supDT(a.last_at)}</span>
    <button class="sup-callinfo ml-1 align-middle text-indigo-500 hover:text-indigo-700" data-oid="${escapeHtml(r.order_id)}" title="Every call on this order">ℹ️</button>
    ${kinds?`<div class="text-[10px] text-slate-400">${escapeHtml(kinds)}${a.count>1?` · ${a.count} calls`:''}</div>`:''}</div>`;
}
function supCallLogHtml(r){
  const a=r.call_attempts||{};
  const rows=(a.log||[]).map(c=>{
    const tone=/reattempt|confirmed/i.test(c.outcome)?'text-emerald-700':/cancel/i.test(c.outcome)?'text-rose-600':'text-slate-600';
    return `<div class="py-1.5 border-b border-slate-100 last:border-0">
      <div class="flex items-center gap-2 flex-wrap text-[11px]">
        <span class="tabular-nums text-slate-500">${supDT(c.at)}</span>
        <span class="px-1.5 py-0.5 rounded bg-slate-100 text-slate-600">${escapeHtml(SUP_CALL_KIND[c.kind]||c.kind)}</span>
        <span class="text-slate-400">${escapeHtml(c.type||'')}</span>
        ${c.seconds?`<span class="tabular-nums text-slate-400">${c.seconds}s</span>`:''}
        ${c.by?`<span class="text-slate-400">by ${escapeHtml(supPrettyUser(c.by))}</span>`:''}
      </div>
      <div class="text-[12px] ${tone} mt-0.5">${escapeHtml(c.outcome||'—')}</div></div>`;
  }).join('');
  // The carrier's view of the same order: dials that rang and were never answered leave no transcript,
  // so without this the log would silently omit them and look like fewer attempts than really happened.
  const dial=(a.dial||[]).map(d=>{
    const att=(d.log||[]).map(x=>`<div class="flex gap-2 text-[11px] text-slate-500 py-0.5">
        <span class="w-8 text-slate-400">#${x.n||'?'}</span><span class="w-28 tabular-nums">${x.at?supDT(x.at):''}</span>
        <span class="w-24">${escapeHtml(x.result||'')}</span><span class="w-14 text-right tabular-nums">${x.ring_s!=null?x.ring_s+'s':''}</span>
        <span>${escapeHtml(x.cause||'')}</span></div>`).join('')||'<p class="text-[11px] text-slate-400">no carrier record</p>';
    return `<div class="mt-2"><p class="text-[10px] uppercase tracking-wide text-slate-400">${escapeHtml(d.purpose||'')} · ${escapeHtml(d.status||'')}${d.attempts?` · ${d.attempts} attempt${d.attempts>1?'s':''}`:''}</p>${att}
      ${d.next_at?`<p class="text-[11px] text-amber-700 mt-0.5">retry ${supDT(d.next_at)}</p>`:''}</div>`;
  }).join('');
  return `<div class="text-left"><p class="font-semibold text-slate-700 mb-1">Calls on ${escapeHtml(r.order_name||r.order_id)}</p>
    ${rows||'<p class="text-[12px] text-slate-400">No AI call reached this order.</p>'}${dial}</div>`;
}
// "Raised to the courier" — was only ever a free-text note ("raised", "raised with VOC"), so it could
// not be filtered, sorted or counted. Now a stored mark with its own date.
const SUP_RAISE_LABEL={ raised:'Raised', raised_voc:'Raised · VOC', customer_rto:'Customer RTO' };
function supRaisedCell(r){
  if(!r.raised_kind) return '<span class="text-slate-300">—</span>';
  // Amber for customer_rto: it is not an escalation we are chasing, it is the customer closing the
  // order themselves, and the queue should read that difference at a glance.
  const cls = r.raised_kind==='customer_rto' ? 'bg-amber-100 text-amber-800'
    : r.raised_kind==='raised_voc' ? 'bg-violet-100 text-violet-700' : 'bg-sky-100 text-sky-700';
  const by = r.raised_by ? ' by '+supPrettyUser(r.raised_by) : '';
  return `<span class="inline-flex px-1.5 py-0.5 rounded text-[10px] font-bold ${cls} whitespace-nowrap" title="Raised${escapeHtml(by)} on ${r.raised_at?new Date(r.raised_at).toLocaleString():''}">${SUP_RAISE_LABEL[r.raised_kind]||'Raised'}</span>
    <div class="text-[10px] text-slate-400 mt-0.5 tabular-nums">${r.raised_at?_dmy(r.raised_at):''}</div>`;
}
// Native <select> rather than a hand-rolled menu: no popup positioning to get wrong inside a scrolling
// table, and it works on touch. Resets to the placeholder after each choice so it reads as an action.
// One definition of the option list, used by the initial render AND by the in-place patch below, so a
// row that has just been marked offers exactly the same choices as one rendered fresh.
function supRaiseOptions(k){
  return `<option value="" ${k?'':'selected'}>${k?'Change…':'Raise ▾'}</option>
      <option value="raised" ${k==='raised'?'selected':''}>Raised</option>
      <option value="raised_voc" ${k==='raised_voc'?'selected':''}>Raised with VOC</option>
      <option value="customer_rto" ${k==='customer_rto'?'selected':''}>Customer Requested RTO</option>
      ${k?'<option value="__clear">Clear</option>':''}`;
}
function supRaiseControl(r){
  return `<select class="sup-raise filter-select" style="height:30px;font-size:11px;padding:0 6px" data-oname="${escapeHtml(r.order_name||'')}" title="Record that this was raised with the courier partner">
      ${supRaiseOptions(r.raised_kind||'')}
    </select>`;
}
const _supKey = n => String(n||'').replace('#','').trim();
// Repaint JUST this order's raised chip and its dropdown — never the table.
//
// ⚠️ The options are rewritten IN PLACE rather than by replacing the <select>. These selects are
// upgraded by ecEnhanceSelect() into a .csel wrapper (button + panel are siblings of the real select);
// swapping the element would leave the new one orphaned inside the old wrapper with a dead button.
// ecSyncSelect() repaints that button, since setting .value in code fires no 'change' event.
function supPatchRaise(orderName, pending){
  const key=_supKey(orderName);
  const row=(_supQueueRows||[]).find(x=>_supKey(x.order_name)===key);
  if(!row) return;
  document.querySelectorAll('#sup-queue-table .sup-raise').forEach(sel=>{
    if(_supKey(sel.dataset.oname)!==key) return;
    const tr=sel.closest('tr');
    const cell=tr&&tr.querySelector('.sup-raised-cell');
    if(cell){
      cell.innerHTML=supRaisedCell(row);
      // Half-opacity while the write is in flight: the mark is on screen instantly, but it is honest
      // about not being saved yet, so a failure that reverts it is not a surprise.
      cell.style.opacity = pending ? '.45' : '';
    }
    const k=row.raised_kind||'';
    sel.innerHTML=supRaiseOptions(k);
    sel.value=k||'';
    sel.disabled=!!pending;
    ecSyncSelect(sel);
  });
}
// Optimistic: the chip changes the moment the agent chooses, not after the round-trip. An agent works
// this queue row by row, and a control that does nothing for ~300ms gets clicked twice.
async function supDoRaise(orderName, value, sel){
  if(!value) return;
  const kind = value==='__clear' ? null : value;
  const row=(_supQueueRows||[]).find(x=>_supKey(x.order_name)===_supKey(orderName));
  const prev = row ? { kind:row.raised_kind, at:row.raised_at, by:row.raised_by } : null;
  if(row){
    row.raised_kind=kind;
    row.raised_at=kind?new Date().toISOString():null;
    row.raised_by=kind?((typeof currentUser!=='undefined'&&currentUser&&currentUser.email)||row.raised_by||''):null;
  }
  supPatchRaise(orderName, true);
  try{
    const d=await supFetch('/api/support/raise',{ method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({ orderName, kind }) });
    // Take the SERVER's values, not the guess — it owns the timestamp and the acting user.
    if(row){ row.raised_kind=d.raised?d.raised.kind:null; row.raised_at=d.raised?d.raised.at:null; row.raised_by=d.raised?d.raised.by:null; }
    supPatchRaise(orderName, false);
    showNotification(kind?`${SUP_RAISE_LABEL[kind]} saved — ${orderName}`:`Raised mark cleared — ${orderName}`);
  }catch(e){
    // Put the row back exactly as it was, so the screen never claims something that was not stored.
    if(row&&prev){ row.raised_kind=prev.kind; row.raised_at=prev.at; row.raised_by=prev.by; }
    supPatchRaise(orderName, false);
    showNotification(`Could not save — ${orderName}: ${e.message}`, true);
  }
}
function supReasonChips(r){
  if(!r.reasons||!r.reasons.length) return '';
  return r.reasons.map(k=>{ const m=SUP_REASON_META[k]; if(!m) return '';
    return `<span class="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-medium ${m[4]||m[2]} whitespace-nowrap align-middle" title="${m[3]}">${m[0]} ${m[1]}</span>`; }).join(' ');
}
// Column comparator for header-click sorting. Time columns (created_at / last_scan_at) compare by epoch
// with empty values ALWAYS last (regardless of direction); other columns are case-insensitive strings.
function _supSortCmp(k,d){ const isTime=(k==='created_at'||k==='last_scan_at'||k==='raised_at'||k==='escalated_at');
  return (a,b)=>{ if(isTime){ const x=a[k]?new Date(a[k]).getTime():null, y=b[k]?new Date(b[k]).getTime():null;
      if(x===null&&y===null) return 0; if(x===null) return 1; if(y===null) return -1; return d*(x-y); }
    return d*String(a[k]||'').toLowerCase().localeCompare(String(b[k]||'').toLowerCase()); }; }
// Date AND time for the Escalated column — "when did this actually leave" is the point of it.
const supDT = iso => { const d=new Date(iso); return `${_dmy(iso)}, ${d.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}`; };
// Combined escalation viewer — the SAME renderers Delivery Performance uses (dpThreadHtml /
// dpSheetThreadHtml), fed through their caches and shown in a modal, because Call Queue rows open the
// order popup on click and have no inline expansion to render into.
async function supEscThreadModal(awb, kinds){
  const wrap=document.createElement('div');
  wrap.className='dp-sheet-overlay fixed inset-0 flex items-center justify-center bg-slate-900/50 p-4';
  wrap.innerHTML=`<div class="bg-white rounded-2xl shadow-2xl w-full max-w-2xl p-6 max-h-[82vh] overflow-y-auto">
    <div class="flex items-center justify-between"><h3 class="text-lg font-bold text-slate-800">📨 Escalation & responses — ${ecEsc(awb)}</h3><button id="set-x" class="text-slate-400 text-xl hover:text-slate-600">✕</button></div>
    <div id="set-body" class="mt-2">${brandLoaderSm('Loading escalation…')}</div></div>`;
  document.body.appendChild(wrap);
  const close=()=>wrap.remove();
  wrap.addEventListener('click',e=>{ if(e.target===wrap) close(); });
  wrap.querySelector('#set-x').addEventListener('click',close);
  let html='';
  try{
    if(kinds.includes('mail')){
      const r=await fetch('/api/escalation-emails?awb='+encodeURIComponent(awb),{ headers:getAuthHeaders() });
      const d=await r.json();
      _dpThreadCache[awb]={ loading:false, threads:d.threads||[] }; html+=dpThreadHtml(awb); delete _dpThreadCache[awb];
    }
    if(kinds.includes('sheet')){
      const r=await fetch('/api/escalation-sheet/thread/'+encodeURIComponent(awb),{ headers:getAuthHeaders() });
      const d=await r.json();
      _dpSheetCache[awb]={ loading:false, entries:d.entries||[] }; html+=dpSheetThreadHtml(awb); delete _dpSheetCache[awb];
    }
  }catch(e){ html=`<div class="text-xs text-rose-500">${ecEsc(e.message)}</div>`; }
  const body=wrap.querySelector('#set-body'); if(body) body.innerHTML=html||'<div class="text-xs text-slate-400">No escalation records for this AWB.</div>';
}
// 🧺 on the Call Queue · Undelivered tab — the escalation basket's home for the support team
// (user, 2026-08-19: "shift add to basket thing in Call Queue Undelivered page"). Same basket, same
// localStorage, same floating bar as Delivery Performance — an order added here pushes identically.
function supBasketBtn(r){
  if(_supTab!=='und'||!r.awb_number) return '';
  const inB=_dpBasket.has(r.awb_number);
  return `<button class="sup-basket-btn inline-flex items-center gap-1 px-2 py-1.5 rounded-lg text-[11px] font-semibold border transition-colors ${inB?'bg-slate-700 text-white border-slate-700':'bg-white text-slate-500 border-slate-200 hover:border-slate-400'}" data-awb="${escapeHtml(r.awb_number)}" data-oname="${escapeHtml(r.order_name||'')}" data-plat="${escapeHtml(r.platform||'')}" title="${inB?'In escalation basket — click to remove':'Add to escalation basket (sheet / email)'}">🧺${inB?' ✓':''}</button>`;
}
function supQueueTable(){
  const c=document.getElementById('sup-queue-table'); if(!c) return;
  const fN=document.getElementById('sup-f-notes')?.value||'all';
  const fQ=(document.getElementById('sup-f-notesearch')?.value||'').trim().toLowerCase();
  const fA=document.getElementById('sup-f-age')?.value||'any';
  const fH=document.getElementById('sup-f-hold')?.value||'all';
  const fP=document.getElementById('sup-f-pay')?.value||'all';
  // Courier platform. Only meaningful once a shipment exists, so the control is hidden on Repeat — and
  // forced back to 'all' there, otherwise a filter left set on Undelivered would silently empty that tab.
  const platSel=document.getElementById('sup-f-platform'), platOn=_supTab!=='repeat';
  if(platSel){ platSel.style.display=platOn?'':'none'; if(!platOn) platSel.value='all'; }
  const fL=platOn?(platSel?.value||'all'):'all';
  // Status options are derived from the rows this tab actually holds — populate before reading the value.
  const statusSel=document.getElementById('sup-f-status');
  if(statusSel){ statusSel.style.display=platOn?'':'none'; if(!platOn) statusSel.value='all'; }
  if(platOn) supSyncStatusOptions(_supQueueRows);
  const fS=platOn?(statusSel?.value||'all'):'all';
  const raisedSel=document.getElementById('sup-f-raised');
  if(raisedSel){ raisedSel.style.display=platOn?'':'none'; if(!platOn) raisedSel.value='all'; }
  const fR=platOn?(raisedSel?.value||'all'):'all';
  // Call type filters on every tab: a COD confirmation on Hold Orders is as real as an RTO dial on
  // Undelivered, so this one is not hidden with the shipped-only filters above.
  const fC=document.getElementById('sup-f-calltype')?.value||'all';
  const fCD=supCallDateWindow();
  const clear=document.getElementById('sup-f-clear'); if(clear) clear.style.display=(fN!=='all'||fQ||fA!=='any'||fH!=='all'||fP!=='all'||fL!=='all'||fR!=='all'||fC!=='all'||!!fCD||fS!=='all'||_supSort)?'':'none';
  let list=_supQueueRows.slice();
  if(fCD) list=list.filter(r=>supCalledInWindow(r,fCD));
  if(fC!=='all') list=list.filter(r=>{ const a=r.call_attempts;
    if(fC==='none') return !a||!a.last_at;
    if(fC==='any')  return !!(a&&a.last_at);
    return !!(a&&(a.kinds||[]).includes(fC)); });
  if(fN==='with') list=list.filter(r=>r.note_count>0);
  if(fN==='none') list=list.filter(r=>!r.note_count);
  // One box, every identifier an agent actually has to hand: order no, AWB, phone, email, name, note.
  // Digits are matched separately so a pasted "+91 72475 71477" finds the stored "7247571477" — the
  // formats differ per order, which is why a plain substring test on the raw phone kept missing.
  if(fQ){
    const qDigits=fQ.replace(/\D/g,'');
    list=list.filter(r=>{
      const hay=[r.order_name,r.order_id,r.awb_number,r.customer_name,r.email,r.latest_note,r.courier]
        .filter(Boolean).join(' ').toLowerCase();
      if(hay.includes(fQ)) return true;
      if(qDigits.length>=4){
        const phone=String(r.phone||'').replace(/\D/g,'');
        const awb=String(r.awb_number||'').replace(/\D/g,'');
        if(phone.includes(qDigits)||awb.includes(qDigits)) return true;
      }
      return false;
    });
  }
  if(fA!=='any') list=list.filter(r=>{ const dAge=(Date.now()-new Date(r.created_at))/86400000;
    return fA==='lt1'?dAge<1:fA==='1-3'?(dAge>=1&&dAge<3):fA==='3-7'?(dAge>=3&&dAge<7):dAge>=7; });
  if(fH!=='all'){ const isHeld=r=>(r.shopify_hold&&r.shopify_hold.status==='held')||r.ee_hold; list=list.filter(r=>fH==='held'?isHeld(r):!isHeld(r)); }
  if(fP!=='all') list=list.filter(r=>String(r.payment||'').toLowerCase()===fP);
  // 'none' = the server couldn't resolve a platform (no journey row yet, no usable partner/courier) —
  // worth being able to isolate, since those are the rows whose tracking nobody is syncing.
  if(fL!=='all') list=list.filter(r=>{ const p=String(r.platform||'').toLowerCase(); return fL==='none'?!p:p===fL; });
  // Raised filter — the point of storing it rather than leaving it in a note.
  if(fR!=='all') list=list.filter(r=> fR==='none' ? !r.raised_kind : fR==='any' ? !!r.raised_kind : r.raised_kind===fR);
  if(fS!=='all') list=list.filter(r=>supStatusText(r)===fS);
  if(_supSort&&_supSort.k) list.sort(_supSortCmp(_supSort.k,_supSort.d));   // else keep the server order (confirmed → oldest)
  // Say when the SERVER truncated, not just how many survived the client filters — otherwise a capped
  // tab reads as complete. Only meaningful with no client filter narrowing the list further.
  const cnt=document.getElementById('sup-queue-count');
  if(cnt) cnt.textContent = (_supCapped && list.length===_supQueueRows.length)
    ? `${list.length} of ${_supTotal} — narrow the dates to see the rest` : `${list.length} shown`;
  document.querySelector(`.sup-tab[data-tab="${_supTab}"] .sup-tab-count`).textContent=`(${list.length})`;
  if(!list.length){ c.innerHTML='<div class="text-slate-400 text-sm p-10 text-center">Queue is clear 🎉</div>'; return; }
  const TH='px-3 py-2.5 text-left text-[11px] font-semibold text-slate-400 uppercase tracking-wider border-b border-slate-200 bg-slate-50/60 whitespace-nowrap';
  const TD='px-3 py-2.5 text-sm text-slate-700 border-b border-slate-100 align-middle';
  // Click a column header to sort (asc/desc toggle); the caret shows the active column + direction.
  // The "Last scan" column is only meaningful for Undelivered (in-transit) orders — hidden on Repeat/Status-changed.
  const showScan=_supTab==='und';
  // Rejected COD rows are customer replies, mostly pre-dispatch: no shipment columns, and a Rejected
  // column carrying WHEN and the exact words — the reply text is the evidence the row exists.
  const isRejTab=_supTab==='rejected';
  const showBucket=_supTab!=='repeat';   // every Repeat row is order_to_dispatch → the Bucket column is noise
  // Payment (COD / Prepaid) — shown on Undelivered + Status-changed. Hidden on Repeat, which is COD-only
  // by definition (fully-prepaid orders are never repeat candidates), so the column would be noise there.
  const showPay=_supTab!=='repeat';
  // Courier-platform tag — only the shipped panels carry one (Repeat orders are pre-dispatch, no shipment yet).
  const showPlat=_supTab!=='repeat';
  // On the shipped tabs the Bucket column said "Undelivered" on every single row — the tab already tells
  // you that. It now shows the order's LATEST COURIER STATUS, which is the thing that actually differs.
  const COLS=isRejTab
    ?[{h:'Order',k:'order_name',d:1},{h:'Customer',k:null},{h:'Rejected',k:'rejected_at',d:-1},
      {h:'Reply',k:null},{h:'Status',k:'tracking_status',d:1},{h:'Age',k:'created_at',d:1},{h:'Actions',k:null}]
    :[{h:'Order',k:'order_name',d:1},{h:'Customer',k:null},
    ...(showBucket?[showPlat?{h:'Status',k:'tracking_status',d:1}:{h:'Bucket',k:'bucket',d:1}]:[]),
    ...(showPay?[{h:'Payment',k:'payment',d:1}]:[]),{h:'Age',k:'created_at',d:1},{h:'Courier',k:'courier',d:1},
    ...(showScan?[{h:'Last scan',k:'last_scan_at',d:-1}]:[]),
    // Called — on BOTH panels, because a COD confirmation on Hold Orders is as worth seeing as an
    // RTO dial on Undelivered. Sorts on the last attempt, so never-called rows gather at one end.
    {h:'Called',k:'call_last_at',d:-1},
    ...(showPlat?[{h:'Raised',k:'raised_at',d:-1}]:[]),
    ...(_supTab==='und'?[{h:'Escalated',k:'escalated_at',d:-1}]:[]),{h:'Actions',k:null}];
  const thHtml=COLS.map(col=>{ if(!col.k) return `<th class="${TH}">${col.h}</th>`;
    const on=_supSort&&_supSort.k===col.k; const car=on?(_supSort.d===1?'▲':'▼'):'<span class="text-slate-300">↕</span>';
    return `<th class="${TH} cursor-pointer select-none hover:text-indigo-600 ${on?'text-indigo-600':''}" data-sort="${col.k}" data-dir="${col.d}" title="Sort by ${col.h}">${col.h} <span class="text-[9px]">${car}</span></th>`; }).join('');
  // Flag customers who have MORE THAN ONE order sitting in this queue right now (concurrent / duplicate orders).
  const _phoneCount={}; list.forEach(x=>{ const p=String(x.phone||'').replace(/\D/g,'').slice(-10); if(p) _phoneCount[p]=(_phoneCount[p]||0)+1; });
  c.innerHTML=`<table class="w-full"><thead><tr>${thHtml}</tr></thead><tbody>${
    list.slice(0,500).map(r=>{ const ph=String(r.phone||'').replace(/\D/g,'').slice(-10); const dupN=ph?(_phoneCount[ph]||0):0;
      if(isRejTab){
        // The customer said no, in writing. The reply text IS the row's reason to exist, so it is shown
        // verbatim; a rejection the webhook could not pin to an order still appears (phone-only row) —
        // an invisible rejection is how a told-you-so parcel ships anyway.
        return `<tr class="sup-row cursor-pointer hover:bg-slate-50" data-oid="${escapeHtml(r.order_id)}">
        <td class="${TD} font-mono font-semibold">${r.order_name?escapeHtml(r.order_name)+eeHoldChip(r.order_name):'<span class="text-slate-400" title="The reply carried no order number — matched by phone only">unmatched</span>'}</td>
        <td class="${TD}"><div class="flex items-center gap-1.5 flex-wrap">
          ${ph?`<a href="tel:+91${ph}" onclick="event.stopPropagation()" class="text-indigo-600 font-semibold hover:underline tabular-nums">${ph}</a>`:'<span class="text-slate-300">no phone</span>'}
          ${r.reject_customer?`<span class="text-xs text-slate-500">${escapeHtml(r.reject_customer)}</span>`:''}
        </div></td>
        <td class="${TD} whitespace-nowrap"><span class="px-2 py-0.5 rounded-full text-[11px] font-semibold bg-rose-100 text-rose-700">Rejected</span>
          <div class="text-[10px] text-slate-500 tabular-nums mt-0.5">${supDT(r.rejected_at)}</div></td>
        <td class="${TD}"><span class="text-xs text-slate-600 italic">“${escapeHtml(r.reject_reply||'—')}”</span></td>
        <td class="${TD}">${r.tracking_status?supStatusChip(r):'<span class="text-slate-300" title="Not dispatched — the rejection arrived before the parcel moved">not dispatched</span>'}</td>
        <td class="${TD}"><span class="font-semibold tabular-nums">${supAge(r.rejected_at)}</span> <span class="text-xs text-slate-400">${_dmy(r.rejected_at)}</span></td>
        <td class="${TD}"><div class="flex items-center gap-1.5 flex-wrap">${r.order_name?supHoldControl(r):''}
          <button style="flex-shrink:0" class="sup-note-btn inline-flex items-center gap-1 px-2 py-1.5 rounded-lg text-[11px] font-semibold border transition-colors ${r.note_count?'bg-amber-50 text-amber-700 border-amber-200 hover:bg-amber-100':'bg-white text-slate-400 border-slate-200 hover:border-indigo-300 hover:text-indigo-600'}" data-oid="${escapeHtml(r.order_id)}" data-oname="${escapeHtml(r.order_name||'')}" title="${r.note_count?'View / add notes':'Add a note'}">📝${r.note_count?` <span class="min-w-[16px] h-4 px-1 rounded-full bg-amber-200/80 text-amber-800 text-[10px] leading-4 text-center">${r.note_count}</span>`:' <span class="font-medium">+</span>'}</button>
        </div></td></tr>`;
      }
      return `<tr class="sup-row cursor-pointer hover:bg-slate-50 ${supAiRowTint(r)||(r.msg91_confirmed?'bg-sky-50/50':'')}" data-oid="${escapeHtml(r.order_id)}">
      <td class="${TD} font-mono font-semibold"${dupN>1?' style="border-left:4px solid #d946ef"':''}>${escapeHtml(r.order_name||r.order_id)}${_supTab!=='repeat'?eeHoldChip(r.order_name):''}</td>
      <td class="${TD}">
        <div class="flex items-center gap-1.5 flex-wrap">
          ${ph?`<a href="tel:+91${ph}" onclick="event.stopPropagation()" class="text-indigo-600 font-semibold hover:underline tabular-nums">${ph}</a>`:'<span class="text-slate-300">no phone</span>'}
          ${r.orders_count?`<span class="px-1.5 py-0.5 rounded text-[10px] font-medium bg-slate-100 text-slate-500" title="${r.orders_count} order${r.orders_count>1?'s':''} on record for this customer">${r.orders_count} order${r.orders_count>1?'s':''}</span>`:''}
          ${dupN>1?`<span class="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold" style="background:#fdf4ff;color:#a21caf" title="This customer has ${dupN} orders in the queue right now — likely duplicate / concurrent orders">🔁 ${dupN}×</span>`:''}
          ${r.msg91_confirmed?`<span class="px-1.5 py-0.5 rounded text-[10px] font-medium bg-sky-50 text-sky-700" title="Customer confirmed via MSG91">✓ Confirmed</span>`:''}
        </div>
        ${_supTab==='repeat'&&((r.reasons&&r.reasons.length)||r.ai_call)?`<div class="flex items-center gap-1 flex-wrap mt-1">${r.reasons&&r.reasons.length?supReasonChips(r):''}${supAiCallChip(r)}</div>`:''}
        ${_supTab==='und'&&r.rto_call?`<div class="flex items-center gap-1 flex-wrap mt-1">${supRtoCallChip(r)}</div>`:''}
      </td>
      ${showBucket?`<td class="${TD}">${showPlat?supStatusChip(r):supBadge(r.bucket)}</td>`:''}
      ${showPay?`<td class="${TD}">${supPayChip(r)}</td>`:''}
      <td class="${TD}"><span class="font-semibold tabular-nums">${supAge(r.created_at)}</span> <span class="text-xs text-slate-400">${_dmy(r.created_at)}</span></td>
      <td class="${TD}"><div class="flex items-center gap-1.5 flex-wrap">${escapeHtml((r.courier||'—').replace(/\b\w/g,ch=>ch.toUpperCase()))}${showPlat?supPlatformTag(r.platform):''}</div>${r.awb_number?`<div class="text-[10px] mt-0.5">${supAwbLink(r.awb_number,r.order_name,r.courier)}</div>`:''}</td>
      ${showScan?`<td class="${TD} whitespace-nowrap">${r.last_scan_at?`<span class="text-slate-500" title="Latest AWB scan by courier: ${new Date(r.last_scan_at).toLocaleString()}">🛰 ${supRelTime(r.last_scan_at)}</span>`:'<span class="text-slate-300">—</span>'}</td>`:''}
      <td class="${TD}">${supCallCell(r)}</td>
      ${showPlat?`<td class="${TD} whitespace-nowrap sup-raised-cell">${supRaisedCell(r)}</td>`:''}
      ${_supTab==='und'?`<td class="${TD} whitespace-nowrap">${r.escalated_at?`<button class="sup-esc-view text-left" data-awb="${escapeHtml(r.awb_number||'')}" data-kinds="${escapeHtml(r.escalated_kind||'')}" title="View the escalation and any responses">
          <div class="flex items-center gap-1">${String(r.escalated_kind||'').includes('sheet')?'📋':''}${String(r.escalated_kind||'').includes('mail')?'✉️':''}<span class="text-[11px] font-semibold text-indigo-600 hover:underline">view</span></div>
          <div class="text-[10px] text-slate-500 tabular-nums">${supDT(r.escalated_at)}</div></button>`:'<span class="text-slate-300">—</span>'}</td>`:''}
      <td class="${TD}"><div class="flex items-start gap-2">
        <div class="flex-1 min-w-0 space-y-1.5">
          <div class="flex items-center gap-1.5 flex-wrap">${supHoldControl(r)}${showPlat?supRaiseControl(r):''}${supBasketBtn(r)}</div>
          ${r.latest_note?`<div class="min-w-0 border-l-2 border-slate-200 pl-2">
            <div class="text-xs text-slate-500 italic truncate max-w-[260px]" title="${escapeHtml(r.latest_note)}">“${escapeHtml(r.latest_note)}”</div>
            <div class="text-[10px] text-slate-400 truncate">${escapeHtml(r.latest_note_by||'')}${r.latest_note_by&&r.latest_note_at?' · ':''}${r.latest_note_at?supRelTime(r.latest_note_at):''}</div></div>`:''}
        </div>
        <button style="flex-shrink:0" class="sup-note-btn inline-flex items-center gap-1 px-2 py-1.5 rounded-lg text-[11px] font-semibold border transition-colors ${r.note_count?'bg-amber-50 text-amber-700 border-amber-200 hover:bg-amber-100':'bg-white text-slate-400 border-slate-200 hover:border-indigo-300 hover:text-indigo-600'}" data-oid="${escapeHtml(r.order_id)}" data-oname="${escapeHtml(r.order_name||'')}" title="${r.note_count?'View / add notes':'Add a note'}">📝${r.note_count?` <span class="min-w-[16px] h-4 px-1 rounded-full bg-amber-200/80 text-amber-800 text-[10px] leading-4 text-center">${r.note_count}</span>`:' <span class="font-medium">+</span>'}</button></div></td></tr>`; }).join('')
  }</tbody></table>${list.length>500?`<div class="text-xs text-slate-400 p-3 text-center">Showing first 500 of ${list.length}</div>`:''}`;
  c.querySelectorAll('th[data-sort]').forEach(th=>th.addEventListener('click',()=>{
    const k=th.dataset.sort, dd=parseInt(th.dataset.dir,10)||1;
    if(_supSort&&_supSort.k===k) _supSort.d*=-1; else _supSort={k,d:dd};   // toggle direction on the same column
    supQueueTable(); }));
  c.querySelectorAll('.sup-basket-btn').forEach(b=>b.addEventListener('click',e=>{ e.stopPropagation();
    const awb=b.dataset.awb;
    if(_dpBasket.has(awb)){ dpBasketToggle(awb); return; }                        // remove — no popup
    // Sheet details (type/reason) only exist for RapidShyp — the sheet is theirs. Anything else goes
    // straight into the basket; its escalation exit is the ✉️ email (user, 2026-08-19).
    if(_dpBasket.size>=DP_BASKET_MAX) return showNotification(`Basket is full (${DP_BASKET_MAX} orders max).`, true);
    if(String(b.dataset.plat||'').toLowerCase()==='rapidshyp') dpBasketReasonModal(awb,{ order:b.dataset.oname||awb, plat:'rapidshyp' });
    else { _dpBasket.add(awb); _dpBasketPlats[awb]=String(b.dataset.plat||'').toLowerCase(); dpBasketSave(); dpBasketRepaintAll(); showNotification('Added — escalates by ✉️ email (not on the RapidShyp sheet)'); }
  }));
  c.querySelectorAll('.sup-esc-view').forEach(b=>b.addEventListener('click',e=>{ e.stopPropagation();
    supEscThreadModal(b.dataset.awb, String(b.dataset.kinds||'').split('+')); }));
  dpBasketRenderBar();   // the floating bar lives on this view too
  // Clicking a row opens the order modal — but NEVER when the click landed on a control inside it.
  // ⚠️ `.csel` is the one that actually bit: ecEnhanceSelect() moves the real <select> into a wrapper and
  // puts the visible button and the option list BESIDE it as siblings, so a stopPropagation bound to the
  // <select> never sees the click that really happened. Choosing "Raised" therefore saved the mark AND
  // opened the order popup on top of the confirmation. Guarding on the ANCESTOR covers the button, the
  // panel and every option row at once, and keeps working if the widget's internals ever change.
  c.querySelectorAll('.sup-row').forEach(row=>row.addEventListener('click',e=>{
    if(e.target.closest('.csel, select, button, a, input, label')) return;
    supOrderModal(row.dataset.oid);
  }));
  c.querySelectorAll('.sup-callinfo').forEach(b=>b.addEventListener('click',e=>{ e.stopPropagation();
    const row=_supQueueRows.find(x=>String(x.order_id)===String(b.dataset.oid));
    if(row) supCallLogModal(row);
  }));
  c.querySelectorAll('.sup-note-btn').forEach(b=>b.addEventListener('click',e=>{ e.stopPropagation(); supNotesModal(b.dataset.oid,b.dataset.oname); }));
  c.querySelectorAll('.sup-hold-btn').forEach(b=>b.addEventListener('click',e=>{ e.stopPropagation(); supDoHold(b.dataset.oid,b.dataset.oname,b); }));
  c.querySelectorAll('.sup-unhold-btn').forEach(b=>b.addEventListener('click',e=>{ e.stopPropagation(); supDoUnhold(b.dataset.oid,b.dataset.oname,b); }));
  c.querySelectorAll('.sup-cancel-btn').forEach(b=>b.addEventListener('click',e=>{ e.stopPropagation(); supDoCancel(b.dataset.oid,b.dataset.oname,b); }));
  c.querySelectorAll('.sup-eehold-btn').forEach(b=>b.addEventListener('click',e=>{ e.stopPropagation(); supDoEeHold(b.dataset.oid,b.dataset.oname,b); }));
  c.querySelectorAll('.sup-eeunhold-btn').forEach(b=>b.addEventListener('click',e=>{ e.stopPropagation(); supDoEeUnhold(b.dataset.oid,b.dataset.oname,b); }));
  c.querySelectorAll('.sup-raise').forEach(sel=>{
    sel.addEventListener('click',e=>e.stopPropagation());          // don't open the order modal
    sel.addEventListener('change',e=>{ e.stopPropagation(); supDoRaise(sel.dataset.oname, sel.value, sel); });
  });
}
// "🔓 Unheld by <user> · <ago>" history chip — shown when a hold was placed then RELEASED by a human,
// so an agent can see who released it (and when) instead of assuming it was never held. `by` is the
// releaser's email (or 'auto'); prettify the email local-part into a name to match the note byline.
function supPrettyUser(u){ if(!u) return ''; if(u==='auto') return 'auto'; const l=String(u).split('@')[0]; return l.replace(/[._]+/g,' ').replace(/\b\w/g,c=>c.toUpperCase()); }
function supReleasedChip(h){
  if(!(h && h.status==='released')) return '';
  const who=supPrettyUser(h.by)||'someone', when=h.at?supRelTime(h.at):'';
  const full=h.at?new Date(h.at).toLocaleString('en-IN',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'';
  const m=String(h.reason||'').match(/^held for:\s*(.+)$/i), why=m?m[1]:'';   // category captured at hold time (recordReleased)
  return `<span class="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-medium bg-slate-100 text-slate-500 whitespace-nowrap" title="Hold released by ${escapeHtml(h.by||'')}${full?' · '+full:''}${why?' · was held for: '+escapeHtml(why):''}">🔓 Unheld by ${escapeHtml(who)}${when?' · '+when:''}</span>`;
}
// Hold controls for the Repeat tab. Picks the RIGHT system: held-on-Shopify → Release Shopify;
// held-on-EasyEcom → Unhold EasyEcom; else if the order is already imported into EasyEcom → Hold
// EasyEcom (a Shopify hold is pointless once imported); else (still upstream) → Hold Shopify. A hold that
// was placed then human-RELEASED also shows the "🔓 Unheld by <user> · <ago>" history chip. Past-pickup
// rows are call-only. Repeat tab only.
function supHoldControl(r){
  if(_supTab!=='repeat') return '';
  const h=r.shopify_hold, oid=escapeHtml(r.order_id), oname=escapeHtml(r.order_name||'');
  if(h && h.status==='held'){ const why=(h.reason && h.reason!=='Repeat COD — awaiting customer confirmation')?h.reason:'';   // category captured at hold time
    return `<span class="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold bg-rose-50 text-rose-700 whitespace-nowrap" title="Held on Shopify${h.by==='auto'?' automatically':''}${why?' — '+escapeHtml(why):''} — won't ship / import to EasyEcom until released">🔒 Shopify hold${h.by==='auto'?' · auto':''}</span> <button class="sup-unhold-btn px-2.5 py-1.5 rounded-lg text-[11px] font-semibold bg-emerald-600 text-white hover:bg-emerald-700 whitespace-nowrap" data-oid="${oid}" data-oname="${oname}">Release Shopify</button>${canCancelOrders()?` <button class="sup-cancel-btn px-2.5 py-1.5 rounded-lg text-[11px] font-semibold bg-rose-600 text-white hover:bg-rose-700 whitespace-nowrap" data-oid="${oid}" data-oname="${oname}" title="Cancel this order on Shopify (restocks inventory, refunds any online-paid COD fee, no customer email)">Cancel order</button>`:''}`; }
  if(r.ee_hold) return `<span class="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold bg-amber-50 text-amber-700 whitespace-nowrap" title="On hold in EasyEcom">⏸ EasyEcom hold</span> <button class="sup-eeunhold-btn px-2.5 py-1.5 rounded-lg text-[11px] font-semibold bg-emerald-600 text-white hover:bg-emerald-700 whitespace-nowrap" data-oid="${oid}" data-oname="${oname}">Unhold EasyEcom</button>`;
  const rel=supReleasedChip(h);                      // history: was held, then released by a human (or auto)
  if(r.bucket !== 'order_to_dispatch') return rel;   // past pickup → call only (still surface the release history)
  if(r.in_ee) return `${rel?rel+' ':''}<button class="sup-eehold-btn px-2.5 py-1.5 rounded-lg text-[11px] font-semibold bg-amber-500 text-white hover:bg-amber-600 whitespace-nowrap" data-oid="${oid}" data-oname="${oname}" title="Order is already in EasyEcom — pause it there (before manifest)">⏸ Hold EasyEcom</button>`;
  const failed = h && h.status==='failed';
  return `${rel?rel+' ':''}${failed?`<span class="inline-flex items-center px-1.5 py-0.5 rounded text-[10px] font-semibold bg-amber-50 text-amber-700 whitespace-nowrap" title="Shopify hold failed: ${escapeHtml(h.reason||'')}">⚠️ Shopify hold failed</span> `:''}<button class="sup-hold-btn px-2.5 py-1.5 rounded-lg text-[11px] font-semibold bg-slate-800 text-white hover:bg-slate-700 whitespace-nowrap" data-oid="${oid}" data-oname="${oname}" title="Not yet in EasyEcom — hold on Shopify (stops it importing / shipping)">🔒 Hold Shopify</button>`;
}
// ── In-place row updates for the hold/release/cancel actions (user, 2026-08-20) ───────────────
// Every action used to end in supLoadQueue() — a full re-fetch of the heavy queue endpoint that
// flashed the grid and lost the agent's scroll position on each click. The action's outcome is known
// the moment the API says success, so the ROW is patched and the table repainted client-side (same
// optimistic pattern as the Raised control); the 30s auto-poll reconciles with the server soon after,
// so a drifted guess cannot outlive half a minute.
function supRowPatch(oid, fn){ const r=(_supQueueRows||[]).find(x=>String(x.order_id)===String(oid)); if(r) fn(r); supQueueTable(); }
function supRowDrop(oid){ _supQueueRows=(_supQueueRows||[]).filter(x=>String(x.order_id)!==String(oid)); supQueueTable(); }
const _supHoldReason='Repeat COD — awaiting customer confirmation';
// Standalone busy popup for the two actions with no confirm step (Hold Shopify goes straight to work;
// Cancel confirms through its own reason picker) — same chrome as supConfirm's busy state.
function supBusyModal(title, message){
  document.getElementById('sup-confirm-modal')?.remove();
  const wrap=document.createElement('div');
  wrap.id='sup-confirm-modal';
  wrap.className='fixed inset-0 z-[95] flex items-center justify-center bg-slate-900/50 backdrop-blur-[2px] p-4';
  wrap.innerHTML=`<div class="sup-pop bg-white rounded-2xl shadow-2xl w-full max-w-sm p-6"><div class="py-2">${brandLoaderSm(title)}
    ${message?`<p class="text-xs text-slate-400 mt-2 text-center">${escapeHtml(message)}</p>`:''}</div></div>`;
  document.body.appendChild(wrap);
  const box = wrap.firstElementChild;
  return {
    close: () => wrap.remove(),
    success: (t, m) => { box.innerHTML = `<div class="py-3 text-center">
        <span class="inline-flex w-12 h-12 rounded-full bg-emerald-100 text-emerald-600 items-center justify-center text-2xl">✓</span>
        <h3 class="text-base font-bold text-slate-800 mt-3">${escapeHtml(t)}</h3>
        ${m ? `<p class="text-sm text-slate-500 mt-1">${escapeHtml(m)}</p>` : ''}</div>`;
      setTimeout(() => wrap.remove(), 1300); },
    error: (t, m) => { box.innerHTML = `<div class="py-2 text-center">
        <span class="inline-flex w-12 h-12 rounded-full bg-rose-100 text-rose-600 items-center justify-center text-2xl">✕</span>
        <h3 class="text-base font-bold text-slate-800 mt-3">${escapeHtml(t)}</h3>
        <p class="text-sm text-slate-500 mt-1 break-words">${escapeHtml(m || '')}</p>
        <button class="supbm-close mt-4 px-4 py-2 rounded-lg text-sm font-semibold text-slate-600 bg-slate-100 hover:bg-slate-200">Close</button></div>`;
      box.querySelector('.supbm-close').addEventListener('click', () => wrap.remove()); },
  };
}
async function supDoHold(oid,oname){
  const busy=supBusyModal(`Holding ${oname}…`,'Talking to Shopify — a few seconds.');
  try{ await supFetch('/api/support/shopify-hold',{method:'POST',body:JSON.stringify({orderId:oid,orderName:oname})});
    busy.success(`${oname} held on Shopify`, 'It will not ship or import to EasyEcom until released.');
    showNotification(`${oname} held on Shopify`);
    supRowPatch(oid, r=>{ r.shopify_hold={ status:'held', reason:_supHoldReason, by:(currentUser&&currentUser.email)||null, at:new Date().toISOString() }; }); }
  catch(e){ busy.error('Hold failed', e.message); }
}
async function supDoUnhold(oid,oname){
  const res=await supConfirm({ title:`Release ${oname}?`, tone:'go', confirmLabel:'Release hold',
    message:`The order will be released and can ship / import to EasyEcom. Do this only after the customer has confirmed.`,
    busyTitle:`Releasing ${oname}…`, busyMessage:'Talking to Shopify — a few seconds.',
    successTitle:`${oname} released`, successMessage:'The order can now ship / import to EasyEcom.', errorTitle:'Release failed',
    work:()=>supFetch('/api/support/shopify-unhold',{method:'POST',body:JSON.stringify({orderId:oid,orderName:oname})}) });
  if(res!==true) return;   // cancelled, or the popup already showed the error until it was read
  showNotification(`${oname} released`);
  supRowPatch(oid, r=>{ const prev=r.shopify_hold||{};
    r.shopify_hold={ status:'released', by:(currentUser&&currentUser.email)||null, at:new Date().toISOString(), reason:prev.reason?`held for: ${prev.reason}`:null }; });
}
// Cancel a held Shopify order — pick a reason (logged), then cancel on Shopify (restock, no customer email).
async function supDoCancel(oid,oname){
  const reason=await supCancelReason(oname);
  if(!reason) return;
  const busy=supBusyModal(`Cancelling ${oname}…`,'Cancelling on Shopify and refunding any online-paid amount — a few seconds.');
  try{ const d=await supFetch('/api/support/cancel-order',{method:'POST',body:JSON.stringify({orderId:oid,orderName:oname,reason})});
    busy.success(`${oname} cancelled`, `Inventory restocked${d&&d.refunded?` · ₹${d.refunded} refunded`:''} · no email to the customer.`);
    showNotification(`${oname} cancelled on Shopify${d&&d.refunded?` · ₹${d.refunded} refunded`:''}`);
    delete _eeHold[String(oname||'').replace('#','').trim()]; _eeHoldAt=0; supRowDrop(oid); }
  catch(e){ busy.error('Cancel failed', e.message); }
}
// Reason picker for cancelling — a category dropdown + optional note. Returns the reason string, or null if dismissed.
function supCancelReason(oname){
  return new Promise(resolve=>{
    document.getElementById('sup-cancel-modal')?.remove();
    const wrap=document.createElement('div'); wrap.id='sup-cancel-modal';
    wrap.className='fixed inset-0 z-[95] flex items-center justify-center bg-slate-900/50 backdrop-blur-[2px] p-4';
    const opts=['Customer refused','Customer unreachable','Duplicate order','Fake / fraudulent','Other'];
    wrap.innerHTML=`<div class="sup-pop bg-white rounded-2xl shadow-2xl w-full max-w-sm p-6">
      <div class="flex items-start gap-3">
        <span class="w-10 h-10 rounded-xl bg-rose-100 text-rose-600 flex items-center justify-center text-lg shrink-0">⚠️</span>
        <div class="min-w-0"><h3 class="text-base font-bold text-slate-800">Cancel this order?</h3>
          <p class="text-sm text-slate-500 mt-1">${escapeHtml(oname||'')} will be <b>cancelled on Shopify</b> — inventory restocked, any amount paid online (COD fee/advance) refunded, no email to the customer. This can't be undone.</p></div></div>
      <label class="block text-xs font-semibold text-slate-500 mt-4 mb-1">Reason</label>
      <select id="supcx-reason" class="filter-select w-full">${opts.map(o=>`<option value="${o}">${o}</option>`).join('')}</select>
      <input id="supcx-note" type="text" maxlength="120" class="filter-input w-full mt-2" placeholder="Optional note (added to the reason)">
      <div class="flex justify-end gap-2.5 mt-5">
        <button id="supcx-no" class="px-4 py-2 rounded-lg text-sm font-semibold text-slate-600 hover:bg-slate-100">Keep order</button>
        <button id="supcx-yes" class="px-4 py-2 rounded-lg text-sm font-semibold text-white bg-rose-600 hover:bg-rose-700">Cancel order</button>
      </div></div>`;
    document.body.appendChild(wrap);
    const done=v=>{ wrap.remove(); document.removeEventListener('keydown',onKey); resolve(v); };
    const onKey=e=>{ if(e.key==='Escape') done(null); };
    document.addEventListener('keydown',onKey);
    wrap.addEventListener('click',e=>{ if(e.target===wrap) done(null); });
    document.getElementById('supcx-no').addEventListener('click',()=>done(null));
    document.getElementById('supcx-yes').addEventListener('click',()=>{
      const r=document.getElementById('supcx-reason').value, n=document.getElementById('supcx-note').value.trim();
      done(n?`${r} — ${n}`:r);
    });
    setTimeout(()=>document.getElementById('supcx-reason')?.focus(),50);
  });
}
// EasyEcom hold/unhold from the Repeat tab (order already imported into EasyEcom → hold it there).
async function supDoEeHold(oid,oname){
  const res=await supConfirm({ title:`Hold ${oname} on EasyEcom?`, icon:'⏸', confirmLabel:'Hold order',
    message:`The order is already in EasyEcom — it will be paused there (works before manifest). Do this to stop it shipping until the customer confirms.`,
    busyTitle:`Holding ${oname}…`, busyMessage:'Talking to EasyEcom — a few seconds.',
    successTitle:`${oname} held in EasyEcom`, successMessage:'It will not ship until released.', errorTitle:'EasyEcom hold failed',
    work:()=>supFetch('/api/easyecom/hold-order',{method:'POST',body:JSON.stringify({orderName:oname,reason:_supHoldReason})}) });
  if(res!==true) return;
  showNotification(`${oname} held in EasyEcom`);
  const _hk=String(oname||'').replace('#','').trim();
  _eeHold[_hk]={ order_name:_hk, note:_supHoldReason, created_by:currentUser&&currentUser.email, created_at:new Date().toISOString() }; _eeHoldAt=0;
  supRowPatch(oid, r=>{ r.ee_hold=true; });
}
async function supDoEeUnhold(oid,oname){
  const res=await supConfirm({ title:`Release ${oname}?`, tone:'go', confirmLabel:'Release hold',
    message:`The order will be released in EasyEcom and can proceed. Do this only after the customer has confirmed.`,
    busyTitle:`Releasing ${oname}…`, busyMessage:'Talking to EasyEcom — a few seconds.',
    successTitle:`${oname} released`, successMessage:'The order can now proceed in EasyEcom.', errorTitle:'Release failed',
    work:()=>supFetch('/api/easyecom/unhold-order',{method:'POST',body:JSON.stringify({orderName:oname})}) });
  if(res!==true) return;
  showNotification(`${oname} released in EasyEcom`);
  delete _eeHold[String(oname||'').replace('#','').trim()]; _eeHoldAt=0;
  supRowPatch(oid, r=>{ r.ee_hold=false; });
}
async function supRefreshTracking(){
  const btn=document.getElementById('sup-refresh'); const orig=btn.textContent;
  btn.disabled=true; btn.textContent='Syncing…'; showNotification('Fetching latest tracking from RapidShyp…');
  try{ const d=await supFetch('/api/support/refresh-tracking',{method:'POST'});
    showNotification('Tracking refreshed'+((d.result&&d.result.updated!=null)?` — ${d.result.updated} orders updated`:'')); supSyncInfo(d.lock); supLoadQueue(); }
  catch(e){ showNotification('Sync failed: '+e.message, true); }
  finally{ btn.disabled=false; btn.textContent=orig; }
}

// ── Notes dialog (add / edit / delete own) — avatar cards, relative time, hover actions ──
function supRelTime(iso){ if(!iso) return ''; const m=(Date.now()-new Date(iso).getTime())/60000;
  if(m<1) return 'just now'; if(m<60) return Math.round(m)+'m ago'; if(m<1440) return Math.round(m/60)+'h ago';
  if(m<10080) return Math.round(m/1440)+'d ago'; return new Date(iso).toLocaleDateString('en-IN',{day:'2-digit',month:'short'}); }
// Our own confirm dialog (no browser confirm()) — stacks above any open modal. Returns Promise<boolean>.
// Confirmation popup. `tone` picks the visual voice: 'go' (emerald — release/proceed actions),
// 'danger' (rose), default ask (indigo); `icon` overrides the emoji. Pass `work: async () => …` and
// the popup CARRIES THE ACTION: on confirm it stays open as a loader (busyTitle/busyMessage) while the
// API call runs, then closes — resolves true on success, { error } on failure, false on cancel.
// (2026-08-20, user: after confirming a release, the only feedback was tiny button text — the modal
// vanished and nothing visibly loaded. Escape/backdrop are dead while busy: the work is in flight and
// closing the popup would not undo it, only hide it.)
function supConfirm({ title = 'Are you sure?', message = '', confirmLabel = 'Confirm', danger = false, tone = null, icon = null, busyTitle = 'Working…', busyMessage = '', successTitle = 'Done', successMessage = '', errorTitle = 'Something went wrong', work = null } = {}) {
  const t = tone || (danger ? 'danger' : 'ask');
  const iconBg = t === 'danger' ? 'bg-rose-100 text-rose-600' : t === 'go' ? 'bg-emerald-100 text-emerald-600' : 'bg-indigo-100 text-indigo-600';
  const btnBg = t === 'danger' ? 'bg-rose-600 hover:bg-rose-700' : t === 'go' ? 'bg-emerald-600 hover:bg-emerald-700' : 'bg-indigo-600 hover:bg-indigo-700';
  const glyph = icon || (t === 'danger' ? '🗑' : t === 'go' ? '🔓' : '❓');
  return new Promise(resolve => {
    document.getElementById('sup-confirm-modal')?.remove();
    const wrap = document.createElement('div');
    wrap.id = 'sup-confirm-modal';
    wrap.className = 'fixed inset-0 z-[95] flex items-center justify-center bg-slate-900/50 backdrop-blur-[2px] p-4';
    wrap.innerHTML = `<div class="sup-pop bg-white rounded-2xl shadow-2xl w-full max-w-sm p-6">
      <div class="flex items-start gap-3">
        <span class="w-10 h-10 rounded-xl ${iconBg} flex items-center justify-center text-lg shrink-0">${glyph}</span>
        <div class="min-w-0"><h3 class="text-base font-bold text-slate-800">${escapeHtml(title)}</h3>
          ${message ? `<p class="text-sm text-slate-500 mt-1">${escapeHtml(message)}</p>` : ''}</div></div>
      <div class="flex justify-end gap-2.5 mt-5">
        <button id="supcf-no" class="px-4 py-2 rounded-lg text-sm font-semibold text-slate-600 hover:bg-slate-100 transition-colors">Cancel</button>
        <button id="supcf-yes" class="px-4 py-2 rounded-lg text-sm font-semibold text-white ${btnBg} transition-colors">${escapeHtml(confirmLabel)}</button>
      </div></div>`;
    document.body.appendChild(wrap);
    let busy = false;
    const done = v => { if (busy && v === false) return;   // no closing out of an in-flight action
      wrap.remove(); document.removeEventListener('keydown', onKey); resolve(v); };
    const onKey = e => { if (e.key === 'Escape') done(false); if (e.key === 'Enter' && !busy) onYes(); };
    const onYes = async () => {
      if (!work) return done(true);
      if (busy) return;
      busy = true;
      // The popup becomes the loader — the action visibly runs where the agent just clicked …
      wrap.firstElementChild.innerHTML = `<div class="py-2">${brandLoaderSm(busyTitle)}
        ${busyMessage ? `<p class="text-xs text-slate-400 mt-2 text-center">${escapeHtml(busyMessage)}</p>` : ''}</div>`;
      try {
        await work();
        // … then the RESULT shows in the same popup (user, 2026-08-20: success was never shown — the
        // modal vanished and only a corner toast fired). A short ✅ beat, then it closes itself.
        busy = false;
        wrap.firstElementChild.innerHTML = `<div class="py-3 text-center">
          <span class="inline-flex w-12 h-12 rounded-full bg-emerald-100 text-emerald-600 items-center justify-center text-2xl">✓</span>
          <h3 class="text-base font-bold text-slate-800 mt-3">${escapeHtml(successTitle)}</h3>
          ${successMessage ? `<p class="text-sm text-slate-500 mt-1">${escapeHtml(successMessage)}</p>` : ''}</div>`;
        setTimeout(() => done(true), 1300);
      } catch (e) {
        // Errors stay until READ — an auto-closing failure is a missed failure.
        busy = false;
        wrap.firstElementChild.innerHTML = `<div class="py-2 text-center">
          <span class="inline-flex w-12 h-12 rounded-full bg-rose-100 text-rose-600 items-center justify-center text-2xl">✕</span>
          <h3 class="text-base font-bold text-slate-800 mt-3">${escapeHtml(errorTitle)}</h3>
          <p class="text-sm text-slate-500 mt-1 break-words">${escapeHtml(e.message || String(e))}</p>
          <button id="supcf-errclose" class="mt-4 px-4 py-2 rounded-lg text-sm font-semibold text-slate-600 bg-slate-100 hover:bg-slate-200">Close</button></div>`;
        wrap.querySelector('#supcf-errclose').addEventListener('click', () => done({ error: e, shown: true }));
      }
    };
    document.addEventListener('keydown', onKey);
    wrap.addEventListener('click', e => { if (e.target === wrap) done(false); });
    document.getElementById('supcf-no').addEventListener('click', () => done(false));
    const yes = document.getElementById('supcf-yes'); yes.addEventListener('click', onYes); yes.focus();
  });
}
const SUP_ICON_EDIT='<svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>';
const SUP_ICON_TRASH='<svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>';
// Every call on one order, opened from the ℹ️ in the Called column (user, 2026-09-05: "call
