// ═══════════════ ZONE MAPPING (admin) ═══════════════
// KwikShip's serviceability sheet: one row per DESTINATION pincode. ⚠️ `Pin_code_From` is the PICKUP
// pincode (constant, e.g. 122101 Gurgaon) and `Pin_code_To` is the destination — despite the names it
// is NOT a From..To range. It can be imported straight into `zone_mapping_with_pincode` from Supabase
// (the table's columns match the CSV headers exactly), or uploaded here. Either way "Re-apply to
// shipments" re-derives `zone` on every KwikShip shipment. RapidShyp/DocPharma are never touched.
const _zm = { bound: false, b64: null, filename: null };

// Direct fetch (not supFetch): a failed header-detection returns 400 WITH the sheet's header row, and
// supFetch collapses an error body down to its message, losing the columns we need for the picker.
async function zmPost(url, body) {
    const r = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json', ...getAuthHeaders() }, body: JSON.stringify(body) });
    const d = await r.json().catch(() => ({}));
    return { ok: r.ok && d.success !== false, data: d };
}

function zmTile(label, value, sub) {
    return `<div class="card p-4">
        <div class="text-[11px] font-semibold text-slate-400 uppercase tracking-wide">${escapeHtml(label)}</div>
        <div class="text-2xl font-bold text-slate-800 mt-1 tabular-nums">${escapeHtml(value)}</div>
        ${sub ? `<div class="text-xs text-slate-400 mt-0.5">${sub}</div>` : ''}
    </div>`;
}

async function zmSummary() {
    const host = document.getElementById('zm-kpis');
    if (!host) return;
    host.innerHTML = brandLoaderSm('Loading mapping…');
    try {
        const d = await supFetch('/api/zone-mapping/summary');
        const zones = (d.zones || []).map(z => `${escapeHtml(z.zone)} ${z.count.toLocaleString('en-IN')}`).join(' &middot; ');
        const kw = d.kwikship || { total: 0, mapped: 0 };
        const pct = kw.total ? Math.round((kw.mapped / kw.total) * 100) : 0;
        const org = (d.origins || []).map(o => escapeHtml(String(o.pincode))).join(', ');
        host.innerHTML = [
            zmTile('Destination pincodes', (d.destinations || 0).toLocaleString('en-IN'), d.total ? `${(d.total || 0).toLocaleString('en-IN')} rows in the sheet` : 'nothing imported yet'),
            zmTile('Pickup pincode', org || '—', (d.origins || []).length > 1 ? '⚠️ more than one — two reports mixed?' : 'the origin this sheet is for'),
            zmTile('Zones', String((d.zones || []).length), zones || '—'),
            zmTile('Kwikship shipments', `${pct}%`, `${kw.mapped.toLocaleString('en-IN')} of ${kw.total.toLocaleString('en-IN')} on a listed pincode`),
        ].join('');
        zmRenderCharges(d);
    } catch (e) {
        host.innerHTML = `<div class="col-span-full text-sm bg-rose-50 border border-rose-200 text-rose-700 rounded-lg px-3 py-2">${escapeHtml(e.message)}</div>`;
    }
}

// Shipping cost estimated against the KwikShip rate card. Ex-GST is the headline because GST is
// input-creditable; the gross is shown alongside since that is what actually leaves the bank.
// Whole rupees — freight totals run to five figures, where paise are noise. (`_inr` above keeps
// decimals for the finance screens that need them.)
const _inr0 = n => '₹' + Math.round(Number(n) || 0).toLocaleString('en-IN');

function zmRenderCharges(d) {
    const host = document.getElementById('zm-charges');
    if (!host) return;
    const c = d.charges;
    if (!c || !c.priced) { host.innerHTML = ''; return; }
    const cfg = d.billing_config || {};

    // Rate card pivoted to zone × rate-kind for display.
    const ZONES = ['A', 'B', 'C', 'D', 'E'];
    const KINDS = [
        ['fwd_base_500', 'Forward 500 g'], ['fwd_add_500', 'Forward +500 g'], ['rto_base_500', 'RTO 500 g'],
        ['fwd_base_2000', 'Forward 2 kg'], ['fwd_add_1000', 'Forward +1 kg'], ['rto_base_2000', 'RTO 2 kg'],
    ];
    const rc = {};
    (d.rate_card || []).forEach(r => { rc[`${r.rate_kind}|${r.zone}`] = r.rate; });
    // Zone C is priced by the card but absent from the serviceability sheet — mark it so the row isn't
    // mistaken for live pricing.
    const liveZones = new Set((d.zones || []).map(z => z.zone));

    const cardRows = KINDS.map(([k, label]) => `<tr class="border-t border-slate-100">
        <td class="px-3 py-2 text-slate-600">${label}</td>
        ${ZONES.map(z => `<td class="px-3 py-2 text-right tabular-nums ${liveZones.has(z) ? 'text-slate-700' : 'text-slate-300'}">${rc[`${k}|${z}`] != null ? _inr0(rc[`${k}|${z}`]) : '—'}</td>`).join('')}
    </tr>`).join('');

    const byZone = (c.by_zone || []).map(z => `<tr class="border-t border-slate-100">
        <td class="px-3 py-2 font-semibold">${escapeHtml(z.zone)}</td>
        <td class="px-3 py-2 text-right tabular-nums">${z.shipments.toLocaleString('en-IN')}</td>
        <td class="px-3 py-2 text-right tabular-nums">${_inr0(z.ex_gst)}</td>
    </tr>`).join('');

    host.innerHTML = `<div class="card p-6">
      <div class="flex items-center justify-between flex-wrap gap-2 mb-4">
        <div>
          <h2 class="text-sm font-bold text-slate-700">Shipping cost &mdash; estimated against the KwikShip rate card</h2>
          <p class="text-xs text-slate-400 mt-0.5">
            ${c.priced.toLocaleString('en-IN')} shipments priced${c.unpriced ? ` &middot; <span class="text-amber-600">${c.unpriced.toLocaleString('en-IN')} could not be priced</span>` : ''}
            &middot; RTO pays forward + RTO &middot; COD fee ${_inr0(cfg.cod_min)} or ${cfg.cod_pct}% (higher) on delivery only
          </p>
        </div>
      </div>
      <div class="grid grid-cols-2 md:grid-cols-5 gap-3 mb-5">
        ${zmTile('Forward', _inr0(c.forward))}
        ${zmTile('RTO', _inr0(c.rto))}
        ${zmTile('COD fees', _inr0(c.cod_fee))}
        ${zmTile('Total ex-GST', _inr0(c.ex_gst), 'the real cost (GST is creditable)')}
        ${zmTile(`Incl. ${cfg.gst_pct || 18}% GST`, _inr0(c.incl_gst), 'what leaves the bank')}
      </div>
      <div class="grid lg:grid-cols-2 gap-6">
        <div>
          <h3 class="text-xs font-bold text-slate-600 uppercase tracking-wide mb-2">Cost by zone</h3>
          <div class="overflow-x-auto border border-slate-100 rounded-lg">
            <table class="w-full text-sm text-left border-collapse">
              <thead class="bg-slate-50 text-xs text-slate-500 uppercase tracking-wide">
                <tr><th class="px-3 py-2">Zone</th><th class="px-3 py-2 text-right">Shipments</th><th class="px-3 py-2 text-right">Cost ex-GST</th></tr>
              </thead>
              <tbody>${byZone}</tbody>
            </table>
          </div>
        </div>
        <div>
          <h3 class="text-xs font-bold text-slate-600 uppercase tracking-wide mb-2">Rate card (surface, ex-GST)</h3>
          <div class="overflow-x-auto border border-slate-100 rounded-lg">
            <table class="w-full text-sm text-left border-collapse">
              <thead class="bg-slate-50 text-xs text-slate-500 uppercase tracking-wide">
                <tr><th class="px-3 py-2">Slab</th>${ZONES.map(z => `<th class="px-3 py-2 text-right">${z}</th>`).join('')}</tr>
              </thead>
              <tbody>${cardRows}</tbody>
            </table>
          </div>
          <p class="text-xs text-slate-400 mt-2">Greyed zones are priced by the card but never appear in KwikShip's serviceability sheet, so no shipment can be billed at them.</p>
        </div>
      </div>
      <p class="text-xs text-slate-400 mt-4">These are <b>estimates against the contracted card</b>, not KwikShip invoice lines &mdash; weight is the EasyEcom package weight (dead weight; no dimensions are available, so volumetric weight is not applied). Costs recompute automatically whenever zones change and nightly after the 2 AM sync.</p>
    </div>`;
}

function zmRenderReview(s) {
    const host = document.getElementById('zm-review');
    if (!host) return;
    const warn = [];
    if (s.badPin) warn.push(`<b>${s.badPin}</b> row(s) skipped — the destination pincode was not a valid 6-digit pincode.`);
    if (s.missingZone) warn.push(`<b>${s.missingZone}</b> row(s) skipped — no zone value.`);
    if (s.dupDest) warn.push(`<b>${s.dupDest}</b> repeat row(s) for a destination already listed — the first one is kept.`);
    if (s.conflicts) warn.push(`⚠️ <b>${s.conflicts}</b> destination(s) appear twice with a <b>different</b> zone${s.conflictSample && s.conflictSample.length ? `, e.g. ${s.conflictSample.slice(0, 3).map(c => `${escapeHtml(c.pincode)} (${c.zones.map(escapeHtml).join(' vs ')})`).join(', ')}` : ''} — the first is used.`);
    if ((s.origins || []).length > 1) warn.push(`⚠️ The file lists <b>${s.origins.length}</b> different pickup pincodes (${s.origins.slice(0, 5).map(escapeHtml).join(', ')}) — a serviceability report should cover ONE origin. Check you haven't merged two exports.`);
    if (s.unknownColumns && s.unknownColumns.length) warn.push(`<b>${s.unknownColumns.length}</b> column(s) in the file have no matching column in the table and will NOT be stored: ${s.unknownColumns.slice(0, 8).map(escapeHtml).join(', ')}${s.unknownColumns.length > 8 ? '…' : ''}.`);

    const zoneChips = (s.zones || []).map(z =>
        `<span class="px-2 py-1 rounded bg-indigo-50 text-indigo-700 text-xs font-semibold">${escapeHtml(z.zone)} &middot; ${z.count.toLocaleString('en-IN')}</span>`).join(' ');

    const sample = (s.sample || []).map(r => `<tr class="border-t border-slate-100">
        <td class="px-3 py-2 font-mono text-xs">${escapeHtml(String(r.dest))}</td>
        <td class="px-3 py-2 font-semibold">${escapeHtml(r.zone)}</td>
        <td class="px-3 py-2 font-mono text-xs text-slate-400">${escapeHtml(String(r.from == null ? '—' : r.from))}</td>
        <td class="px-3 py-2 text-slate-400 text-xs">${r.fields} fields</td>
    </tr>`).join('');

    host.innerHTML = `<div class="card p-6">
        <div class="flex items-center justify-between flex-wrap gap-3 mb-4">
            <div>
                <h2 class="text-sm font-bold text-slate-700">Ready to import &mdash; ${escapeHtml(s.filename || 'sheet')}</h2>
                <p class="text-xs text-slate-400 mt-0.5">
                    <b>${s.destinations.toLocaleString('en-IN')}</b> destination pincodes
                    ${(s.origins || []).length === 1 ? `from pickup <b>${escapeHtml(String(s.origins[0]))}</b>` : ''} &middot;
                    ${s.matchedColumns} column(s) mapped &middot; header on row ${s.headerRow}
                </p>
            </div>
            <div class="flex items-center gap-2">
                <button id="zm-cancel" class="px-4 py-2 rounded-lg text-sm font-semibold text-slate-600 bg-white border border-slate-200 hover:bg-slate-50 transition-colors">Cancel</button>
                <button id="zm-commit" class="px-4 py-2 rounded-lg text-sm font-semibold text-white bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 transition-colors">Import &amp; apply</button>
            </div>
        </div>
        <div class="flex flex-wrap gap-2 mb-4">${zoneChips}</div>
        ${warn.length ? `<div class="text-xs bg-amber-50 border border-amber-200 text-amber-700 rounded-lg px-3 py-2 mb-4 space-y-1">${warn.map(w => `<div>${w}</div>`).join('')}</div>` : ''}
        <div class="overflow-x-auto border border-slate-100 rounded-lg">
            <table class="w-full text-sm text-left border-collapse">
                <thead class="bg-slate-50 text-xs text-slate-500 uppercase tracking-wide">
                    <tr><th class="px-3 py-2">Destination</th><th class="px-3 py-2">Zone</th><th class="px-3 py-2">Pickup</th><th class="px-3 py-2">Stored</th></tr>
                </thead>
                <tbody>${sample}</tbody>
            </table>
        </div>
        <p class="text-xs text-slate-400 mt-3">Showing the first ${(s.sample || []).length} destinations. Importing rewrites the zone on Kwikship shipments delivering to a listed pincode; pincodes not in the sheet keep their current state-derived zone.</p>
    </div>`;

    document.getElementById('zm-cancel')?.addEventListener('click', () => { host.innerHTML = ''; document.getElementById('zm-status').innerHTML = ''; });
    document.getElementById('zm-commit')?.addEventListener('click', zmCommit);
}

async function zmParse() {
    const status = document.getElementById('zm-status');
    if (!_zm.b64) return;
    status.innerHTML = brandLoaderSm('Reading the sheet…');
    const { ok, data } = await zmPost('/api/zone-mapping/upload', {
        filename: _zm.filename, contentBase64: _zm.b64, dryRun: true,
    });
    if (!ok) {
        status.innerHTML = `<div class="text-sm bg-rose-50 border border-rose-200 text-rose-700 rounded-lg px-3 py-2">${escapeHtml(data.error || 'Could not read that file.')}</div>`;
        return;
    }
    status.innerHTML = '';
    zmRenderReview(data.summary);
}

async function zmCommit() {
    const status = document.getElementById('zm-status');
    const btn = document.getElementById('zm-commit');
    if (btn) { btn.disabled = true; btn.textContent = 'Importing…'; }
    status.innerHTML = brandLoaderSm('Importing and re-applying to Kwikship shipments…');
    const { ok, data } = await zmPost('/api/zone-mapping/upload', {
        filename: _zm.filename, contentBase64: _zm.b64, dryRun: false,
        replace: !!(document.getElementById('zm-replace') || {}).checked,
    });
    if (!ok) {
        status.innerHTML = `<div class="text-sm bg-rose-50 border border-rose-200 text-rose-700 rounded-lg px-3 py-2">${escapeHtml(data.error || 'Import failed.')}</div>`;
        if (btn) { btn.disabled = false; btn.textContent = 'Import & apply'; }
        return;
    }
    const r = data.remap || {};
    status.innerHTML = `<div class="text-sm bg-emerald-50 border border-emerald-200 text-emerald-700 rounded-lg px-3 py-2">
        Imported <b>${(data.written || 0).toLocaleString('en-IN')}</b> destination pincodes.
        ${data.remap ? `Kwikship shipments: <b>${(r.matched || 0).toLocaleString('en-IN')}</b> matched, <b>${(r.changed || 0).toLocaleString('en-IN')}</b> zone(s) updated, ${(r.unmapped || 0).toLocaleString('en-IN')} kept their state-derived zone.` : ''}
        ${data.remapError ? `<br>Mapping saved, but re-applying failed: ${escapeHtml(data.remapError)} — use “Re-apply to shipments”.` : ''}
    </div>`;
    document.getElementById('zm-review').innerHTML = '';
    _zm.b64 = null;
    zmSummary();
}

function zmRead(file) {
    const status = document.getElementById('zm-status');
    if (!/\.(csv|xlsx)$/i.test(file.name)) {
        status.innerHTML = `<div class="text-sm bg-rose-50 border border-rose-200 text-rose-700 rounded-lg px-3 py-2">Upload a .csv or .xlsx file. Old .xls must be re-saved from Excel first.</div>`;
        return;
    }
    status.innerHTML = brandLoaderSm('Reading ' + file.name + '…');
    const reader = new FileReader();
    reader.onerror = () => { status.innerHTML = `<div class="text-sm bg-rose-50 border border-rose-200 text-rose-700 rounded-lg px-3 py-2">Could not read that file.</div>`; };
    reader.onload = () => {
        _zm.b64 = String(reader.result).split(',')[1] || '';
        _zm.filename = file.name;
        zmParse();
    };
    reader.readAsDataURL(file);
}

async function zmLookup() {
    const out = document.getElementById('zm-lookup-out');
    const pin = String((document.getElementById('zm-pin') || {}).value || '').replace(/\D/g, '');
    if (!/^[1-9]\d{5}$/.test(pin)) {
        out.innerHTML = `<div class="text-sm bg-amber-50 border border-amber-200 text-amber-700 rounded-lg px-3 py-2">Enter a 6-digit pincode.</div>`;
        return;
    }
    out.innerHTML = brandLoaderSm('Checking…');
    try {
        const d = await supFetch(`/api/zone-mapping/lookup?pincode=${pin}`);
        const row = d.row;
        out.innerHTML = d.found
            ? `<div class="text-sm bg-emerald-50 border border-emerald-200 text-emerald-700 rounded-lg px-3 py-2">
                 <b>${escapeHtml(pin)}</b> → Zone <b>${escapeHtml(d.zone)}</b>
                 ${row && row.Pin_code_From != null ? ` &middot; from pickup <span class="font-mono text-xs">${escapeHtml(String(row.Pin_code_From))}</span>` : ''}
                 <span class="text-emerald-600">&middot; a Kwikship shipment here is zoned from the sheet</span>
               </div>`
            : `<div class="text-sm bg-amber-50 border border-amber-200 text-amber-700 rounded-lg px-3 py-2">
                 <b>${escapeHtml(pin)}</b> is not in the sheet — a Kwikship shipment there keeps the state-derived zone.
               </div>`;
    } catch (e) {
        out.innerHTML = `<div class="text-sm bg-rose-50 border border-rose-200 text-rose-700 rounded-lg px-3 py-2">${escapeHtml(e.message)}</div>`;
    }
}

async function zmRemap() {
    const out = document.getElementById('zm-lookup-out');
    const btn = document.getElementById('zm-remap');
    if (btn) { btn.disabled = true; btn.textContent = 'Applying…'; }
    out.innerHTML = brandLoaderSm('Re-applying zones to Kwikship shipments…');
    try {
        const d = await supFetch('/api/zone-mapping/remap', { method: 'POST', body: '{}' });
        out.innerHTML = `<div class="text-sm bg-emerald-50 border border-emerald-200 text-emerald-700 rounded-lg px-3 py-2">
            <b>${(d.matched || 0).toLocaleString('en-IN')}</b> of ${(d.total || 0).toLocaleString('en-IN')} Kwikship shipments matched the sheet &middot;
            <b>${(d.changed || 0).toLocaleString('en-IN')}</b> zone(s) updated &middot;
            ${(d.unmapped || 0).toLocaleString('en-IN')} kept their state-derived zone.
        </div>`;
        zmSummary();
    } catch (e) {
        out.innerHTML = `<div class="text-sm bg-rose-50 border border-rose-200 text-rose-700 rounded-lg px-3 py-2">${escapeHtml(e.message)}</div>`;
    } finally {
        if (btn) { btn.disabled = false; btn.textContent = 'Re-apply to shipments'; }
    }
}

function zmInit() {
    zmSummary();
    if (_zm.bound) return;
    _zm.bound = true;
    const drop = document.getElementById('zm-drop'), input = document.getElementById('zm-file');
    if (drop && input) {
        drop.addEventListener('click', () => input.click());
        drop.addEventListener('dragover', e => { e.preventDefault(); drop.classList.add('border-indigo-400'); });
        drop.addEventListener('dragleave', () => drop.classList.remove('border-indigo-400'));
        drop.addEventListener('drop', e => {
            e.preventDefault(); drop.classList.remove('border-indigo-400');
            if (e.dataTransfer.files && e.dataTransfer.files[0]) zmRead(e.dataTransfer.files[0]);
        });
        // Reset value so re-picking the SAME file still fires change.
        input.addEventListener('change', () => { if (input.files && input.files[0]) { zmRead(input.files[0]); input.value = ''; } });
    }
    document.getElementById('zm-lookup')?.addEventListener('click', zmLookup);
    document.getElementById('zm-pin')?.addEventListener('keydown', e => { if (e.key === 'Enter') zmLookup(); });
    document.getElementById('zm-remap')?.addEventListener('click', zmRemap);
    // Zone & State tab (2026-08-29)
    document.querySelectorAll('.zm-tab').forEach(b => b.addEventListener('click', () => zmTab(b.dataset.tab)));
    document.getElementById('zs-apply')?.addEventListener('click', () => { _zs.page = 0; zsLoad(); });
    document.getElementById('zs-clear')?.addEventListener('click', () => { const st=document.getElementById('zs-state'), zn=document.getElementById('zs-zone'), q=document.getElementById('zs-q'), pl=document.getElementById('zs-place'); st.value=''; zn.value=''; q.value=''; if(pl) pl.value=''; ecSyncSelect(st); ecSyncSelect(zn); _zs.page = 0; zsLoad(); });
    document.getElementById('zs-q')?.addEventListener('keydown', e => { if (e.key === 'Enter') { _zs.page = 0; zsLoad(); } });
    document.getElementById('zs-place')?.addEventListener('keydown', e => { if (e.key === 'Enter') { _zs.page = 0; zsLoad(); } });
    document.getElementById('zs-state')?.addEventListener('change', () => { _zs.page = 0; zsLoad(); });
    document.getElementById('zs-zone')?.addEventListener('change', () => { _zs.page = 0; zsLoad(); });
    document.getElementById('zs-prev')?.addEventListener('click', () => { if (_zs.page > 0) { _zs.page--; zsLoad(); } });
    document.getElementById('zs-next')?.addEventListener('click', () => { if ((_zs.page + 1) * _zs.size < _zs.total) { _zs.page++; zsLoad(); } });
    document.getElementById('zs-export')?.addEventListener('click', zsExport);
    // India Post directory upload (CSV → india_pincode_directory_ecom, then the zone rows are filled from it)
    const dd = document.getElementById('zs-dir-drop'), df = document.getElementById('zs-dir-file');
    if (dd && df) {
        dd.addEventListener('click', () => df.click());
        dd.addEventListener('dragover', e => { e.preventDefault(); dd.classList.add('border-indigo-400'); });
        dd.addEventListener('dragleave', () => dd.classList.remove('border-indigo-400'));
        dd.addEventListener('drop', e => { e.preventDefault(); dd.classList.remove('border-indigo-400'); if (e.dataTransfer.files && e.dataTransfer.files[0]) zsDirUpload(e.dataTransfer.files[0]); });
        df.addEventListener('change', () => { if (df.files && df.files[0]) { zsDirUpload(df.files[0]); df.value = ''; } });
    }
}
async function zsDirStatus() {
    const el = document.getElementById('zs-dir-status'); if (!el) return;
    try { const d = await supFetch('/api/zone-mapping/pincode-directory');
        el.textContent = d.offices ? `Loaded: ${Number(d.offices).toLocaleString('en-IN')} post offices · ${Number(d.pincodes).toLocaleString('en-IN')} pincodes · last import ${d.last_import ? new Date(d.last_import).toLocaleString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }) : '—'}.` : 'Not imported yet.'; }
    catch (e) { el.textContent = ''; }
}
async function zsDirUpload(file) {
    const out = document.getElementById('zs-dir-out');
    if (!/\.csv$/i.test(file.name)) { out.innerHTML = '<span class="text-rose-600">Please upload the CSV export.</span>'; return; }
    out.innerHTML = brandLoaderSm(`Importing ${escapeHtml(file.name)} (${(file.size / 1048576).toFixed(1)} MB) — a full directory takes a minute or two…`);
    try {
        const b64 = await new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(String(r.result).split(',')[1]); r.onerror = rej; r.readAsDataURL(file); });
        const d = await supFetch('/api/zone-mapping/pincode-directory/upload', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ contentBase64: b64, replace: !!document.getElementById('zs-dir-replace')?.checked }) });
        out.innerHTML = `<span class="text-emerald-700 font-semibold">Imported ${Number(d.written).toLocaleString('en-IN')} post offices</span> (${d.skipped} skipped) · <b>${Number(d.filled).toLocaleString('en-IN')}</b> zone rows filled from it · coverage now ${Number(d.coverage.indiapost).toLocaleString('en-IN')} of ${Number(d.coverage.total).toLocaleString('en-IN')} verified by India Post.`;
        _zs.states = null; zsDirStatus(); zsLoad();
    } catch (e) { out.innerHTML = `<span class="text-rose-600">${escapeHtml(e.message)}</span>`; }
}
// ── Zone & State — browse the sheet by state, download Excel (2026-08-29) ────────────────────────
// The sheet has no state column; the server fills one per pincode (India Post > order addresses >
// postal-circle prefix) and says which — a prefix guess is labelled, never passed off as exact.
let _zs = { page: 0, size: 200, total: 0, states: null, statesAt: 0 };
function zmTab(tab) {
    document.querySelectorAll('.zm-tab').forEach(b => { const on = b.dataset.tab === tab; b.classList.toggle('border-indigo-600', on); b.classList.toggle('text-indigo-700', on); b.classList.toggle('border-transparent', !on); b.classList.toggle('text-slate-500', !on); });
    document.getElementById('zm-pane-mapping')?.classList.toggle('hidden', tab !== 'mapping');
    document.getElementById('zm-pane-state')?.classList.toggle('hidden', tab !== 'state');
    if (tab === 'state') { zsLoad(); zsDirStatus(); }
}
async function zsStates() {
    if (_zs.states && Date.now() - _zs.statesAt < 60000) return _zs.states;
    const d = await supFetch('/api/zone-mapping/states');
    _zs.states = d; _zs.statesAt = Date.now();
    const sel = document.getElementById('zs-state'); const cur = sel.value;
    sel.innerHTML = '<option value="">All states</option>' + (d.states || []).map(s => `<option value="${escapeHtml(s.state)}">${escapeHtml(s.state)} (${Number(s.pincodes).toLocaleString('en-IN')})</option>`).join('');
    sel.value = cur; ecSyncSelect(sel);
    const src = d.sources || {}, exact = (src.indiapost || 0), fromOrders = (src.orders || 0), nearest = (src.nearest || 0), prefix = (src.prefix || 0), notReal = (src.not_in_directory || 0), pending = Math.max(0, (d.total || 0) - exact - fromOrders - nearest - prefix - notReal);
    document.getElementById('zs-kpis').innerHTML = [
        zmTile('Pincodes in the sheet', Number(d.total || 0).toLocaleString('en-IN'), 'one row per destination'),
        zmTile('States', String((d.states || []).filter(s => s.state !== '(unknown)').length), 'as resolved for these pincodes'),
        zmTile('Verified by India Post', d.total ? Math.round(exact / d.total * 100) + '%' : '—', `${exact.toLocaleString('en-IN')} pincodes · ${fromOrders.toLocaleString('en-IN')} more from our order addresses (until India Post answers)`),
        zmTile('Derived (courier-only codes)', (nearest + prefix).toLocaleString('en-IN'), `${nearest.toLocaleString('en-IN')} from the nearest real pincode · ${prefix.toLocaleString('en-IN')} from the postal prefix${notReal ? ` · ${notReal.toLocaleString('en-IN')} unresolvable` : ''}${pending ? ` · ${pending.toLocaleString('en-IN')} resolving` : ''}`),
    ].join('');
    document.getElementById('zs-source-note').innerHTML = `Source per row, best first — <b>India Post</b>: the official directory (city, district, state). <b>our orders</b>: the state/city customers typed on orders to that pincode. <b>nearest real pincode</b>: the courier sheet lists a code India Post does not have (sheets pad ranges — 110000, 110100–110108 …), so the state and district are taken from the closest real pincode in the same 3-digit sorting district. <b>postal prefix</b>: state only, from the first digits, when no neighbour exists. A better source always replaces a weaker one.`;
    return d;
}
async function zsLoad() {
    const tbl = document.getElementById('zs-table'); if (!tbl) return;
    tbl.innerHTML = brandLoaderSm('Loading pincodes…');
    try {
        await zsStates();
        const qs = new URLSearchParams({ page: _zs.page, size: _zs.size });
        const st = document.getElementById('zs-state').value, zn = document.getElementById('zs-zone').value, q = document.getElementById('zs-q').value.trim(), pl = (document.getElementById('zs-place')?.value || '').trim();
        if (st) qs.set('state', st); if (zn) qs.set('zone', zn); if (q) qs.set('q', q); if (pl) qs.set('place', pl);
        const d = await supFetch('/api/zone-mapping/pincodes?' + qs.toString());
        _zs.total = d.total || 0;
        const TH = 'px-3 py-2.5 text-left text-[11px] font-semibold text-slate-400 uppercase tracking-wider border-b border-slate-200 bg-slate-50/60 whitespace-nowrap';
        const TD = 'px-3 py-2 text-sm text-slate-700 border-b border-slate-100';
        // Ranked by trust; every row says which one it came from.
        const SRC = { indiapost: ['India Post', 'bg-emerald-50 text-emerald-700'], orders: ['our orders (customer-typed)', 'bg-sky-50 text-sky-700'], nearest: ['nearest real pincode', 'bg-violet-50 text-violet-700'], prefix: ['postal prefix', 'bg-amber-50 text-amber-700'], not_in_directory: ['not an India Post pincode', 'bg-rose-50 text-rose-700'] };
        tbl.innerHTML = d.rows.length ? `<table class="w-full"><thead><tr>${['Pincode', 'City', 'District', 'State', 'Zone', 'Source'].map(h => `<th class="${TH}">${h}</th>`).join('')}</tr></thead><tbody>${d.rows.map(r => {
            const [sl, sc] = SRC[r.state_source] || ['resolving…', 'bg-slate-100 text-slate-500'];
            return `<tr class="hover:bg-slate-50"><td class="${TD} font-mono">${escapeHtml(String(r.pincode))}</td><td class="${TD}">${escapeHtml(r.city || '—')}</td><td class="${TD}">${escapeHtml(r.district || '—')}</td><td class="${TD}">${escapeHtml(r.state || '—')}</td><td class="${TD}"><span class="px-2 py-0.5 rounded-full text-[11px] font-semibold bg-indigo-50 text-indigo-700">Zone ${escapeHtml(r.zone || '?')}</span></td><td class="${TD}"><span class="px-2 py-0.5 rounded-full text-[11px] font-semibold ${sc}">${sl}</span></td></tr>`; }).join('')}</tbody></table>`
            : '<div class="text-slate-400 text-sm p-6">No pincodes match.</div>';
        const from = _zs.total ? _zs.page * _zs.size + 1 : 0, to = Math.min(_zs.total, (_zs.page + 1) * _zs.size);
        document.getElementById('zs-count').textContent = `${_zs.total.toLocaleString('en-IN')} pincode${_zs.total === 1 ? '' : 's'}${st ? ' · ' + st : ''}${zn ? ' · zone ' + zn : ''}${pl ? ' · ' + pl : ''}${q ? ' · starts with ' + q : ''}`;
        document.getElementById('zs-page').textContent = _zs.total ? `${from.toLocaleString('en-IN')}–${to.toLocaleString('en-IN')}` : '';
        document.getElementById('zs-prev').disabled = _zs.page === 0; document.getElementById('zs-next').disabled = to >= _zs.total;
    } catch (e) { tbl.innerHTML = `<div class="text-rose-500 text-sm p-6">${escapeHtml(e.message)}</div>`; }
}
// The download is a fetch with the bearer token, never an <a href> (a link carries no headers and
// saves the 401 body as a file). Exports the FULL filtered set server-side, not the page on screen.
async function zsExport() {
    const btn = document.getElementById('zs-export'); const label = btn.textContent; btn.disabled = true; btn.textContent = 'Preparing…';
    try {
        const qs = new URLSearchParams();
        const st = document.getElementById('zs-state').value, zn = document.getElementById('zs-zone').value, q = document.getElementById('zs-q').value.trim(), pl = (document.getElementById('zs-place')?.value || '').trim();
        if (st) qs.set('state', st); if (zn) qs.set('zone', zn); if (q) qs.set('q', q); if (pl) qs.set('place', pl);
        const r = await fetch('/api/zone-mapping/pincodes.xlsx?' + qs.toString(), { headers: getAuthHeaders() });
        if (!r.ok) { let msg = `Export failed (${r.status})`; try { const j = await r.json(); if (j && j.error) msg = j.error; } catch (_) {} throw new Error(msg); }
        const blob = await r.blob(); if (!blob.size) throw new Error('The server returned an empty file.');
        const cd = r.headers.get('Content-Disposition') || ''; const m = cd.match(/filename="([^"]+)"/);
        const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = m ? m[1] : 'zone-state.xlsx'; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(a.href), 5000);
        showNotification(`Downloaded ${_zs.total.toLocaleString('en-IN')} pincodes`);
    } catch (e) { showNotification(e.message, 'error'); }
    finally { btn.disabled = false; btn.textContent = label; }
}


// ═══════════════ AGENT LEARNING — the self-learning voice agent (2026-08-28) ═══════════════
// Reads /api/support/agent-learning/summary: every saved call reviewed by the AI (scores, outcome,
// issues), the LESSONS distilled from them (active / proposed / retired, with before-vs-after numbers),
// and the learning runs. Lessons can be activated, retired, edited, or taught by hand — every change
// reaches the next call within five minutes (the prompt block is cached that long on the server).
let _sal = { data: null, charts: {}, wired: false, filter: '', sort: 'seen',
  // Agent Learning keeps its OWN date range (user, 2026-09-02: "remove preset and make date filter
  // workable") — the shared preset widget updated a hidden state without refreshing the inputs, so
  // the dates on screen and the data never matched. Default: last 7 days; remembered per browser.
  rangeSel: '7',
  range: (() => { try { const r = JSON.parse(localStorage.getItem('sal.dateRange')); if (r && r.from && r.to) return r; } catch (_) {}
    const d = new Date(), f = new Date(d.getFullYear(), d.getMonth(), d.getDate() - 7);
    return { from: _ymd(f), to: _ymd(d) }; })() };
try { const r = JSON.parse(localStorage.getItem('sal.dateRange')); if (r && r.sel) _sal.rangeSel = r.sel; } catch (_) {}
function salRenderRange(){
  const el=document.getElementById('sal-range'); if(!el) return;
  // Quick ranges kept, placeholder "Presets" option dropped (user, 2026-09-02: "remove only preset
  // option — other filter required along with custom date"). Picking a range also UPDATES the visible
  // date inputs (the old shared widget's bug: dates on screen never matched the data); a manual
  // Apply flips the dropdown to Custom.
  el.innerHTML=`<div class="flex items-center gap-2 flex-wrap">
    <select class="filter-select sal-preset">
      <option value="custom" ${_sal.rangeSel==='custom'?'selected':''}>Custom</option>
      <option value="0" ${_sal.rangeSel==='0'?'selected':''}>Today</option>
      <option value="7" ${_sal.rangeSel==='7'?'selected':''}>Last 7 days</option>
      <option value="14" ${_sal.rangeSel==='14'?'selected':''}>Last 14 days</option>
      <option value="30" ${_sal.rangeSel==='30'?'selected':''}>Last 30 days</option>
      <option value="90" ${_sal.rangeSel==='90'?'selected':''}>Last 90 days</option>
    </select>
    <span class="sal-custom items-center gap-2 ${_sal.rangeSel==='custom'?'flex':'hidden'}">
      <input type="date" class="filter-input sal-from" value="${_sal.range.from}"><span class="text-slate-400">→</span>
      <input type="date" class="filter-input sal-to" value="${_sal.range.to}">
      <button class="filter-btn sal-apply-range">Apply</button></span></div>`;
  const save=()=>{ localStorage.setItem('sal.dateRange',JSON.stringify({..._sal.range,sel:_sal.rangeSel})); };
  const custom=el.querySelector('.sal-custom');
  el.querySelector('.sal-preset').addEventListener('change',e=>{
    const v=e.target.value;
    // the date inputs appear ONLY for Custom (user, 2026-09-02) — a quick range needs no dates on screen
    if(v==='custom'){ _sal.rangeSel='custom'; custom.classList.remove('hidden'); custom.classList.add('flex'); return; }
    custom.classList.add('hidden'); custom.classList.remove('flex');
    const d=new Date(), f=new Date(d.getFullYear(),d.getMonth(),d.getDate()-(+v));
    _sal.range={from:_ymd(f),to:_ymd(d)}; _sal.rangeSel=v; save();
    el.querySelector('.sal-from').value=_sal.range.from;
    el.querySelector('.sal-to').value=_sal.range.to;
    salLoad();
  });
  el.querySelector('.sal-apply-range').addEventListener('click',()=>{
    const f=el.querySelector('.sal-from').value, t=el.querySelector('.sal-to').value;
    if(!f||!t) return showNotification('Pick both dates',true);
    if(f>t) return showNotification('The From date is after the To date',true);
    _sal.range={from:f,to:t}; _sal.rangeSel='custom'; save();
    el.querySelector('.sal-preset').value='custom';
    salLoad();
  });
}
const SAL_CAT_LABEL = { opening: 'Opening', screening: 'Call screening', confirmation: 'Confirmation', language: 'Language', tone: 'Tone', objection: 'Objections', closing: 'Closing', other: 'Other' };
const SAL_OUT_LABEL = { confirmed: 'Confirmed', cancelled: 'Cancelled', reattempt: 'Re-attempt', no_answer: 'No answer', unclear: 'Unclear', other: 'Other' };
const SAL_OUT_COLOR = { confirmed: '#10b981', cancelled: '#f43f5e', reattempt: '#f59e0b', no_answer: '#94a3b8', unclear: '#a78bfa', other: '#cbd5e1' };
// ── Call Insights (2026-09-02): counted rule-compliance on the left, an evidence-led AI audit of
