    custom.classList.add('hidden'); custom.classList.remove('flex');
    const d=new Date(), f=new Date(d.getFullYear(),d.getMonth(),d.getDate()-(+v));
    _sci.range={from:_ymd(f),to:_ymd(d)}; _sci.rangeSel=v; save();
