  const tabBtn=(k,l)=>`<button class="infd-tab px-3.5 py-2 text-sm font-semibold rounded-lg ${_infDetTab===k?'bg-indigo-600 text-white':'text-slate-500 hover:bg-slate-100'}" data-tab="${k}">${l}</button>`;
